window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[17]=[{"i":40500,"n":"צאבח, אברהם ממוגאדור-מרוקו","b":"מו\"ץ במוגאדור-מרוקו."},{"i":40501,"n":"צאבח, אליהו","b":"מחכמי מוגאדור(מרוקו)"},{"i":40502,"n":"צאבח, יהודה מרבאט-מרוקו","f":"יעיש","b":"מו\"ץ בארבאט-מרוקו-שנות ה-תק'-תר'."},{"i":40503,"n":"צאבח, יצחק","b":"בא מארץ המערב,מרביץ תורה,דיין בירושלים-ת\"ג"},{"i":40504,"n":"צאבח, מאיר מצפרו","b":"מו\"ץ בצפרו, חתם-תקעה על פס\"ד עם ר שלמה אביטבול, ועם ר\"פ ן עטר, ור שמואל ן זמרא."},{"i":40505,"n":"צאבח, משה מארבאט","b":"מחכמי ארבאט-שנות ה-התק'."},{"i":40506,"n":"צאבח, משה מצפרו","b":"מחכמי צפרו-מרוקו, חתם על פס\"ד-תפב עם ר יהודה הרוש."},{"i":40507,"n":"צאבח, שמואל ממרוקו","b":"מגדולי רבני המערב הפנימי-מרוקו"},{"i":40508,"n":"צאדיקאריו, אברהם ראובן משלוניק","dt":"תקלט","dp":"שלוניקי","b":"גביר בשלוניקי. נהרג עק\"ה-תקלט."},{"i":40509,"n":"צאהלין, אליהו מגרוסורדין","f":"משה גרשון מפינטשוב","k":"בעל מענה אליהו","bt":"תעו","bp":"ירוסלב-גליציה","dt":"תקמו - יח ניסן","dp":"באטורקעס","b":"הגיע מגליציה, נדד בפולין וגרמניה, והתפרנס מהוראת בני גבירים. רב בגרוסורדין-תקכו-לה ועזב בגלל מחלוקת-תקלו, עבר לבטורקס(=באטור-קעסי)-הונגריה, ור נפתלי צבי ליפכוביץ על מקומו אחריו.. חיבר גם \"הדרת אליהו\", ועוד."},{"i":40510,"n":"צאהלין, שמואל אריהליב","f":"אליהו צאהלין","b":"רב בבאטורקעס-תק\"ס"},{"i":40511,"n":"צאהרי, שמואל מירושלים","k":"בעל השכל וידוע","bt":"תרנד","bp":"ירושלים","dt":"תשיח - אחרי","dp":"[ירושלים]","b":"מחכמי ירושלים, מיסד \"אגודת שבט ישראל\"-תשב שעסקה בעניני התרת עגונות ועוד. הקים את ישיבת \"תפארת בחורים\" בשיטת הרמבם. חיבר גם \"רגשי הדת\", \"מחנים\" - בענין טריפות, ועוד."},{"i":40512,"n":"צאחין, שאול מירושלים","bp":"ארם צובא?","b":"מחכמי ירושלים, ר יעקב עמדן מספר בשם ר משה בן חביב אודות שלשה חכמים שלא האמינו בשבתי צבי בהיותו בירושלים - ר שאול הינו אחד מהם."},{"i":40513,"n":"צאלח הלוי מביירות","b":"מחכמי ביירות-לבנון. תשובות ממנו ב\"ישכיל עבדי\"."},{"i":40514,"n":"צאלח יחיא בן יוסף","bt":"1725","dt":"ה'תקסו 1806","bk":[["זבח תודה",""],["פעולת צדיק",""],["שערי קדושה",""]]},{"i":40515,"n":"צאלח מבגדד","f":"סולימן","b":"רב בבגדד-שנות ה-ת'."},{"i":40516,"n":"צאלח מתימן - מהר\"ץ","f":"יחיא","k":"בעל פרי צדיק","bt":"תרה","bp":"צנעא","b":"תלמיד ר שלום צבטאני. ראש השוחטים ודיין בצנעא ומלמד תלמידים. נכדו המהרי\"ץ. חיבר גם ספר הבדיקות, והגהות לשו\"ע."},{"i":40517,"n":"צאלח, אברהם מצנעא","bt":"תקצג","dt":"תרסה - כו אייר","b":"דיין בצנעא"},{"i":40518,"n":"צאלח, אברהם מקושטא","b":"מחכמי קושטא-שפ. סייע לר\"ש יפה בהדפסת \"יפה תואר\" לבראשית."},{"i":40519,"n":"צאלח, אברהם מקושטא","f":"שבתי","b":"רב בפטרץ, ארטא-יון, מגדולי דורו-קושטא-שפ. הו\"ל \"משפטי שמואל\" לר שמואל קלעי-שנט."},{"i":40520,"n":"צאלח, יחיא מתימן","k":"מהרי\"ץ","bt":"תצ-תק - בערך","b":"תלמיד סבו-מרי צלאח, ר אהרן הכהן עראקי, ר יחיא עראקי, ר דוד משרקי בעל שתילי זיתים. מגדולי חכמי תימן, רב בצנעא וכל ערי המדינה-תקמ. חיבר עץ חיים, זבחי תודה, פעולת צדיק."},{"i":40521,"n":"צאלח, משה יחזקאל מבגדד","f":"יחזקאל","k":"בעל פני משה","bt":"תרנו","bp":"בגדד","dt":"תשכו - י טבת","b":"תלמיד המקובל ר משה פתיה, ור שמעון אגסי. לימד ב\"בית זלכה\" בבגדד, ראש ביהמ\"ד \"מנדאני\"-תשד. עלה לארץ-תשיא וכיהן כרב בנחלת יהודה. חיבר גם \"ויקהל משה\", \"בגדי ישע\" ועוד. ונדפסו ירושלים תשמט."},{"i":40522,"n":"צאלח, עבודי מבגדד","b":"רב בבגדד - בשכונת ג'אמוסין."},{"i":40523,"n":"צ'אני, ברוך ממצרים","b":"מגדולי חכמי מצרים בדורו של החיד\"א שפגשו במצרים, מעמיק גדול, סגי נהור, רב בנא אמון(=אלכסנדריה)-תקל"},{"i":40524,"n":"צאפרט, ישראל מפרשבורג","b":"מראשי קהלת פרשבורג-תקמג."},{"i":40525,"n":"צאפת ן, דוד הלוי","b":"מרבני סאלי-תרמ\"ז"},{"i":40526,"n":"צארום, אברהם מתימן","f":"סעדיה","bt":"תרלז","bp":"ג'בל חרג'-תימן","b":"עלה לארץ-תרנז והתישב ביפו, מ זכיר וחבר ועד עדת התימנים בירושלים-תרסט, ומנהל הסיוע לקהלת התימנים של הועד האמריקאי, פעיל ציבור. יסד את שכונת \"מחנים\"-תרפג."},{"i":40527,"n":"צארום, יחיא יהודה","k":"בעל זרוע השלום","b":"מחכמי תימן,רב בצנעא-תר\"י"},{"i":40528,"n":"צארום, יחיא מירושלים","f":"יוסף","bt":"תרג","bp":"צנעא","dt":"תרעז - א-ו ניסן","dp":"ירושלים","b":"מחכמי תימן, עלה לירושלים-תרמד וכיהן כרב העדה התימנית על מקום ר יוסף עראקי. מחכמי \"בית אל\", ו\"רחובות הנהר\". אחיו ר סעיד מקובל בירושלים."},{"i":40529,"n":"צארום, משה מתימן","f":"יוסף","k":"בעל לקוטי שושן","bt":"תרלה","bp":"יאפיר-תימן","dt":"תשיא - כו אלול","b":"תלמיד ר נסים אלחריזי, ר דוד רצאבי. עלה לארץ-תשי והתישב בכרכור. פרסם קונטרס בדבר מנהג תימן בענין החזרה על \"ה' אלוקיכם אמת\"."},{"i":40530,"n":"צארום, נחמן","b":"עלה לארץ, והיה פועל במושבות, פעיל ציבור-תרצא והתישב בתל אביב."},{"i":40531,"n":"צארום, נתן מתימן","f":"חלקיה","b":"מחכמי צנעא - סוף המאה ה-19, וחתם עם חכמי צנעא על שו\"ת חכמי ראדע ועדן בנושא קריאה בתורה פעמיים או שלוש."},{"i":40532,"n":"צארום, סעיד מירושלים","b":"מקובל מחכמי ירושלים. אחיו של ר יחיא הראב\"ד לעדת התימנים בירושלים."},{"i":40533,"n":"צארום, שלום מתימן","f":"יוסף","bt":"תרג","bp":"צנעא","dp":"ירושלים","b":"מחכמי תימן, עלה לירושלים-תרמב עם קבוצה של עולים מתימן, והיה מחכמי ירושלים וסופר סתם."},{"i":40534,"n":"צארקעס, אליעזר","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":40535,"n":"צבאח, אברהם ממרוקו","f":"דוד - משכיל לדוד","b":"מחכמי מראקש-מרוקו."},{"i":40536,"n":"צבאח, אברהם ממרוקו וטבריה","b":"עלה לטבריה, שד\"ר-תרל\"ג, חזר למערב, אב\"ד ור\"מ במוגאדור-תרמ\"ד"},{"i":40537,"n":"צבאח, אליהו ממוגאדור-מרוקו","b":"מחכמי מוגאדור-מרוקו בשנות ה-תק'."},{"i":40538,"n":"צבאח, דוד","f":"מסעוד","k":"בעל שושנים לדוד","bt":"תרכט-יח אב","bp":"רבאט","dt":"תשטז","dp":"ירושלים","b":"למד תורה אצל אביו ואצל ר' רפאל אנקאווא, ספרא דדיינא, דיין ורב במאזאזאן(אלג'דידה)-תרפ\"ט, קניטה(פורט ליוטי), חזר לרבאטעלה לירושלים-תש\"ט, חיבר \"שושנים לדוד\""},{"i":40539,"n":"צבאח, דוד ממראקש","k":"בעל משכיל לדוד","dt":"תריט - י תשרי","dp":"מראקש","b":"מו\"ץ ומלמד תורה במראקש, יחד עמו הרבנים ר אלעזר חזאן, ר רפאל מסעוד ן מוחא, ר משה פינטו, ר יוסף אביטבול, ר שלם הכהן. חיבר \"משכיל לדוד\" ונכדו ר דוד הו\"ל - תרפד. בניו: ר ימין ור אברהם."},{"i":40540,"n":"צבאח, ימין ממראקש","f":"דוד","b":"מחכמי מראקש-שנות ה-תר'-תש'."},{"i":40541,"n":"צבאח, יצחק ממרוקו וירושלים","dt":"תח","dp":"ירושלים","b":"מחכמי צפון אפריקה, נכדו של ר שמואל צבאח, עלה לירושלים-שך, וכיהן כדיין כ-50 שנה, בשנת שכו, ו-שנז חתם על התקנה לשחרר תלמידי חכמים ממס. מוזכר ב\"חרבות ירושלים\" בין הסובלים בפרעות אבן פארוך."},{"i":40542,"n":"צבאח, מימון מפאס","dt":"תסד","dp":"פאס","b":"נהרג עק\"ה בידי מולאי חפיד בנו של מולאי איסמעיל."},{"i":40543,"n":"צבאח, מסעוד","f":"אלעזר","bt":"[תר]","bp":"רבאט","dt":"תרצא - כו אלול","b":"תלמיד ר דוד בן שמעון. עלה לירושלים. אביו של ר דוד בעל \"שושנים לדוד\"."},{"i":40544,"n":"צבאח, שמואל מספרד ופאס","b":"מחכמי ספרד, והגיע לפאס-מרוקו אחרי הגירוש, הסכים עם ר\"ש בן מסנות-רס בענין מנהג הנפיחה במרוקו, ונזכר ב\"עץ חיים\" לר חיים גאגין."},{"i":40545,"n":"צבאן, אברהם הכהן","f":"אהרן","bp":"דבדו","dt":"תרף","dp":"מליליה","b":"מו\"ץ במליליה-תרס\"ג"},{"i":40546,"n":"צבאן, בכור מטריפולי","f":"יצחק","bt":"תרע","dt":"תשם","b":"תלמיד ר ציון ביתאן. רב בבנגאזי, טריפולי. חיבר מילון בערבית-יהודית - בכת\"י."},{"i":40547,"n":"צבאן, סצ'יר","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":40548,"n":"צבאן, עמראן מאלגיר","f":"פרץ","bt":"תרמב","dt":"תשכד","b":"רב בגרדאייא-אלגיר ועסר במסחר, רב באפלו וחזר לגראדייא. הו\"ל קרוב\"ץ מנהג גרדאייא-גרבה תש, \"בארצות החיים\" גרבה תש, \"שבחי צדיקים\" גרבה תשח, \"חסדי אבות\" סוסה תרפו, ועוד. בספריו דאג לשמר את מורשת הקהלה."},{"i":40549,"n":"צבאן, רפאל כדיר מג'רבה","k":"בעל נפש חיה","bt":"תרע","bp":"ג'רבא","dt":"תשנה - ד כסלו","b":"מחכמי ג'רבא, תלמיד ר רחמים חי חיותה הכהן. חברו של ר מצליח מאזוז. ר\"מ בישיבה בג'רבא. עלה לארץ וכיהן כרב בנתיבות. נשיא ישיבת \"כסא רחמים\". חיבר גם \"זרע יעקב\", \"שיירי הנפש\" ועוד. הו\"ל \"הירח\" - ג'רבה תשח."},{"i":40550,"n":"צבאן, שלמה הכהן ממרוקו","f":"יוסף","k":"הרש\"ך - בעל לך שלמה","bt":"תרמא","bp":"דברו","b":"תלמיד זקנו ר אהרן הכהן, ור דוד הכהן בן אזהור. רב בדברו-מרוקו-תרעא, דיין במאזאגן-תרפה, רב מטעם הממשלה הצרפתית במאזאגן-תרפו, דברו-תרפט, אזמור-תרצו, מאזאגן-תש, ראב\"ד באוג'דה-תשה. חיבר גם \"ויחל שלמה\" - אודות השתלשלות הרבנות בדברו-מרוקו, \"ויאסוף שלמה\", \"מעלות לשלמה\". תשובות ממנו ב\"שושנים לדוד\" לר דוד צבאח. חיבר \"יחס דוברו\" המתאר את תולדות קהילת דברו מזמן גירוש סביליה-קנא, ויחוס משפחות כהנים שם ונדפס בספרו של ר שמואל יוסף ן נאים."},{"i":40551,"n":"צבאן, שמעון מאלגיר","bt":"תרל","dt":"תש - בערך","b":"מחכמי ווהראן. הו\"ל \"סדר לארבע מיתות בית דין\" על פי קבלה מקדמונים."},{"i":40552,"n":"צבטאני, שלום מתימן","f":"חיים","bt":"[ת]","dt":"תעה","dp":"צנעא","b":"רב בתימן לאחר גלות מוזע-תרם. דיין בצנעא-תן אצל ר זכריה הכהן עם חברו ר משה בן סעדיה קטיעי. נזכר אצל המהרי\"ץ שמביא כמה הלכות ממנו בספריו. תלמידו ר צאלח בן יחיא."},{"i":40553,"n":"צבי","f":"מאיר מפרמישלן - הנכד","dt":"כא אייר","dp":"גוואדזיץ","b":"ממשפחת אדמורי פרמישלן. חתן קרובו ר אהרן מבאריטשוב, נסע לר יהודה צבי מסטרטין. נפטר בחיי אביו האדמור מפרמישלן."},{"i":40554,"n":"צבי (יחיאל מיכל) סגל מקלוש","b":"חתן ר יצחק בלוי. עלה לצפת-תרה בהוראת ר מאיר מפירימישלן. עבר לירושלים ולמד בישיבת תורת חיים כ-65 שנה. הניח כתבים (חלקם פורסמו בעתון \"המודיע\")."},{"i":40555,"n":"צבי (פישל) אשכנזי","f":"אפרים פישל מבריסק","b":"נכד(-אבי אמו) המהרש\"ל?, רב-שץ. בנו - ר אפרים פישל מלבוב. אחיינו - החכם צבי."},{"i":40556,"n":"צבי - משפחה באשכנז","b":"השם צבי בא בשני אופנים, א. ר\"ת - צדיק באמונתו יחיה, ב. שם משפחה ואז הופיע \"מגזע צבי\" - ומשפחה זו מצאצאי ר נפתלי הרץ טריווש בן אליעזר - ש\"ץ ואב\"ד בפפד\"מ-שנות הש' - בעל פירוש ע\"פ הקבלה לתפלות - טיהנגן שך - כאשר אחד מצאצאיו שעבר לפולין שינה שמו להירש (על שם אביו - הירץ) ולבסוף לצבי, עוד משפחות שנסתעפו ממנו: טריבש, טרעפעש, דרייפוס."},{"i":40557,"n":"צבי אלימלך מגרודזיסק","b":"רב בגרודזיסק."},{"i":40558,"n":"צבי אריה הכהן ממעזיבוז","dt":"תקצ - ה טבת","b":"רב במזיבוז"},{"i":40559,"n":"צבי אריה מאילוקסט","f":"אלימלך ואנש מאילקוסט","b":"שו\"ב באילוקסט-תרמו על מקום אביו."},{"i":40560,"n":"צבי אריה מזבנא","b":"רב בזבנא."},{"i":40561,"n":"צבי אריה מטויסט","b":"רב בטויסט."},{"i":40562,"n":"צבי אריה מלוייא","b":"רב בלוייא"},{"i":40563,"n":"צבי אריה מסיגט","f":"פרנקל, צבי אריה מסיג","b":"רב באיטליה. תשובותיו בספרי חכמי דורו - ובהם \"יד חרוזים\"-תס - ובו מספיד את תלמידו - ר גרשום חפץ."},{"i":40564,"n":"צבי בנימין זאב מזברז","f":"המגיד מזלוטשוב","k":"אדמור מזברז","dt":"תקפב","dp":"וולוטשיסק","b":"רב בזברז. חיבר \"תפארת צבי זאב\" למברג תרנו, \"רדין דאוריתא\" וארשא תרסג.","bk":[["תפארת צבי",""],["רזין דאורייתא (זבאריז')",""]]},{"i":40565,"n":"צבי דב מטיקטין וירושלים","b":"חתם-תרכב עם ראשי הכוללות בירושלים על כתב שליחות ר נתן נטע נאטקין."},{"i":40566,"n":"צבי דב מפרשבורג","f":"מיכאל ליב","b":"מחכמי פרשבורג, חתם-תקכח על תקנות ר מאיר ברבי."},{"i":40567,"n":"צבי דוב מפרשבורג","b":"דומ\"צ בפרשבורג-תק\"ל"},{"i":40568,"n":"צבי הירש","b":"רב-שנת ת\"ק"},{"i":40569,"n":"צבי הירש","f":"נחום גאון","b":"רב-שנת ת\"צ"},{"i":40570,"n":"צבי הירש","f":"ניסן","k":"בעל תפארת צבי","b":"חיבר \"תפארת צבי\" - אמשטרדם תקטו."},{"i":40571,"n":"צבי הירש (טאוב)","f":"שלמה זלמן-תלמיד הבעש","r":"המגיד מנדבורנא, ומקודם בדאלינא","bt":"תצז בערך","dt":"תקסד","dp":"פרגא-וורשא","b":"אביו של האדמור ר יחזקאל טאוב מקוזמיר.","bk":[["תשע שיטות",""],["צמח ה' לצבי - עה\"ת , אבני חפץ - ש\"ס",""],["אבני חפץ - ש\"ס",""],["צמח ה' לצבי - עה\"ת",""]]},{"i":40572,"n":"צבי הירש (לוין) מלונדון וברלין","f":"אריה ליב מאמשטרדם","k":"הצב\"א -בעל צבי לצדיק","r":"מגיד בוואיידסלוב, אביו של ר' בונים מפרשיסחא","bt":"תפא","bp":"רישא","dt":"תקס - ד אלול","dp":"ברלין","b":"אחיו של ר שאול מאמשטרדם. מגדולי חכמי דורו, ר\"מ בגלוגא, רב בלונדון-תריז, הלברשטט-תקכג, מנהיים-תקל, אב\"ד וראש ישיבה בברלין-תקלב על מקום ר אהרן מגזע צבי שעבר לאנשבך (וזכה בבחירות ראשי הקהל כנגד ר רפאל בן יקותיאל זיסקינד בעל \"תורת יקותיאל\" - מצאצאי בעל הלבוש שנתמך בידי קרוביו בני משפחת יפה). בזמן מחלוקת היעב\"ץ-אחי אמו לבין ר יהונתן איבשיץ - היה מתומכי היעב\"ץ, ושלח מכתבים מגלוגא לרבני אשכנז ופולין ודבריו היו בעלי השפעה רבה, אולם כאשר ר יחזקאל לנדא בעל \"נודע ביהודה\" שלח מכתב לר אשר למיל הלוי רבה של גלוגא ובה הצעת פשרה שיתחייב ר יהונתן שלא לכתוב יותר קמיעות, ואז הצטרף ר צבי הירש להצעת ה\"נודע ביהודה\" וכתב מכתב לאביו על כך, ואביו הסכים עמו וכתב מכתב ליעב\"ץ ובו מיעץ לו להיענות להצעה, והיעב\"ץ שלח מכתב לר צבי הירש ובו דוחה את ההצעה ומבקר אותו על הצעתו. תרגם לעברית \"השמים והעולם\" לאריסטו - ושלחו למנדלסון כמשלוח מנות בפורים. הסכים על תרגום התנ\"ך למנדלסון, ולבקשת המלך פרידריך ביקש ממנדלסון לכתוב את תמצית דיני ממונות בגרמנית ונדפס בשם \"ריטואלגעזעטצע דער יודען\". היה במחלוקת עם נפתלי הירץ ויזל על מכתבו \"דברי שלום ואמת\" בענין התערבות בחינוך ילדי ישראל באוסטריה, וגם היה במחלוקת כנגד הספר \"מצפה יקותיאל\" (שכתב בנו ר שאול בעילום שמו) שיצא כנגד ר רפאל הכהן וספרו \"תורת יקותיאל\" ותומכיו דוד פרידלנדר וגיסו ר איצק בן דניאל יפה. בניו: ר שאול מפפד\"א בעל \"בשמים ראש\" ו\"מצפה יקותיאל\", ר שלמה מפרענצלויא, ר טעבלי. חתנו - אחיינו ר יעקב בן שאול מאמשטרדם. חתם שמו - \"הצב\"א\".","bk":[["ארץ צבי - דרושים",""],["עשרה למאה - דרוש",""],["תירוש ויצהר",""]]},{"i":40573,"n":"צבי הירש (מרגליות) מיזלוביץ","f":"ראה: מרגליות, צבי הי"},{"i":40574,"n":"צבי הירש אריה ליב מזאגראווע וי","dt":"תרכז - כו כסלו","b":"רב בזאגראווע,עלה לירושלים"},{"i":40575,"n":"צבי הירש אשכנזי מבורשטין","b":"רב בבורטשין-תקכא, אחיו ר אפרים מברודי. חתן ר אברהם משה מזורובנא. חתנו ר מרדכי זיסקינד לנדא על מקומו אחריו."},{"i":40576,"n":"צבי הירש אשכנזי מטבריה","dt":"תקסח - כט אב","dp":"טבריה","b":"מחסידי טבריה."},{"i":40577,"n":"צבי הירש בעש\"ט מטבריה","b":"עלה לארץ-תקלט, בשליחות-תקמו."},{"i":40578,"n":"צבי הירש בר מגרבוביץ","b":"מראשי ה\"חבורה\" בקוצק ונחשב לדמות מופת אצל חסידי קוצק ורבו אמר עליו \"ראוי הוא להיות אדמור לאלפים\"."},{"i":40579,"n":"צבי הירש ברל'ס מבריסק","f":"מרדכי","k":"בעל אור הצבי","dt":"תרמג - א כסלו","dp":"בריסק","b":"רב בבריסק. מחותן עם ר פנחס מיכאל רוקח מאנטפליא."},{"i":40580,"n":"צבי הירש בר\"ן מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":40581,"n":"צבי הירש גרשון מסורוקא","dt":"תקצא","dp":"בוטישאן","b":"תלמיד ר חיים מטשרנוביץ, וסידר ספרי רבו לדפוס."},{"i":40582,"n":"צבי הירש דוד הלוי משברשין","f":"יצחק אב\"ד קראקא","dt":"תקצב - יד טבת","dp":"קראקא","b":"מצאצאי הקדוש ר יהושע רייציס (מצד אביו), נכד-(אבי אמו) ר אריה ליב מלבוב ואמשטרדם. מתנגד לחסידות. רב בשברשין, קראקא על מקום אביו (למעשה ביניהם נבחר בינתים ר שלמה זלמן מוארשא - שלא אושרה בחירתו בידי השלטון?). (בשם הגדולים החדש מופיע שם אביו - יהודה ליב במקום יצחק). נזכר במגילת איבה בידי המו\"ל ר משה קערנר."},{"i":40583,"n":"צבי הירש הכהן מאוסטרהא","f":"עקיבא","dt":"תנג - טז אייר","dp":"אוסטרהא","b":"מחכמי וגדולי אוסטרהא."},{"i":40584,"n":"צבי הירש הכהן מדאלטיש וירושלים","f":"יוסף","dt":"תקצט - ו ניסן","dp":"ירושלים","b":"מראשי כולל הפרושים בירושלים, חתם-תקצו על שטר משכנתא מהכולל לר מרדכי מינסקר."},{"i":40585,"n":"צבי הירש הכהן מויסלוביץ","f":"זאב וואלף הכהן","b":"רב בווייסלוביץ-ת\"ק"},{"i":40586,"n":"צבי הירש הכהן מטיקטין","f":"אריה ליב מטיקטין","b":"רב בטיקטין על מקום אביו."},{"i":40587,"n":"צבי הירש הכהן מניו יורק","k":"בעל גנזי דרשות","b":"רב בניו יורק."},{"i":40588,"n":"צבי הירש הכהן מסניאטין","b":"רב בסניאטין."},{"i":40589,"n":"צבי הירש הכהן מפאטיק","b":"רב בפאטיק-תקפ\"ח"},{"i":40590,"n":"צבי הירש הכהן מקומרנא","f":"נתן","dt":"תקטז - ו אב","dp":"לבוב","b":"רב בקומרנא."},{"i":40591,"n":"צבי הירש הכהן מקראקא","dt":"תה - כו אלול","b":"דרשן בקראקא"},{"i":40592,"n":"צבי הירש הכהן מקרוטושין","f":"רפאל הכהן","b":"רב בקראטשין-תק\"ע"},{"i":40593,"n":"צבי הירש הלוי מאוסטרהא","f":"שאול","k":"ר הירשקי ר שמואלקס","dt":"תקמט - יג טבת","dp":"אוסטרהא","b":"מגדולי חכמי אוסטרהא - לא כיהן ברבנות, והלכו אליו גם רבני העיר ובהם רב ייבי ור אשר. צדיק, איש אמת, ועניו. כשהגיע ר יעקב שמשון משפטיוקע להשתדל למנוי רבו בעל \"תולדות יעקב יוסף\" לרב באוסטרהא ור צבי הירש התנגד ואמר \"הבעלי בתים מאוסטרהא לא יוכלו לסבול קפדנותו של הרב...\", ואכן לא נתקבל לרבנות."},{"i":40594,"n":"צבי הירש הלוי מאסאד","b":"רב באסאד-תק\"ל"},{"i":40595,"n":"צבי הירש הלוי מבריסק","f":"אלעזר סגל","b":"דיין בבריסק, חתם-שצט עם ר\"א אפשטין ור יוסף בן ליזר."},{"i":40596,"n":"צבי הירש הלוי מהרובשוב","b":"רב בהרובשוב"},{"i":40597,"n":"צבי הירש הלוי מוילנא","f":"ישכר בער","b":"דיין בוילנא, חתם-תפח עם ר יהודה ליב מטיקטין."},{"i":40598,"n":"צבי הירש הלוי מזולקוא","f":"רפאל","k":"בעל עבודת השיר","b":"מצאצאי ר יצחק מזסלב. חתן ר חיים-אחיו של ר יצחק איזיק מטרניגרד בן יהושע מטומשוב. ראב\"ד בזולקוא. חתם-תקם על תקנה בזולקוא. חיבר \"עבודת השיר\" - זולקוא תקלג."},{"i":40599,"n":"צבי הירש הלוי מטימישואר","b":"רב בטעמעשוואר-תק\"מ"},{"i":40600,"n":"צבי הירש הלוי מלבוב ופיורדא","f":"אהרן שלום","dt":"תיא - טז טבת","dp":"לבוב","b":"רב בכמה קהלות, אב\"ד ור\"מ בלבוב. (אולי אחיו - ר דוד בן אהרן שלום הלוי מלבוב)."},{"i":40601,"n":"צבי הירש הלוי מקופנהגן","dt":"תקלו - ד טבת","b":"רב בקופנהגן"},{"i":40602,"n":"צבי הירש הלוי מקרסניברד","dt":"תקנד - יא אדר","b":"רב בקראסניברד. נכדו - ר צבי הירש בן גדליה מזאמושט הו\"ל \"מציון תצא תורה\" - זאמושט תרפט."},{"i":40603,"n":"צבי הירש הלוי משקלוב","f":"מאיר הלוי","b":"רב בשקלאב"},{"i":40604,"n":"צבי הירש זלקינד","b":"גביר בליטא. מחותן עם - ר אבא סולוביציק מקובנא, ר אלכסנדר זיסקינד שחור מדוברובנא, ר יואל סירקין ממיר, ר יחזקאל לנדא-ראב\"ד וילנא."},{"i":40605,"n":"צבי הירש חריף מאוסטרהא","f":"ישראל חריף מלבוב","dt":"תצב - יג אב","dp":"אוסטרהא","b":"נכד ר פנחס משה מלבוב. דיין באוסטרהא. אולי אביו של ר יעקב יהודה יודיל חסיד מאוסטרהא."},{"i":40606,"n":"צבי הירש חריף מביאלה והלברשטט","f":"ראה: הלברשטט, צבי הי"},{"i":40607,"n":"צבי הירש חריף ממיטאוי","f":"דובער הקדוש","bp":"מיטאוי?","dt":"תקע - טז תמוז","dp":"מיטאוי","b":"מו\"ץ במיטאוי, טוקום?. הסכים על \"זבד טוב\", \"שפת הים\". בניו - ר משה ממיטאוי, ר יעקב ממיטאוי, ר אהרן ממיטאוי."},{"i":40608,"n":"צבי הירש חריף מנישוויז","f":"שלום","b":"רב בנעשוויז(=נשוויז)-ליטא-תרי. בנו - ר אברהם מפיקעלן ופוקרוי."},{"i":40609,"n":"צבי הירש יאיר מרייויץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":40610,"n":"צבי הירש יעקב מקאמלי","dt":"תקמז - ד אייר","b":"רב בקאמלי"},{"i":40611,"n":"צבי הירש כץ מלבוב","f":"אברהם","k":"ר' צבי הירש הקדוש","dt":"תכד - ו-י אייר","dp":"לבוב","b":"דיין בלבוב. נהרג עק\"ה."},{"i":40612,"n":"צבי הירש מאברניק","bt":"תקסד","dt":"תרלה - כט ניסן","b":"רב באברניק-תקצ\"ב"},{"i":40613,"n":"צבי הירש מאוסטרהא","f":"שמואל","dt":"תקמט - יג טבת","b":"תלמיד הבעשט. מראשי החסידים באוסטרהא. מקובל."},{"i":40614,"n":"צבי הירש מאוסטרהא","f":"יוסף יוזפא אוסטרר","b":"נכד ר שמואל ר יעקב'ס מאוסטרהא. פרנס באוסטרהא."},{"i":40615,"n":"צבי הירש מאטיניא","b":"רב באיטיניא"},{"i":40616,"n":"צבי הירש מאיבנוביץ","dt":"תקא","b":"רב באיבנוביץ,אייבשיץ,ביזנץ,קרומנוי,אונגריש-ברוד"},{"i":40617,"n":"צבי הירש מאמשטרדם","k":"בעל שבר פושעים","b":"רב באמשטרדם-תעד. חיבר \"שבר פושעים\" כנגד נחמיה חיון."},{"i":40618,"n":"צבי הירש מאנגליה","f":"שמעון מלעסלויא","k":"בעל מלחמות האמונה","b":"סופר מחכמי אנגליה - שנות ה-תק'-תר'. חיבר \"מלחמות האמונה ותשובת הנצחון\" בעברית ואנגלית - לונדון תקפב."},{"i":40619,"n":"צבי הירש מאסטרלנקע","b":"רב בסאקאלקא, אסטראלענקא. הסכים על חובת אדם לר אהרן למדן. אולי בנו - ר חיים נחום פלטרוביץ בעל תהלות חיים.."},{"i":40620,"n":"צבי הירש מאפשטני","b":"רב בהילדסהיים"},{"i":40621,"n":"צבי הירש מבוליחוב ואמשטרדם","b":"רב בבוליחוב. עבר לאמשטרדם ויש בביהמ\"ד של ר שאול אב\"ד אמשטרדם, חיבר ושם הדפיס - \"שרי צבי\" אמשטרדם תקכח בעילום שמו. חותנו זקנו היה השל\"ה."},{"i":40622,"n":"צבי הירש מבוסק","b":"חתן ר ישכר בער פאלק מפודהייץ-בנו של בעל פני יהושע (ויש חולקים על כך). רב בבוסק-תקמ. (ראה גם: ר צבי הירש בן משה מזולקוא ובוסק). (אצל בובר מופיע שהוא מחותן ר אברהם שרנצל והוא מחבר הספר \"גאון צבי\")."},{"i":40623,"n":"צבי הירש מבוצאץ","f":"משה","b":"מחכמי בוצאץ. מתורתו ב\"דברי אבות\"."},{"i":40624,"n":"צבי הירש מברוד","f":"יצחק ישכר בעריש","dt":"תקמט - כט תמוז","b":"רב פעלים,רב בברודי"},{"i":40625,"n":"צבי הירש מברוד וזולקוא","f":"מ' זאב","k":"בעל אור צבי","bt":"תנ","bp":"זולקוא","dt":"תקכו","dp":"ברודי","b":"רב בזולקוא, אוסציא-תקז, גוליגור, ראה ישיבה בברודי-תק. רוב חדושיו אבדו בשריפה. חיבר \"אור צבי\" למברג תרלה. מחותן עם בעל פני יהושע."},{"i":40626,"n":"צבי הירש מברודא","b":"רב בברודא-ת\"ק"},{"i":40627,"n":"צבי הירש מברודשין","b":"מחכמי ברודשין - מתורתו ב\"כרם החסידות\"."},{"i":40628,"n":"צבי הירש מבריסק","f":"משה יעקב","b":"רב בבריסק. נזכר ב\"בית יעקב\" לר יעקב צוזמיר. חתם-תכד בפנקס ליטא. נזכר ב\"זרע אברהם\", הסכים על \"עמודיה שבעה\" לר בצלאל מסלוצק. תלמידו - ר הלל בעל \"בית הלל\"."},{"i":40629,"n":"צבי הירש מברעזן","f":"חיים","b":"רב בברעזאן(=ברזאן), דרוהוביטש, ברודי, ליסקא-תפ."},{"i":40630,"n":"צבי הירש מגוליגור","b":"מחכמי גוליגור - תשובה אליו בשו\"מ."},{"i":40631,"n":"צבי הירש מגלוגא","b":"אב\"ד גלוגא(=גלוגוב?) - שנות ה-תק', נזכר ב\"נודע ביהודה\"."},{"i":40632,"n":"צבי הירש מגלינא","f":"דוד מבאליק","k":"זמישטשער מגיד","b":"רב ומגיד בגלינא ושאר קהילות. חיבר \"משיבת נפש\" זולקוא תקלה, ועוד."},{"i":40633,"n":"צבי הירש מגריידינג","f":"מנחם מנדל","dp":"קומרנא","b":"דברי תורה ממנו ב\"קישוטי כלה\"."},{"i":40634,"n":"צבי הירש מדובנא","f":"עוזר","b":"חתן ר אברהם חיים שור מסטנוב. רב בדובנא-שע על מקום ר שמואל בן אהרן הורביץ, ור מאיר כץ על מקומו אחריו. חיבר הקדמה לספר חותנו \"תורת חיים\". נזכר בתשובות גאונים בתראי שאלה ששאל את בעל הב\"ח שהיה מחותנו."},{"i":40635,"n":"צבי הירש מדובנא","b":"חתן השר ר שאול וייל."},{"i":40636,"n":"צבי הירש מדוברומיל-ראדומישל","f":"יהודה","k":"בעל גאון צבי","dt":"תקנא - בערך","dp":"רישא","b":"נכד המג\"ש. חתן ר אברהם מדוברומיל - אחי הפני יהושע. רב בדוברומיל(=ראדמישלא) על מקום חותנו, רב ברישא. חיבר \"גאון צבי\" וארשא תקסא, ועוד."},{"i":40637,"n":"צבי הירש מדומברובה","b":"רב בדומברובה-תק\"ס"},{"i":40638,"n":"צבי הירש מדיסנא","b":"חתן הגר\"א מוילנא. בנו - ר יצחק, נכדו - ר אליהו צבי רינחין."},{"i":40639,"n":"צבי הירש מדלטין","f":"משה מראהאטין","dt":"תקצג - יא סיון","b":"רב בדעלאטין(=דלטין). תלמיד ר צבי הירש מנדבורנא. אדמור משנת תקסב. י\"א שנפטר - א טבת תקפא."},{"i":40640,"n":"צבי הירש מהוצפלאץ","b":"רב בהוצפלאץ-תק\"מ"},{"i":40641,"n":"צבי הירש מהורודוק ומינסק","f":"ישראל","dt":"תרי - כג אייר","dp":"מינסק","b":"מו\"צ בהורודוק."},{"i":40642,"n":"צבי הירש מהורוקא","f":"אברהם","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":40643,"n":"צבי הירש מהיינספורט","b":"ש\"ץ ונאמן קהלת היינספורט-תקלד (באותו הזמן לא היה רב בהיינספורט והיתה תחת הרב מולרשטיין)."},{"i":40644,"n":"צבי הירש מהילדסהים","f":"אביגדור","b":"רב בהילדסהיים-תקי. חתניו - ר צבי הירש מירלש משווערין, ר יהושע הורביץ."},{"i":40645,"n":"צבי הירש מהלברשטט","b":"רב בהלברשטט-שנות ה-ת'. תשובה ממנו ב\"מקום שמואל\", \"סדרי טהרה\", נזכר גם ב\"צלעות הבית\" לר מאיר פוזנר, ו\"קול יהודה\". תלמידו - ר מאיר ברבי."},{"i":40646,"n":"צבי הירש מואדיסלב","f":"יהודה ליב","k":"בעל עשרה למאה","b":"חתן ר בצלאל מזולקוא בעל \"בשם בצלאל\". אביו של שמחה בונם מפשיסחא. מגיד, דרשן, מג\"מ בוויידיסלאב-תקנ. חיבר גם \"ארץ הצבי\"."},{"i":40647,"n":"צבי הירש מוארשא","dt":"תרא - יז אייר","b":"דיין בוורשה"},{"i":40648,"n":"צבי הירש מוילנא","dt":"תט - יז אדר","b":"דיין בוילנא."},{"i":40649,"n":"צבי הירש מוילנא","f":"דניאל בעל חמודי דניא","dt":"תר.. - ה שבט","dp":"וילנא","b":"הגיע לוילנא בעזרת בן אחותו - הגביר ר מנדל מוצקביץ. דיין בוילנא. חיבר הקדמה לספר אביו \"חמודי דניאל\"."},{"i":40650,"n":"צבי הירש מוילנא","f":"יהודה ליב","dt":"תקצז - כד ניסן","dp":"וילנא","b":"אביו היה בן ר שלמה זלקינד בן ר משה בן ר שלמה זלקניד בן ר ברוך. גביר מחכמי וילנא. יסד בחצרו בימ\"ד בשם \"ר הירשעלע זאלקינדש קלויז\" וע\"ש אשתו בשם \"מושקע ליבעלי זלקינדש קלויז\". אחיו: ר משה, ר שלמה זלמן קלצקי מוילקומיר, ר חיים חייקל מסלונים. גיסו ר בענדעט כבש."},{"i":40651,"n":"צבי הירש מוילנא","f":"אליהו חסיד מוילנא","dt":"תקכה - כט אייר","dp":"וילנא","b":"נכד בעל \"באר הגולה\" ור משה קרמר מוילנא. בניו - ר שלמה זלמן ריבלין משקלוב, הגביר ר אליהו פעסעלעס - מראשי קהילת וילנא ומדינת ליטא. אחיו - ר דב בער - זקנו של הגר\"א. נקבר לצד אחיו-ר משה מקובנא ווילנא."},{"i":40652,"n":"צבי הירש מוילנא","f":"דב בר מוילנא","k":"ר צבי די בערס","dt":"תקעז - כג אייר","dp":"וילנא","b":"נכד ר אליהו פעסעלעס. מחכמי וילנא. בנו - ר אברהם יקותיאל זלמן. אחיו - ר אריה ליב המכונה - ר ליבלי ר בערס."},{"i":40653,"n":"צבי הירש מוילנא","f":"דוד הלוי","k":"אבי בעל הבית'ל","dt":"תקץ - יח אדר","dp":"וילנא","b":"ש\"ץ בוילנא."},{"i":40654,"n":"צבי הירש מוילנא","f":"שאול שייקעס מוילנא","b":"מחכמי וילנא. נפטר צעיר (בגיל 22)."},{"i":40655,"n":"צבי הירש מוילנא (יוהנתנזון)","f":"יונתן משקוד","b":"תלמיד בישיבת ר עקיבא איגר, שכתב ליורשיו \"לא ראיתי תלמיד חכם כמוהו\". היה בקי גם בחכמת המדידה והתכונה והיה נכבד בעיני הפרופסורים של האקדמיה בוילנא. בניו: ר יוסף איבשיץ מאמשטרדם, ר אהרן יוהנתנזון מוילנא."},{"i":40656,"n":"צבי הירש מוילנא ולובלין","f":"עזריאל מוילנא","k":"בעל עטרת צבי","dt":"תצג-ז - כב אייר","dp":"ירושלים","b":"חתן הגביר ופרנס ר מנחם מן מוינה. ראב\"ד באליק, לובלין, האלי-תפב וישב אצל הגביר ר אברהם בן חיים וישב על חיבור ספריו, היה בוינה אצל הגביר ר יהודה זינצהיים שאיפשר לו להקדיש ימיו לכתיבת חיבורו \"בית לחם יהודה\" - ע\"ש מיטיבו. עלה לירושלים ולפי קורות היהודים בברלין חזר ללובלין ונפטר שם. חיבר \"עטרת צבי\" יסניץ תקע, ועוד. מחותן עם ר יואל בעל \"מגיני זהב\" - נכד הט\"ז, ר מנחם מנדל מקוטשין בעל \"עטרת זקנים\", ר פנחס בעל \"הלכה ברורה\". אחיו - ר יעקב-חתן ר בנימין בעל נחלת בנימין.","bk":[["בית לחם יהודא [יו\"ד]",""],["עטרת צבי [חו\"מ]",""]]},{"i":40657,"n":"צבי הירש מוישניצא","b":"רב בוישניצא-תק\"ל"},{"i":40658,"n":"צבי הירש מורעשנא","b":"רב בוורעשנא-תק\"נ"},{"i":40659,"n":"צבי הירש מז'אזמיר","b":"רב בז'אזמיר-תקס. עלה לצפת?"},{"i":40660,"n":"צבי הירש מזאמושט","f":"גדליה","b":"נכד ר צבי הירש מקרסניברוד. הו\"ל \"מציון תצא תורה\" - זאמושט תרפט. פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":40661,"n":"צבי הירש מזגרזש(=זגירז')","f":"אלעזר הכהן מפולטוסק","b":"נכד ר יעקב מליסא בעל \"חוות דעת\". תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, והשפת אמת מגור. רב בזגירז(=זגרז')-תרס, , פולטוסק, לודז, וארשא. אחיו - ר אברהם מוארשא, ר יהושע. גיסו - ר דוד מייזלש מלוסק."},{"i":40662,"n":"צבי הירש מזולקוא","f":"משה","b":"מחכמי זולקוא, חתם-תמ על תקנת הקהלה. אחיו - ר יהודה יודל (מלובלין?)."},{"i":40663,"n":"צבי הירש מזולקוא","f":"אורי","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה."},{"i":40664,"n":"צבי הירש מזולקוא","f":"מרדכי","b":"מחכמי זולקוא, חתם-תעו על בחירת ראשי הקהלה."},{"i":40665,"n":"צבי הירש מזולקוא ובוסק","f":"משה","b":"חתן ר יוסף בנימין זאב וולף מזולקוא בעל אור יקרות. ראש מדינה בזולקוא. הסכים על האלשיך-תקכה, \"אותות למועדים\"-תקיב, \"שער המלך\"-תקכב. רב בבוסק? (ראה גם ר צבי הירש מבוסק - חתן ר ישכר בער מפודהייץ)."},{"i":40666,"n":"צבי הירש מז'ידיק-ליטא","b":"רב בז'ידיק, ועל מקומו ר דב דימנד."},{"i":40667,"n":"צבי הירש מחעלם","b":"רב בחעלמא-תפ\"ג"},{"i":40668,"n":"צבי הירש מטאלדאש","f":"אלעזר הירש","b":"רב בטאלדאש-תר\"מ"},{"i":40669,"n":"צבי הירש מטארלי","dt":"תפג - ה שבט","b":"רב בטארלי"},{"i":40670,"n":"צבי הירש מטבריה","b":"נכד הבעש\"ט. עלה לטבריה-תקמו (בפרוקמין כתוב תרמו - כנראה בטעות)."},{"i":40671,"n":"צבי הירש מטומשוב","f":"ישראל ליבל מבילגוריי","bt":"תקס","dt":"תרלב - ז חשון","b":"חתן הגביר ר יעקב מטומשוב. תלמיד ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק - ושימש כאיש סודו ונאמן ביתו, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר. בנו ר יהושע שמואל מיאנוב."},{"i":40672,"n":"צבי הירש מטימקוביץ","f":"יהודה יידל","k":"בעל מרי צבי","b":"רב בטימקוביץ-ת\"ע"},{"i":40673,"n":"צבי הירש מטלוסט","b":"רב בטלוסט - תשובה אליו במהרש\"ם."},{"i":40674,"n":"צבי הירש מטרמבובלה","b":"רב בטרמבובלה-תרטז."},{"i":40675,"n":"צבי הירש מטרנוב","b":"מחכמי טרנוב - תשובה אליו בשו\"מ."},{"i":40676,"n":"צבי הירש מטרניגרד","b":"רב בטרניגרד-תקל\"ה"},{"i":40677,"n":"צבי הירש מטשודנוב","f":"דב בער מאולינוב","k":"אדמור מטשודנוב","dt":"תרח","b":"נינו של הבעשט, נכד ר דוד מקמינקא תלמיד הבעשט. אדמור בטשודנוב."},{"i":40678,"n":"צבי הירש מטשיטש","b":"רב בטשיטש. מופיע כערב ב\"תנאים\" של בעל \"אוהב ישראל\"."},{"i":40679,"n":"צבי הירש מיוזפוף","b":"רב ביוזעפוף-תקל\"ה"},{"i":40680,"n":"צבי הירש מירושלים","f":"יהודה","b":"בשליחות קהלת הפרושים בירושלים-תקצא."},{"i":40681,"n":"צבי הירש מלבוב","f":"זכריה","dt":"תטו - יב אב","dp":"לבוב","b":"אב\"ד ור\"מ בלבוב. נזכר ב\"לב אריה\". (ולפי בובר לא היה אב\"ד והחליפו בינו לבין ר צבי הירש בן זכריה מנדל שנפטר בקראקא תנא)."},{"i":40682,"n":"צבי הירש מלבוב","f":"יהודה ליבוש","b":"מחכמי לבוב, חתם-תקי על שטר מתנה של ראשי הקהל."},{"i":40683,"n":"צבי הירש מלבוב","f":"יהודה משה","b":"מראשי קהלת לבוב חוץ לעיר, חתם-תקל בפנקס הקהלה."},{"i":40684,"n":"צבי הירש מלבוב ובוליחוב","b":"רב בבאליחוב(=בוליחוב), לבוב-תקנט. הסכים על \"גבולות בנימין\" לר שמחה רפפורט - תקל."},{"i":40685,"n":"צבי הירש מלובלין","k":"ר צבי הירש פרוש","dt":"תקפח - כז ניסן","b":"תלמיד החוזה מלובלין."},{"i":40686,"n":"צבי הירש מלובלין","f":"מרדכי מלובלין","bp":"פודהייץ","b":"כנראה בנו של ר מרדכי שנהרג עק\"ה-שצו. חיבר סליחה \"אלקים אל דמי לך ואל תחרוש\" וחתם שמו בראשי החרוזים."},{"i":40687,"n":"צבי הירש מלובלין","f":"משה חנוך זונדל","k":"בעל דרך טובים","b":"מחכמי לובלין."},{"i":40688,"n":"צבי הירש מלובלין","f":"יצחק יעקב רעכילש","dt":"תקכא - כז אד\"ב","dp":"לובלין","b":"מחכמי לובלין."},{"i":40689,"n":"צבי הירש מלובלין","f":"משה","dt":"תקעא - ב אלול","dp":"לובלין","b":"מחכמי לובלין. חתם על החרם של ר יעקב חיים אב\"ד לובלין על הדוברים סרה בר יהונתן איבשיץ."},{"i":40690,"n":"צבי הירש מלובלין - א","f":"אברהם","dt":"תקכו - א טבת","b":"מגדולי חכמי לובלין"},{"i":40691,"n":"צבי הירש מלובלין - ב","dt":"תקצא - יב ניסן","b":"ראב\"ד בלובלין"},{"i":40692,"n":"צבי הירש מלובלין מדובענקי ולוב","f":"שלמה הכהן","dt":"תקפח - כז ניסן","dp":"לובלין","b":"נינו של ר צבי הירש רפפורט מהלברשטט. אב\"ד דובענקי."},{"i":40693,"n":"צבי הירש מלוקאבי","f":"אברהם פרנס","dt":"תקכו - כד טבת","dp":"לובלין","b":"אחיו של ר יעקב חיים אב\"ד לובלין."},{"i":40694,"n":"צבי הירש מלוקטש","f":"שלמה זלמן מביאלא","k":"בעל חמדת צבי","b":"רב בלוקטש(=לוקאטש)-תקנ. בנו - ר אריה ליב, ר יעקב ליברמן, נכדו - ר שמחה נתן מלבוב, ונינו - ר בנימין מבקשביץ."},{"i":40695,"n":"צבי הירש מליטא","b":"עלה בשיירת החסידים-תקכד."},{"i":40696,"n":"צבי הירש מלשביץ","b":"רב בלשביץ."},{"i":40697,"n":"צבי הירש ממאד","dt":"תקצט","b":"רב במאד על מקום ר משה אליעזר וייל. תלמיד ר מנחם מנדל מרימנוב. בנוסעו אל רבו-תקצט נעלם ולא נודעו עקבותיו."},{"i":40698,"n":"צבי הירש ממונקטש","b":"דומ\"צ במונקאטש-תק\"פ"},{"i":40699,"n":"צבי הירש ממונקטש","dt":"תרב - טז טבת","b":"תלמיד החוזה מלובלין, ור צבי הירש מזידיטשוב והאדמור מנעשכיז, לובלין, קאלוב (והאדמור מקאלוב הניח לו ירושה כדי שיאמר אחריו קדיש. דיין אצל ר צבי אלימלך מדינוב. חתנו - ר שמואל צבי וייס ממונקאטש. נכדו - ר בנציון וייס מרעסויגוב."},{"i":40700,"n":"צבי הירש ממזריטש","b":"רב במזריטש-תי. חתנו - ר חיים."},{"i":40701,"n":"צבי הירש ממזריטש","f":"אלעזר","dt":"תצד - יד תמוז","b":"חתן ר יצחק בן שמואל זנויל מזולקוא, ובזיוו\"ש חתן גיסו - ר מרדכי גינצבורג מבריסק. רב במזריטש. בנו - ר אברהם אביש מפפד\"מ בעל \"ברכת אברהם\", ר מרדכי."},{"i":40702,"n":"צבי הירש ממזריטש","b":"מו\"צ במזריטש-תקל. חתן ר משה שאול."},{"i":40703,"n":"צבי הירש ממינסק","f":"חיים","dt":"תריב - ג אדר","dp":"מינסק","b":"מחכמי מינסק."},{"i":40704,"n":"צבי הירש ממנוסטרישץ","f":"אריה ליב מבוטשאטש","b":"רב במניסטריטץ-ת\"ק"},{"i":40705,"n":"צבי הירש מנדבורנא","f":"פיליפ, צבי הירש מנדב","k":"בעל מילי דאבות","dt":"תקסא - כ סיון","b":"מגיד בדולינא,נדבורנה"},{"i":40706,"n":"צבי הירש מנדבורנה וטבריה","f":"יצחק","k":"בעל כתם פז","b":"תלמיד ר משה חיים אפרים מסדילקוב, ר אברהם מקליסק, ר חיים מקרוסנא, ור שמואל שמלקא מניקלשבורג. רב בנדבורנא, סמטריטש, אוזירן, עלה לארץ-תקנה והתישב בטבריה אצל ר אברהם מקאליסק. נדקר בצפת ע\"י ערבי. חיבר \"כתם פז\" קפוסט תקצג."},{"i":40707,"n":"צבי הירש מנוסטרישטש","b":"רב בנוסטרישטש-תקלח . חתן ר ליבוש ראש מדינה. אביו של ר יעקב חריף."},{"i":40708,"n":"צבי הירש מניישטט","b":"רב בניישטט-תר\"ל"},{"i":40709,"n":"צבי הירש מנישויער וירושלים","f":"יוסף","dt":"תקצח - כ תמוז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":40710,"n":"צבי הירש מסוקלוב","f":"דוד","k":"בעל צבי קדש","b":"רב בסאקלוב(=סוקלוב)-תק. העניק את ספרו לספריית הגביר ר יצחק גאליקו מאיטליה."},{"i":40711,"n":"צבי הירש מסטוינוב","b":"רב בסטוינוב-תרנב."},{"i":40712,"n":"צבי הירש מסימטריטש","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":40713,"n":"צבי הירש מסלאויטש","b":"מקורב לחוזה מלובלין שאמר עליו \"כוכב זורח לי בסלאויטש\". אב\"ד סלאויטש."},{"i":40714,"n":"צבי הירש מסמיאטיץ","k":"בעל מרגליות התורה","dt":"תקעד-ט","b":"תלמיד הגר\"א. רב בסימיאטיטש(=סמיאטיץ). נספד ב\"אגודת אזוב\". חיבר \"מרגליות התורה\" פאריצק תקמח."},{"i":40715,"n":"צבי הירש מסמניץ","b":"רב בסמניץ,סגדין-תקס\"ט"},{"i":40716,"n":"צבי הירש מסנטוב","k":"בעל ארץ צבי ראה: לעוו,","b":"מו\"צ במאד-תנ\"ט,רב בסנטוב"},{"i":40717,"n":"צבי הירש מפודהייץ","b":"רב בפדהייץ(=פודהייץ)-תקמ. מחותן עם ר מאיר מרגליות המזכירו בספרו."},{"i":40718,"n":"צבי הירש מפוזנא","f":"חיים חזן","k":"בעל אור הישר","b":"רב בפוזנא-תמט. חיבר \"אור הישר\" אמשטרדם תסט."},{"i":40719,"n":"צבי הירש מפיורדא","b":"רב בפיורדא-תק\"מ"},{"i":40720,"n":"צבי הירש מפיליוריק","b":"רב בפיליוריק (ליד בוצאץ)-תרכו."},{"i":40721,"n":"צבי הירש מפינסק","f":"הבעל שם טוב","bt":"תפט","dt":"תקמ - ז טבת","b":"רב בפינסק"},{"i":40722,"n":"צבי הירש מפיעטרקוב"},{"i":40723,"n":"צבי הירש מפלונצק","f":"חיים","k":"בעל צמח לאברהם","b":"מצאצאי ר אברהם בעל \"מגן אברהם\". גביר מחכמי פלונצק-פולין-תקן. חיבר \"צמח לאברהם\" - וארשא תקנו, \"גדולי צבי רבא\", ועוד."},{"i":40724,"n":"צבי הירש מפמורן","b":"רב בפמורן-תרמז."},{"i":40725,"n":"צבי הירש מפפד\"מ","f":"אברהם אביש מליסא ופפ","b":"חתן ר מרדכי אב\"ד ליסא. מגדולי חכמי פפד\"מ-תקמה."},{"i":40726,"n":"צבי הירש מפרושניץ","dt":"תקצו - טו אב","b":"רב בפרושניץ"},{"i":40727,"n":"צבי הירש מפרצוב","dt":"תרמה","b":"תלמיד החוזה מלובלין, שליח ציבור אצל בנו ר יוסף מטורטשין, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק, ר חנוך הניך מאלכסנדר, ר יצחק מאיר מגור ונכדו ר יהודה אריה ליב."},{"i":40728,"n":"צבי הירש מצייקישוק","b":"אב\"ד צייקישוק. נכדו - ר דובער שנפלד מראסיין."},{"i":40729,"n":"צבי הירש מצפת טבריה","f":"אליעזר משקלוב","b":"עלה לארץ-תקנג. חתם על כתב שליחות-תקנה."},{"i":40730,"n":"צבי הירש מצשינוב","k":"הרשלי קרעשיווער","b":"רב בצשינוב-תרסא."},{"i":40731,"n":"צבי הירש מקאלוש","f":"משה יוסף","b":"רב בקאלוש."},{"i":40732,"n":"צבי הירש מקאמינקה","b":"תלמיד הבעש\"ט. רב בקאמינקה-תק\"ל. נכדו - ר שמואל קאמינקר."},{"i":40733,"n":"צבי הירש מקויטשיניץ","b":"רב בקופיטשיניץ-תרסט."},{"i":40734,"n":"צבי הירש מקונסטנטין","f":"משה","dt":"תקנא","b":"רב בקונסטנטין"},{"i":40735,"n":"צבי הירש מקוריסטשוב","dt":"ה ניסן","b":"תלמיד הבעשט, שציוהו שלא יבוא למזבוז כדי שלא יתבטל מתורתו, והיו נפגשים פעם בשנה כשהבעשט הגיע לקוריסטשוב, עבר לטשרניגוב. עליו ב\"חיי משה\" לנכדו ר משה שוחט, שנדפס עם \"אמת ליעקב\"."},{"i":40736,"n":"צבי הירש מקושטא","b":"דיין ביה\"ד האשכנזי בקושטא-תטו."},{"i":40737,"n":"צבי הירש מקמניץ","f":"יוסף בן חיים מקמניץ","b":"רב בקמניץ על מקום אביו."},{"i":40738,"n":"צבי הירש מקראקא","f":"מנדל מפוזנא","b":"מגדולי קרקא-ת\"ג"},{"i":40739,"n":"צבי הירש מקרוס","b":"רב בקרוס-תרעב."},{"i":40740,"n":"צבי הירש מקרטשוב","b":"מרביץ תורה בקארטשוב-תק\"נ"},{"i":40741,"n":"צבי הירש מקריסטשוב","b":"ר\"מ בקריסטשוב"},{"i":40742,"n":"צבי הירש מקריסנפולי","b":"רב בקריסנפולי-תקף."},{"i":40743,"n":"צבי הירש מראסיין","dt":"תקע","dp":"ראסיין","b":"חתן ר דוד בן אליהו מראסיין. מו\"ץ בראסיין-שנות ה-תק'."},{"i":40744,"n":"צבי הירש מרימנוב","f":"יהודה ליב הכהן","k":"אדמור מרימנוב","bt":"תקלח","bp":"דומברובה","dt":"תרז - ל חשון","b":"גדל אצל ר דוד קמלהר בן דודו - לאחר שנתייתם. חסיד ר מנחם מנדל מרימנוב ונקרא בשם ר הירש משרת. אחר פטירת רבו נסע לר נפתלי מרופשיץ ואחר 12 שנה חזר לרימנוב ונבחר לכהן כאדמור. חתן ר חיים גרייצר, ובזיוו\"ש חתן ר אלחנן מבילגוריא, ובזיוו\"ש חתן הגביר ר דוד ליב לייבנר מדוקלא. בנו ר יוסף פרידמן על מקומו אחריו. חיבר \"בארות המים\" תרנד. לתולדותיו \"מבשר טוב\".","bk":[["בארות המים",""],["מבשר טוב",""],["מבשר טוב , בארות המים",""]]},{"i":40745,"n":"צבי הירש משאטלנד","b":"חתן ר יונה מלומבלא. רב בשוטלנד(=שאטלנד)-תקכ."},{"i":40746,"n":"צבי הירש משידלובה","f":"אברהם אבלי","dt":"תרטז","b":"רב בשידלובה."},{"i":40747,"n":"צבי הירש סבא","f":"יוסף יאסקה מלובלין","b":"נינו של המהר\"ל. רב-שנת ת\"מ. אחיו - ר שמואל מגניזין בעל \"לחם רב\". בנו - ר משה ונכדו ר אלכסנדר."},{"i":40748,"n":"צבי הירש סגל מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":40749,"n":"צבי הירש סגל מהארקי","f":"אברהם הלוי","dt":"תקפח - יב תשרי","b":"תלמיד ר מנחם מנדיל מויטבסק, ור אברהם מקאליסק. עלה עם רבותיו לארץ-תקלז, בשליחות-תקמג, תקמז, תקסג. ר ברוך ממזבוז מינהו למנהיג חסידי רייסין בטבריה על מקום ר אברהם מקאליסק. בנו ר שאול."},{"i":40750,"n":"צבי הירש קארשטשיווער","b":"נכד-אבי אמו ר נחום מטשרנוביל. נכדו - האדמור ר ישראל מרוזין."},{"i":40751,"n":"צבי הירש ר פישלס מלבוב","b":"חתם-תיט על תקנה בזולקוא. אחיו - ר זאב וולף מלבוב."},{"i":40752,"n":"צבי הירש רוסטנר מהורדנא","f":"אליעזר","dt":"תקס - יד אדר","dp":"הורדנא","b":"מצאצאי בעל \"תבואות שור\". רב בהורדנא."},{"i":40753,"n":"צבי הירש-אביו של ר מרדכי אונגר","b":"תלמיד ר אלימלך מליזנסק, ור אברהם יהושע השל מאפטא. אביו של האדמור ר מרדכי דוד אונגר מדומברובא. ר אלימלך אמר עליו \"אב כמו ר צבי הירש המתעלף בעת ששופך תחינתו על הבנים... אין פלא שיצא מחלציו בן כזה\"."},{"i":40754,"n":"צבי הכהן","bt":"תרכ","dt":"תשי","b":"רב פעלים,רב במונטריאל-תרמ\"ט"},{"i":40755,"n":"צבי הלוי מירושלים","f":"נתנאל מאיטליה","dt":"תקפו - יא כסלו","b":"אביו היה רב בפדובה ובמודנא, עלה לירושלים בשנת תקיח ונמנה עם תלמידי \"כנסת ישראל\". בשנת תקמב בשליחות במרוקו, ר דוד בן חסין כתב שיר לכבודו. בשליחות עם ר אברהם אליעזר הלוי באיטליה והיה בטריאסט ותיקן שם כמה תקנות. מתורתו ב\"פקודת המלך\" ו\"עקרי הד\"ט|, ועוד."},{"i":40756,"n":"צבי הלוי ממרוקו","b":"תלמיד \"כנסת ישראל\" של ר חיים ן עטר בסאלי-מרוקו."},{"i":40757,"n":"צבי הרש ליב סגל מנאוועסא","b":"תלמיד החת\"ס. רב בנאוועסא-תקצט."},{"i":40758,"n":"צבי חיים מגיד מטעטש","f":"מאיר מנדבורנה","b":"מחכמי מרמורורש. חתן ר אפרים פישל פלדמן מביטשוקב. מחכמי ועשירי טעטש. הוציא לאור ספר זקנו \"כתר תורה\" - תרצג."},{"i":40759,"n":"צבי חסיד מזלוטשוב","f":"אליעזר","b":"תלמיד הבעשט. אחיו של ר מנחם מנדל מפרמישלן, שכתב אליו מכתב מטבריה. בנו ר חיים זאב - רשם את תורתו של ר ישכר בער מזלוטשוב ונתפרסמו ב\"מבשר צדק\"."},{"i":40760,"n":"צבי חסיד מיאמפולא","k":"בעל אמרי צדיקים","dt":"תקעה","b":"תלמיד ר חיים מקרוסנא, ור לוי יצחק מברדיטשוב."},{"i":40761,"n":"צבי יהודה הכהן מירושלים","f":"זאב","dt":"תרכו - כו כסלו","dp":"ירושלים","b":"אבד זאגר (פולין), עלה לירושלים, חתום בשנת תרמג עם רבני ירושלים כנגד ר\"מ יאנובר בזמן המחלוקת."},{"i":40762,"n":"צבי יהודה ליב הכהן מראווא","b":"רב בראווא-תריב."},{"i":40763,"n":"צבי יהודה מוואריש","dt":"תרעג","b":"רב בואריש-תרל, לוביטש-תרנג."},{"i":40764,"n":"צבי יוסף מרודניק","b":"חתן הגביר ר איציקל מרודניק. תלמיד ר נפתלי צבי מרופשיץ, מקושר עם גיסו ר אלימלך מרודניק. ר חיים מצאנז שכיהן כרב ברודניק אמר עליו \"כמה טוב היה ברודניק כאשר מצד אחד היה הצדיק ר אלימלך ומצד שני ר צבי יוסף\"."},{"i":40765,"n":"צבי יחזקיהו","k":"מהרי\"ח","b":"מגדולי הפוסקים בחכמי אשכנז-שנת ר'"},{"i":40766,"n":"צבי יחיאל מטבריה","f":"ישעיה מקוידנוב","k":"הירש מיכל","b":"ממונה \"כולל רייסין\" בטבריה-תרטו."},{"i":40767,"n":"צבי יעקב מברוד","b":"מחכמי הקלויז של ברוד. תלמיד ר חיים צאנזר בברודי, והבעשט."},{"i":40768,"n":"צבי ליפמן","k":"בעל ארץ צבי","b":"חיבר \"ארץ צבי\" על הפטרות השנה."},{"i":40769,"n":"צבי מאוביסקא","b":"רב באוביסקא"},{"i":40770,"n":"צבי מאוטציאן וירושלים","f":"אברהם","b":"מחכמי ירושלים, חתם-תרכב עם גבאי הת\"ת במכתב ר\"ש קלמר."},{"i":40771,"n":"צבי מאוסטרהא","f":"יצחק","dt":"תקו - ז שבט","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":40772,"n":"צבי מאוסטרהא","f":"יעקב דוד","dt":"תקמט - כט חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":40773,"n":"צבי מהליטש","k":"ר צבי ר ישעיה'ס","b":"חתן ר יצחק מראדויל בן המגיד מזלוטשוב. חתנו - ר יחיאל מיכל הלפרין מברזאן-הליטש."},{"i":40774,"n":"צבי מוילנא","f":"דב בער","b":"רב בוילנא, חתם-תעד על פס\"ד עם ר בנימין וולף וילנא-אשכנזי ור נח בן יוסף."},{"i":40775,"n":"צבי מטיטיוב","b":"רב בטיטיוב-תק\"צ"},{"i":40776,"n":"צבי מלאסק","f":"פנחס זליג מלאסק","b":"רב בלאסק על מקום אביו-תקנ, ור מאיר צילך על מקומו אחריו."},{"i":40777,"n":"צבי מלובלין","dt":"תקצא - יב ניסן","dp":"לובלין","b":"דיין בלובלין. חתן הרב המגיד(?)."},{"i":40778,"n":"צבי מלובלין","f":"בנימין וולף","dt":"תקיא - כו טבת","dp":"לובלין","b":"אחיו - ר משה."},{"i":40779,"n":"צבי ממז'בוז' ופינסק","f":"הבעש\"ט","dt":"תקם - ז טבת","dp":"פינסק","b":"גיסו של ר אברהם שמשון מרשקוב - בנו של ר יעקב יוסף מפולנאה. אדמור על מקום אביו לזמן קצר, וויתר על ההנהגה לטובת המגיד ממזריטש. בזיוו\"ש חתן ר שמואל חסיד מפינסק ועבר לשם. עליו ב\"אבן ישראל\"."},{"i":40780,"n":"צבי מנאחוד","dt":"תצח - ז ניסן","b":"רב בנאחוד"},{"i":40781,"n":"צבי מנארינסק","b":"רב בנארינסק-תק\"ל"},{"i":40782,"n":"צבי מנחם מנדל מאניפולי","f":"זושא מאניפאלי","k":"אדמור מאניפולי דינוב","dt":"תקעד - כח טבת","dp":"דינוביץ","b":"חתן ר משה מאיבניצא, ובזיוו\"ש חתן ר דב בער מאולינוב-נכד הבעשט. אדמור באניפולי, דינוביץ. מתורתו ב\"שפתי צדיקים\"."},{"i":40783,"n":"צבי מסלבטי","b":"רב בלובץ-תק\"צ"},{"i":40784,"n":"צבי מסקווירא","f":"אהרן מטיטיוב","dt":"יז תשרי","dp":"חודרוקוב","b":"נינו של הבעשט."},{"i":40785,"n":"צבי מפרימישלן","f":"מאיר מפרימישלן","dt":"תרט - בערך","b":"חתן ר ארון מראטשיביר (ליד ניזנוב). נפטר בנסיעתו לר ישראל ברוזין."},{"i":40786,"n":"צבי מקוריסטשוב","f":"אברהם מקוריסטשוב","k":"אדמור מקורסיטשוב","b":"חתן ר אהרן מטיטיוב (אלמנתו נישאה בזיוו\"ש לקרובה ר ברוך ממזבוז). חתניו האדמור ר אהרן טברסקי מטשרנוביל, וגיסו ר אברהם מסקווירא בן ר אהרן מטיטיוב."},{"i":40787,"n":"צבי מקמיניץ","b":"תלמיד הבעשט."},{"i":40788,"n":"צבי מקראקא","f":"יקותיאל","k":"בעל חמדת צבי","b":"שו\"ב בקראקא. חיבר \"חמדת צבי\", \"שבתא דרגלא\" ועוד."},{"i":40789,"n":"צבי מקריסנפולי","dt":"תקפה","b":"רב בקריסניפולע"},{"i":40790,"n":"צבי מראדויל וסיגט","f":"משה אברהם","dt":"תקלא - ד אלול","b":"רב בראדוויל-פולין, הגיע לסאראסאו-ליד סיגט ונרשם במפקד היהודים כ-\"הירש אברמוביץ\" ועסק בבישול משקאות עד שנתגלתה גדלותו בתורה, רבה הראשון של סיגט-תקיט - ובזמנו היה כשני מניני יהודים בעיר."},{"i":40791,"n":"צבי מרדכי מפשיסחא","f":"צבי מרדכי","k":"אדמור מפשיסחא","bt":"תקפו","dt":"תרכז - כט כסלו","b":"חתן ר יצחק מוארקי, והיה חסיד ומקורב לחותנו. בסוף ימיו אדמור בפשיסחא."},{"i":40792,"n":"צבי משידלובה","dt":"תקפז - ז אדר","b":"רב בשידלוב"},{"i":40793,"n":"צבי משקלוב וירושלים","f":"פלטיאל","dt":"תקצא - ו תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":40794,"n":"צבי נפתלי מוילנא","f":"פתחיה מפרג","b":"תלמיד ר יהושע פאלק בעל הסמ\"ע. אביו של ר משה רבקש בעל \"באר הגולה\". חתנו - ר אריה ליב מזוואלין-אביו של ר דוד לידא מאמשטרדם."},{"i":40795,"n":"צבי סופר ממזבוז","b":"תלמיד הבעשט וסופרו. חברו של ר אברהם גרשון מקיטוב. בתו ונכדו נקברו ליד הבעשט."},{"i":40796,"n":"צבי קאהן מיגולניצה","b":"רב ביגולניצה-תרסו."},{"i":40797,"n":"צבי קהת מטופרוב","f":"י\"א מחוליוב","b":"רב בטופרוב, חוליוב."},{"i":40798,"n":"צבי, אברהם מנארול","f":"יעקב קופל אשכנזי","k":"הקדוש(הי\"ד)","b":"רב בנארול"},{"i":40799,"n":"צבי, אברהם מקושטא","dt":"תקצו - כא אלול","dp":"קושטא","b":"דיין ואב\"ד בקושטא"},{"i":40800,"n":"צבי, אהרן אשכנזי מירושלים","f":"משה יהודה","b":"מחכמי ירושלים, בשליחות-תקף בשלוניקי והתגורר שם בבית ר שאול מולכו וחותנו-ר אברהם שלום - וכתב לכבודם שירים. הוציא ספר \"יד אהרן\" שלוניקי תקצט, \"אוצר בינה\" אזמיר תרא. חיבר שיר לכבוד ר חיים יוסף ן ארדיט ור שאול מולכו שסייעו לו בשליחותו ונדפס ב\"יד אהרן\"."},{"i":40801,"n":"צבי, אהרן זליג מלבוב","f":"שמואל","b":"דיין בלבוב, חתם-תפד עם ר נתן נטע בן זלמן סגל, ר אברהם כץ, ועוד."},{"i":40802,"n":"צבי, אהרן מברלין - הנכד","f":"משה מגזע-צבי","k":"בעל מנחת אהרן","dt":"תקמ","b":"נכד בעל הש\"ך. חתן ר בנימין פרנקל מגלוגא. אב\"ד בדעסוי, ראב\"ד בברלין-תקכג (ונקבל כראב\"ד ולא כאב\"ד - (האב\"ד היה נכבד יותר ונקרא מורי מורינו, והראב\"ד לא), רב בשוואבך ומדינת אנסבך ור ליב למברג על מקומו אחריו. חיבר דרוש על השלום-תקכג לכבוד המלך פרידריך, ותורגמה לגרמנית בידי משה מנדלסון ונדפסה בעברית וגרמנית בידי ר הירש בן אריה ליב ליפשיץ. הו\"ל \"הארוך מש\"ך\" לזקנו. נזכר בשו\"ת ר חיים רפפורט שהשיב לרב אחד בענין עגונה-תקכג - וכנראה הכוונה לר אהרן. בנו גם - ר מאיר. הסכים על 'באר יעקב'-פיורדא תקכז."},{"i":40803,"n":"צבי, אהרן מלונטשיץ - הזקן","k":"חתן הש\"ך","b":"חתן הש\"ך. רב בלונטשיץ-תר\"ל. בנו ר משה ונכדו ר אהרן בעל \"מנחת אהרן\"-ראב\"ד ברלין. חתנו - ר יוסף פולווערמאכער הלפרין."},{"i":40804,"n":"צבי, אהרן משה מברוד","f":"שאול","k":"בעל צוואת הרא\"ם","bt":"תקלה","bp":"ברודי","dt":"תרה - ז תמוז","dp":"ירושלים","b":"מתלמידי החוזה מלובלין ור אורי מסטרליסק, חתן ר מרדכי הורביץ. עלה לצפת-תקצט ועבר לירושלים, ועמד בראש קהילת החסידים, ובראש כולל החסידים הראשון. היה חתנו של ר מרדכי הורביץ, הוציא את ספרו של שאר בשרו ר חיים הורביץ \"חיבת ירושלים\" ירושלים תרד. תורה משמו מופיע בספר \"שם חדש\" לר חיים דוד שלמה פנסו, הסכים על כמה ספרים, \"ספר צוואות\" שלו נדפס ירושלים תרה. ניסה לקרב את הגאולה ע\"י תיקון החטא שחטאו לנביא זכריה בן יהוידע."},{"i":40805,"n":"צבי, אליהו - אחי ש\"ץ","f":"מרדכי","b":"גביר באזמיר. אחיו ותומכו של ש\"ץ, וחזר בו לאחר המרת ש\"ץ ונשאר יהודי נאמן."},{"i":40806,"n":"צבי, אליעזר הכהן משוואבאך","f":"אהרן מברלין","b":"נינו של בעל הש\"ך. רב בשוואבאך(=שוואבך). אחיו של ר מאיר בעל \"תבואות שמש\" ונזכר בספרו. עזר לאביו בהדפסת ספר זקנם \"ארוך מש\"ך\"."},{"i":40807,"n":"צבי, אלעזר מבלז","f":"יוסף","b":"חתם על גביית עדות - בלז שעב."},{"i":40808,"n":"צבי, בנימין מפוזנא","f":"אליעזר מלונשטיץ","b":"דיין בפוזנא אצל ר מרדכי יפה בעל הלבוש-שנז. הסכים על \"חג פסח\" - קראקא."},{"i":40809,"n":"צבי, הלמן מוורמייזא","f":"חיים מוורמייזא","b":"תלמיד המהרש\"ל. מגדולי חכמי אשכנז בוורמייזא-שמ. אחיו של ר בצלאל-אבי המהר\"ל. בנו - ר שמואל ונכדו ר חיים מקרמניץ."},{"i":40810,"n":"צבי, חיים מהורדנא","f":"משה מגזע צבי","b":"רב בהורדנא-תע\"ה"},{"i":40811,"n":"צבי, חיים מרדכי מקושטא","bt":"תקצח","dt":"תרסח - כו כסלו","dp":"קושטא","b":"סופר-תרל, דיין בקושטא-תרמא, ואב\"ד."},{"i":40812,"n":"צבי, יהודה ליב מדובנא","f":"ישכר דב בער מזלוטשוב","dt":"תקפח - כז ניסן","b":"בנו של בעל \"מבשר צדק\". גביר בדובנא."},{"i":40813,"n":"צבי, יוסף יוזל מפפד\"מ","b":"הדפיס סליחות - פפד\"א תסב יחד עם גיסו ר מנדל קרוכמל."},{"i":40814,"n":"צבי, יוסף מאזמיר - אחי ש\"ץ","f":"מרדכי","b":"גביר באזמיר, אחיו ותומכו של ש\"ץ, וחזר בו לאחר המרת ש\"ץ ונשאר יהודי נאמן."},{"i":40815,"n":"צבי, יעקב יעקל מפוזנא","f":"שמואל","b":"רב בפוזנא. הסכים על \"נחלת יעקב\"-תח יחד עם אחיו ר חיים מקרמניץ."},{"i":40816,"n":"צבי, יעקב מברלין","f":"משה","bt":"תפד","bp":"ברלין","dt":"תקסב - יב שבט","b":"פו\"מ בברלין, ובזכות קשריו ביטל גזרות רעות על היהודים. מצאצאיו הגבירים לואיס ויעקב במברגר. נזכר בעליות אליהו שנתארח הגר\"א בביתו ונפגש עם אחד מחכמי האוניברסיטה בברלין ולדעת אליעזר לנדסהוט ב\"תולדות אנשי השם\" - האוניברסיטה בברלין נוסדה אחרי מותו של ר יעקב צבי ולכן הדבר לא יתכן."},{"i":40817,"n":"צבי, יעקב קופל מלמברג","k":"בעל מגדני יעקב","b":"מצאצאי ר הירץ טריווש מפפד\"מ. דיין בלבוב-תנ. חיבר גם \"משכנות יעקב\"."},{"i":40818,"n":"צבי, יצחק מסרייבו","f":"שם טוב","b":"רב ומלמד תורה בסרייבו-שנות ה-תק' בזמן ר דוד פארדו בעל שושנים לדוד. מתלמידיו - ר דוד פינטו."},{"i":40819,"n":"צבי, ישכר דב בר מזלוטשוב","f":"אריה יהודה ליבוש","k":"בעל בת עיני","bt":"תצה","dt":"תקנה - ז אב","dp":"צפת","b":"תלמיד המגיד ממזריטש, והמגיד מזלוטשוב. חתן ר צבי הירש פרץ מלברטוב. רב בלברטוב, זלוטשוב. עלה לצפת-תקנד. חיבר גם \"מבשר צדק\". על ספריו הסכימו כל גדולי החסידות, בסוף ימיו נסתמא וכתב על ידי מזכיר. (באוצר תאריך פטירה - תקע). בנו הגביר ר יהודה ליב מדובנרא, חתניו ר חיים אורו לייבש ביליג מגוליגור, ר גרשון מרגליות מסקאליט, ר פסח בן ר שלמה זלמן מזסלב. הסכים על \"ספר השרשים\" לר יצחק מסטנוב בשם ר ישראל מגזע צבי."},{"i":40820,"n":"צבי, ישראל","k":"ראה: צבי, ישכר ד","b":"בהסכמה לספר השרשים נרשם בטעות ר ישראל וצ\"ל ר ישכר דב מזלוטשוב."},{"i":40821,"n":"צבי, ליבוש"},{"i":40822,"n":"צבי, מאיר","f":"אהרן - מנחת אהרן"},{"i":40823,"n":"צבי, מאיר הכהן מעמדן","f":"אהרן מברלין","k":"בעל תבואות שמש","dt":"תקסט - ו טבת","dp":"גלוגא","b":"נינו של בעל הש\"ך. רב בעמדן. חיבר \"תבואות שמש\"."},{"i":40824,"n":"צבי, מרדכי מאזמיר - אבי ש\"ץ","dt":"תכג - כה ניסן","dp":"אזמיר","b":"סוכן בבית מסחר אנגלי באזמיר. אביו של ש\"ץ, יוסף, אליהו."},{"i":40825,"n":"צבי, משה מהורדנא","f":"אברהם הקדוש מגזע צבי","k":"בעל תפארת למשה","dt":"תמא - י אייר","dp":"גרודנא","b":"חתן ר בנימין מירלש פרנקל מברלין. תלמיד זקנו ר השל בבריסק. מגדולי חכמי דורו, רב ור\"מ בהורדנא-תלג על מקום ר חיים חייקא הורביץ ור מרדכי זיסקינד רוטנברג על מקומו אחריו. השתתף בועד יהודי ליטא בחומסק-תלט. נכדו ר שלמה בן חיים הו\"ל את ספרו \"תפארת למשה\" ברלין תקלו. חתנו - ר ברוך אברהם רפפורט מפיורדא."},{"i":40826,"n":"צבי, משה מלונטשיץ","f":"אהרן","b":"רב בלונטשיץ-ת\"ק"},{"i":40827,"n":"צבי, נפתלי הרץ מזולקוא","b":"חתם-תסד על תקנת קהלת זולקוא."},{"i":40828,"n":"צבי, נתן בכור משלוניקי","dt":"תרו","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":40829,"n":"צבי, שבתי משלוניקי-ש\"ץ","f":"מרדכי","bt":"שפו","bp":"אזמיר","dt":"תלז - י תשרי","dp":"דולציאנו או ביראט-אלבניה","b":"משיח שקר. מקובל באזמיר, גורש מאזמיר ועבר לשלוניקי-תיט, חתן ר שלומיאל (או משה שמואל) טרודי (או קארידי), עבר לירושלים-תכא. הכריז על עצמו משיח-תכה, התאסלם-תכו. בזיוו\"ש חתן ר יוסף פילוסוף."},{"i":40830,"n":"צבי, שלמה מברלין","f":"אברהם אבריל ניימרק","dt":"תצא - ו כסלו","b":"ממגורשי אייזנשטט והגיע לברלין. חתן ר יידל מאיזנשטט. בנו"},{"i":40831,"n":"צבי, שלמה מהורדנא","f":"חיים מגזע צבי","b":"רב בהורדנא-תקי\"ב"},{"i":40832,"n":"צבי, שם טוב מסרייבו","f":"יצחק מסרייבו","bp":"בלגרד","dt":"תקד - בערך","b":"תלמיד ר לוי ירושלמי בבלגרד. רב בשאראי(=סרייבו)-תעו על מקום ר יצחק צבי אשכנזי, תשובות ממנו בספרי חכמי דורו. ר דוד פארדו רב בסרייבו על מקומו אחריו. למרות שהיה אשכנזי היה בקי במנהגי הספרדים ומקורב לרבניהם. (אצל רוזניס תאריך פטירתו תכד! ולא יכול להיות)."},{"i":40833,"n":"צבי, שמואל מפוזנא","f":"הלמן (שמואל?)","b":"דיין בפוזנא אצל ר מרדכי יפה בעל הלבוש-שנז. הסכים על \"חג פסח\" - קראקא. בניו: ר חיים מקרמניץ, ר יעקב מפוזנא."},{"i":40834,"n":"צביון, יהודה","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":40835,"n":"צביון, משה","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א, \"תבונה\" - ירושלים תשא-תשח."},{"i":40836,"n":"צביניצקי, יעקב מארה\"ב","f":"יוסף","bt":"תרעז","bp":"ברעמאן","b":"תלמיד ישיבת הרב ברויאר בפפד\"מ, ביהמ\"ד למורים של ר\"ר וייס בוירצבורג, ישיבת \"נר ישראל\" בבולטימור אצל הרב רודרמן. נסמך מאת: ר\"י רודרמן, ר\"ש שוואב, ר\"י קלאוואן. רב בית היתומים ביונקרס-ניו יורק, מאנטנדייל-ניו יורק, מנהל ביהמ\"ד למורות \"בית יעקב\". חבר באגודת ישראל."},{"i":40837,"n":"צביק, בן ציון מנוברדוק וכפר גנ","f":"פסח דוד","bt":"תרמו","bp":"נוברדוק","b":"תלמיד ישיבות מיר, נוברדוק, וולוזין, כוול ברודסקי, ועוד. נסמך מאת: רי\"מ אפשטין, הר\"מ מסלונים, ר\"ש מוולוזין, ועוד. רב בברעסק-תרעב, אורעצי-תרעד, אוסיפוביץ-פלך מינסק-תרף, ווזניסנסק-תרפד, עלה לארץ-תרצד וכיהן כרב בכפר גנים, ויסד ישיבה שם. עסקן לבנית בתי טהרה ברוסיה, ופעל למען הישיבות וולוזין וסלוצק."},{"i":40838,"n":"צבע = סבע - משפחה","b":"משפחה שהגיע מהעיר סאמורה בספרד, והתישבו בחלקם בעיר סאלי-מרוקו, ראש המשפחה היה ר אברהם בעל \"צרור המור\". וחותנו של ר יוסף קארו ר יצחק צבע - מבני המשפחה."},{"i":40839,"n":"צבעח, יצחק ממרוקו ומצרים","b":"מחכמי מרוקו-שנות ה-ש', עבר למצרים."},{"i":40840,"n":"צברדלינג, צבי מזבורוב","k":"בעל אבני זכרון","b":"חיבר \"אבני זכרון\"."},{"i":40841,"n":"צברי, יצחק מתימן","k":"בעל מאורי אורים","b":"מקובל מחכמי תימן- במאה ה-19 וה-20. חיבר \"מאורי אורים\" בקבלה - בכת\"י."},{"i":40842,"n":"צברי, משה מתימן","b":"דיין בחיידאן-צפון תימן - בשנות ה-ש."},{"i":40843,"n":"צברי, סעדיה מתימן","b":"מחכמי צנעא-תימן-תקלה, ונזכר בפנקס בית הדין."},{"i":40844,"n":"צגייר, ברוך הכהן","k":"בעל זרע ברוך","dt":"תרעד - י תשרי","b":"מרביץ תורה בג'רבא, חיבר \"זרע ברוך\", נפטר בגיל 20"},{"i":40845,"n":"צגיר(צעיר), יפת הרופא הקראי","f":"דוד בן שמואל","k":"אלחכים אלצאפי","b":"מחכמי הקראים-שנות ה-ד'תתק. חיבר שו\"ת, ספר מצוות בערבית (חלק ממנו תורגם לעברית בידי ר שמואל בן שלמה הכהן מדמשק-תפב)."},{"i":40846,"n":"צדוק","f":"משה פנחס חריף מלבוב","k":"צדוק דער רייכער","b":"חתנו - ר דוד פרנס מדובנא."},{"i":40847,"n":"צדוק (יצחק) גאון סורא","f":"ישי (אשי)","b":"גאון סורא-ד'תקעו (816), בנו ר נחשון גאון. חיבר תשובות ותקנות - מתקנותיו שבועה על הקרקעות בזמן הזה - כנגד דין התלמוד, וכן פסק מעין קנס על חבלה."},{"i":40848,"n":"צדוק הלוי מירושלים - א","b":"מחכמי ירושלים בתקופת הגאונים."},{"i":40849,"n":"צדוק מארץ ישראל","f":"יאשיהו","b":"מחכמי ארץ ישראל בתקופת הגאונים, אבד בימי אליהו בן אביתר גאון."},{"i":40850,"n":"צדוק מדובנא","b":"רב בדובנא. אחיו של ר קלמן שהיה חותנו של ר יעקב רפפורט מאוסטרהא."},{"i":40851,"n":"צדוק מהורדנא","f":"אברהם","dt":"תקכב - טז טבת","dp":"הורדנא","b":"מחכמי הורדנא."},{"i":40852,"n":"צדוק מירושלים","f":"עובדיה","b":"מחכמי ירושלים, נזכר במכתב ר משולם מוולטרא, חתם על כתב שליחות ר אברהם הלוי בשנת רטז."},{"i":40853,"n":"צדוק ממצרים","b":"מגדולי חכמי דורו-שנת ש',מרביץ תורה במצרים"},{"i":40854,"n":"צדוק מצירין","k":"בעל שפתי צדק","dt":"יג טבת","b":"רב בגירטיגאלי,צירין-תר\"ס"},{"i":40855,"n":"צדוק ן, משה מאלגיר","bt":"קך - בערך","dt":"רץ - בערך","b":"רב ומלמד תורה בברשך-אלגיר. נזכר בשו\"ת ריב\"ש אודות המחלוקת שהיה בינו לבין רב הקהל ר שמואל חלאיו."},{"i":40856,"n":"צדוק, שלום מאלגיר","f":"אברהם","dt":"תרכז","dp":"ווהראן","b":"רב בווהראן. בשנת פטירתו נפטרו 9 חכמים מראשי קהלת ווהראן."},{"i":40857,"n":"צדוק, שלמה מתימן","k":"בעל אהל שלמה","dt":"תשמג","dp":"ישראל","b":"מחכמי תימן, עלה לארץ."},{"i":40858,"n":"צדיק ן, יוסף מספרד","f":"צדיק","k":"בעל עולם קטן","dt":"ד'תתקט","b":"מחכמי ספרד, פייטן ומשורר, דיין בקורדובה-ד'תתצח. פיוטים ממנו במחזור ספרד."},{"i":40859,"n":"צדיק נחמה גרשון משלוניקי","b":"סגינהור. מנצח באגודת \"הלל וזמרה\", והו\"ל עם חננאל חיים חסיד קובץ פיוטים."},{"i":40860,"n":"צדיק, אברהם ממצרים","b":"גביר מחכמי מצרים, יסד דפוס עם האחים אברהם ויעקב יתום שהגיעו מקושטא למצרים."},{"i":40861,"n":"צדיק, אליהו הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'."},{"i":40862,"n":"צדיק, יהודה מקושטא","b":"גביר מעדת הקראים בקושטא-תי, עשה הסכם עם קהלת הקראים בחתימת רבני קהלת קושטא."},{"i":40863,"n":"צדיקה, יהודה מג'רבה","b":"מגדולי רבני ג'רבא,מרביץ תורה"},{"i":40864,"n":"צדיקה, יצחק מג'רבה","k":"בעל זרעו של יצחק","dt":"תרם","b":"תלמיד ר יצחק טייב, ור ישועה בסיס. רב בג'רבא. חתן ר מעתוק חדאד - הרב הראשי בג'רבה. מתורתו ב\"קרן דוד\" - גרבה תרעו."},{"i":40865,"n":"צדיקוב, חיים אלחנן מרומשישוק","f":"יהודה ליב","k":"בעל מורה חיים","bt":"תקעג","dt":"תרמג","b":"מגיד בליטא. מקובל על גדולי דורו כר יצחק אלחנן, ר יוסף סולוביציק, ועוד. חיבר לספרו מבוא גדול בחקר האמונה."},{"i":40866,"n":"צדיקוב, שלום בצלאל גליקסמן","k":"בעל צדה לדרך","b":"רב בארה\"ב-תרנו."},{"i":40867,"n":"צדנר, יוסף","k":"בעל ויוסף אברהם","bt":"תקסד","bp":"גלוגא","dt":"תרלו - כו תשרי","dp":"ברלין","b":"תלמיד בישיבת ר עקיבא איגר, מורה בשטרליץ, ברלין - בבית הגביר אשער, ובהשתדלות הגביר נתמנה למשגיח בספריית המוזיאום הבריטי-תרה כ-25 שנה, פרסם רשימות ספרים, הו\"ל פירוש ראב\"ע לאסתר עם הקדמה בשם \"ויוסף אברהם\""},{"i":40868,"n":"צדק, נחמן מטשעטשליאק","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":40869,"n":"צדקה, יהודה מירושלים","b":"ראש ישיבת פורת יוסף בירושלים."},{"i":40870,"n":"צדקה, יצחק","b":"מחכמי חברון, רבו של ר חיים יצחק קריגל, בשנת תקד חתם על כתב שליחות ר אברהם גדיליה."},{"i":40871,"n":"צדקה, יצחק מחברון","b":"רב בחברון. חתם על כתב שליחות ר אברהם גדיליה-תקד. תלמידו - ר חיים יצחק קריגל."},{"i":40872,"n":"צדקה, יצחק מסופיה","b":"דיין בסופיה-שנות ה-תק' בזמן רבנות ר ראובן בן יעקב, והיה מחלוקת כנגדו עד שהורד מתפקידו. נזכר ב\"שם יוסף\" לר יוסף אליקים, \"שם יוסף\", \"מכתם לדוד\", \"באר מים חיים\"."},{"i":40873,"n":"צדקה, שמואל מבגדד","bt":"תקץ","bp":"בגדד","dt":"תרע - ו תשרי","dp":"בגדד","b":"מחכמי בגדד, תלמיד ר אלישע, וחברו של ר ראובן בלבול. נספד ע\"י ר יעקב בנו של ה\"בן איש חי\"."},{"i":40874,"n":"צדרבוים, אלכסנדר (ארז)","k":"בעל כתר כהונה","bp":"זמושץ","b":"משכיל, סופר, עורך \"המליץ\". התגורר בלובלין-1835. חיבר ספר ביקורתי לתולדות החסידות בשם \"כתר כהונה\"."},{"i":40875,"n":"צדרבוים, חיים ישעיה","dt":"תרף - יא כסלו","b":"חתנו - ר מנחם זמבא בעל \"תוצאות חיים\"."},{"i":40876,"n":"צהל ן, יעקב מירושלים - ב","b":"מחכמי ירושלים-שנות ה-תר'. פסקים ממנו ב\"פסקי חלה\" לר\"י קורונל."},{"i":40877,"n":"צהל ן, יצחק ממצרים","b":"רב במצרים-תם בזמן מהר\"י זיין, שהספידו ב\"שערי תורה\""},{"i":40878,"n":"צהל, בנימין משלוניקי","b":"מדפיס בדפוס המנוח בצלאל אשכנזי בשלוניקי-תקכו."},{"i":40879,"n":"צהלון יעקב בן יצחק","bt":"1630","dt":"ה'תנג 1693","bk":[["אוצר החיים",""],["מרגליות טובות",""]]},{"i":40880,"n":"צהלון, אברהם מצפת ואיטליה","f":"יצחק","k":"ראבי\"ץ-בעל מרפא לנפש","dt":"שס","dp":"צפת","b":"מחכמי צפת ומתלמידי הארי, נכדו של ר יצחק קארו בעל \"תולדות יצחק\" שהיה דודו של ר יוסף קארו. היה שליח בבגדד-שנג ושהה בבית הגביר יצחק טובה ושם בספרייתו חבר את ספריו. חיבר ספר \"מרפא לנפש\" ונציה שנה,\"יד חרוצים\" ונציה שנח, ועוד"},{"i":40881,"n":"צהלון, ידידיה","f":"יום טוב צהלון","b":"רב-שנת ת\"פ"},{"i":40882,"n":"צהלון, יום טוב מצפת - הנכד","f":"עקיבא","dt":"תנז","dp":"ירושלים","b":"מחכמי צפת, נכד ר יום טוב צהלון הראשון, בשנת תטו בשליחות באירופה יחד עם ר דוד הלוי. הדפיס את שו\"ת זקנו בונציה תנד והוסיף הקדמה משלו (לפי בניהו בניגוד לדעת יערי). עבר למצרים ושם היה בימי התגלות שבתי צבי והיה ממתנגדיו, כפי שמעיד ר יעקב ששפורטש שכנראה הכירו מימי שליחותו באמשטרדם או בהמבורג. עלה לירושלים סביב שנת תנד. היה חבר בבית דינו של ר משה ן חביב עם ר יעקב מולכו. מכתבים ותשובות ממנו. נספד בספר \"פני שלמה\" לר שלמה אמאריליו. חיבר תשובות וחדושים על השס שלא נדפסו. (האם שני חכמים באותו השם?)"},{"i":40883,"n":"צהלון, יום טוב שלום מצפת -הזקן","f":"משה לפי רוזניס עקיבא","k":"בעל לקח טוב","bt":"שיח","bp":"צפת","dt":"שצח - אחרי","dp":"צפת","b":"מחכמי צפת. תלמיד ר משה מטראני, נסמך על ידי ר משה אלשיך והיה מתלמידי הארי. בשנת שמז הגיע לדמשק וארם צובא בגלל פרעות הדרוזים. היה חברו של ר ישראל נג'ארה בדמשק. חזר לצפת וברח לפקיעין (בוקיעא), שם חתם על פסקים. היה בצידון וכן בשליחות באיטליה והולנד, ובמצרים ותורכיה, לשיקום הקהלה בצפת. חתנו היה ר יוסף בן טבול מתלמידי הארי. חיבר \"לקח טוב\" והגישו לאביו כמשלוח מנות בפורים, נדפס צפת שלז, ועוד. (האם שני חכמים באותו השם? - בעל \"מגן אבות\")."},{"i":40884,"n":"צהלון, יעקב מרומי","f":"יצחק","k":"בעל אוצר החיים","bt":"שץ","bp":"רומא","dt":"תנג","dp":"פיררה","b":"רב ורופא ברומי, פיררה. חיבר \"אוצר החיים\" ונציה תמג, ועוד. אחד משלושת רבני פיררה שעליהם אמר ר נתנאל סגרי כי הם המופלאים בדורם."},{"i":40885,"n":"צהלון, יצחק מברושה","b":"רב בברושה-שץ."},{"i":40886,"n":"צהלון, מרדכי מאיטליה - א","f":"יעקב","k":"בעל מגלת נהרות","dt":"תקט - כח כסלו","b":"רב ורופא בפיררה-תפח בזמן ר שבתי ריקנטי ור יצחק למפרונטי, רב בליוורנו, רופא וראש ישיבה-תק. חיבר \"מגלת נהרות\" אודות הנס בשיטפון - נדפס תסז. חיבר פיוט על נס האש בחצר היהודים - תמח. תשובות ממנו בספרי חכמי דורו - \"פחד יצחק\" \"שמש צדקה\" \"עדן ערוך\" ועוד."},{"i":40887,"n":"צהלון, מרדכי מאיטליה - ב","f":"יעקב","k":"בעל מציץ ומליץ","dt":"תקע - ח כסלו","b":"רב כולל,חכם השלם,מגדולי רבני איטליה,רב בפירארה. ?? לבדוק אם חכם אחד או 2 באותו השם ??"},{"i":40888,"n":"צהלון, משה ממראקש","b":"מחכמי מראקש-שנות ה-תק'. שירים ממנו ב\"דברי חכמים\" לר אליעזר אשכנזי."},{"i":40889,"n":"צובל, יצחק מאיר מפאקש","f":"שלמה מטירנא","dt":"תשד","dp":"אושוויץ","b":"תלמיד השב\"ס, חתן ר משה ישכר בר שלזינגר מפאקש, ועבר לשם. מחכמי פאקש. נספה בשואה."},{"i":40890,"n":"צובל, משה נחום מירושלים","f":"שלמה מטירנא","bt":"תרלח","bp":"טירנא","dt":"תשכב - כז אד\"א","dp":"ירושלים","b":"תלמיד השב\"ס, ור שלמה צבי שטרסר מדברצין. חתן ר משה קורניצר מפאראד וירושלים. עורך עתונים וכתבי עת בוינה, קעלין-תרע, בודפשט, פרשבורג וברלין-תרף. עלה לירושלים-תרצט."},{"i":40891,"n":"צובל, נחום מפרשבורג","b":"עורך שבועון יהודי בגרמנית \"יידישע פאלקסצייטונג\" - פרשבורג תרעט."},{"i":40892,"n":"צובל, שלמה מטירנא","b":"דיין בטירנא. בזיוו\"ש חתן ר משה שטרנברג מאטש. בניו - ר יצחק מאיר צובל מפאקש ור משה נחום מירושלים."},{"i":40893,"n":"צוברי, שלמה מתימן","b":"מחכמי צנעא במאה ה-19, רבו של ר סעדיה בן יוסף צוברי."},{"i":40894,"n":"צווארעצער, אברהם ממינסק","f":"יהודה","dt":"תריג - יד ניסן","b":"מחכמי מינסק."},{"i":40895,"n":"צוובנר, א' ש' מירושלים","f":"אברהם שאג-צוובנר"},{"i":40896,"n":"צוובנר, ישכר בער מירושלים","f":"אברהם שאג","b":"חתן ר אהרן בער מטרעביטש וירושלים. חדושים ממנו ב\"הירח\", ועוד."},{"i":40897,"n":"צוובנר, מרדכי מירושלים","b":"מחכמי ירושלים, תעודת חבר-תרסט מחברת שערי חסד."},{"i":40898,"n":"צווקין, דוד מלובלין","b":"נכד האדמור ממרקישוב, ונכד ר עוזיאל מייזלש בעל \"עץ הדעת טוב\". עורך \"העץ\" - לובלין תרצג."},{"i":40899,"n":"צווקין, עוזר מלובלין","b":"מדפיס בלובלין-תרצד."},{"i":40900,"n":"צוזמיר, אבא מאוסטרהא","b":"אב\"ד אוסטרהא. הסכים על \"תו יהושע\"-תרלז, \"הר ציון\"-תרמו."},{"i":40901,"n":"צוזמיר, יעקב מצוזמיר","f":"שמואל בן תנחום","k":"בעל בית יעקב","b":"חתן ר יצחק איזיק הלפרין מטיקטין. רב בצוזמיר-תכ. נשא ונתן עם הש\"ך ועוד. חתנו - ר יהושע מאפטא. (ראה גם ר יעקב מחנטשין)."},{"i":40902,"n":"צוזמיר, יקותיאל אשר זלמן מסטר","f":"מנחם נחום מסטרי","k":"בעל שות מהריא\"ז","bt":"תקן","bp":"רוזדול","dt":"תריח - כא ניסן","b":"תלמיד בעל הקצות וההדיר את חדושיו. חתן ר יוסף אשר ארנברג מפרמישלא. רב בסטרי, פשמישל על מקום חותנו (והושיב שם רב מטעמו - ר שמואל זנויל הלר). בזיוו\"ש חתן ר יהושע יהודה הלברטל מברסטיצקה. בהיותו מתנגד פעל לגירוש האדמורים מסטרטין וזידיטשוב מעירו - אולם אחר כך חזר בו. חתנו ר אליהו מאיר הכהן רוזנבלום על מקומו אחריו בסטרי. חיבר \"שאלות ותשובות מהריאז ענזיל\" למברג תרמב."},{"i":40903,"n":"צוזמיר, משה מוארשא","b":"מראשי קהלת וארשא-תקסח."},{"i":40904,"n":"צוזמיר, נתן מלבוב","b":"גביר מחכמי לבוב. אחיו - ר אברהם מונש מלבוב. על משפחתו ב\"השיב רבי אליעזר\" לקרובו ר אליעזר ליפשיץ."},{"i":40905,"n":"צוזמיר, עוזר ממהליב","f":"אברהם","k":"בעל לוחות העדות","bp":"מהליב","b":"נכד ה\"שער משפט\". גר בקמניץ פודולסק. חיבר \"לוחות העדות\" למברג תרכה."},{"i":40906,"n":"צוזמיר, ענזיל מטסרי","f":"נחום","dt":"תריח - כא ניסן","b":"רב בסטרי","bk":[["מהריא\"ז ענזיל – שו\"ת",""]]},{"i":40907,"n":"צוזמיר, צבי","f":"בנימין","k":"חתן הרמ\"א","b":"רב-שנת ת\"כ"},{"i":40908,"n":"צוזמיר, שלמה נפתלי הרץ מצורטקו","f":"נחום","b":"חתן ר שמחה ויטלש מבוברקא. רב בצורטקוב על מקום ר יעקב נתן רוזנצוייג. השאיר כתבים. בנו ר מנחם נחום אריה ליבוש אב\"ד זלישטשיק ואדמור בקראקא."},{"i":40909,"n":"צוזמיר-ריכנברג, מנחם נחום אריה","f":"שלמה נפתלי מצורטקוב","k":"אדמור מזלישטשיק","bt":"תקסו","dt":"תרמו - ו אלול","b":"תלמיד ר צבי הירש מזידיטשוב. חתן ר דוד יעקב הלפרין מבוליחוב. רב בצורטקוב על מקום אביו, בוליחוב, זלישטשיק-תקצב בהמלצת הישועות יעקב. נאלץ לברוח בגלל הלשנה ושינה שמו לריכנברג. בזיוו\"ש חתן ר שמואל הלר מפרמישלא. התישב בקראקא וכיהן כאדמור מזלישטשיק - כנגד עצת הדברי חיים - ולכן פרצה מחלוקת והצטרף לצד סדיגורה במחלוקתם עם צאנז. בנו ר מרדכי זיסר ריכנברג רב ואדמור באושפיצין - רצה למלא מקום אביו בקראקא. חיבר \"מעון אריה\" קראקא תרנז."},{"i":40910,"n":"צויבל, אלימלך","f":"דוד מלנצהוט","dt":"תרפו","b":"תלמיד ר יהושע חריף מסוקולוב. חסיד ר אלעזר ויסבלום מרישא. חתן נכדת בעל \"שובע שמחות\""},{"i":40911,"n":"צויג משה יונה בן מאיר","bt":"1909","dt":"ה'תשכג 1963","bk":[["אהל משה",""]]},{"i":40912,"n":"צוייג, יוסף מפוטוק זלוטי","f":"משה יונה הלוי מפוטוק","k":"בעל פורת יוסף","bt":"תרלו","dt":"תשיז","b":"חתן הנגיד ר דב בר צימט מפודהייץ. רב בפוטוק-זלוטי - תרסב על מקום אביו, עבר לארה\"ב-תרפה וכיהן כרב בברונזויל-ניו יורק. חיבר \"פורת יוסף\" בילגוריא תרצג. ?? לא באוצר ??"},{"i":40913,"n":"צוייג, משה יונה אלתר מזבורוב","f":"מאיר הלוי מזבורוב","k":"בעל אהל משה","r":"אב\"ד שומרי הדת אנטוורפן","bt":"תרסט","bp":"זבורוב","dt":"תשכג","b":"רב בפוטוק-זלוטי, אטיק-מאהליב. חתן ר טוביה עלנבויגן, ובזיוו\"ש חתן ר יהונתן אסטרייכר מטשנגר. ממיסדי צא\"י בפוטוק. ניצל מהשואה ועלה לירושלים-תשא, חסיד בלז ומקורב למזרחי. רב בלונדון-תשיב, אנטורפן-תשיג. חיבר \"אהל משה\" ירושלים תשיט. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח.","bk":[["אהל משה – שו\"ת",""]],"e":"תרס\"ט-תשכ\"ג"},{"i":40914,"n":"צוייג, משה יונה מפוטוק זלוטי","f":"אלכסנדר סנדר הלוי","k":"בעל מי באר","bt":"תר","dt":"תרסב","b":"רב בפוטוק-זלוטי-תרלה. חיבר \"מי באר\" 6 קונטרסים נדפסו בסף \"פורת יוסף\" לבנו ר יוסף שמילא את מקומו אחריו. ?? לא באוצר ??"},{"i":40915,"n":"צוייגנהאפטיג, דוד מסוסנוביצא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":40916,"n":"צוייד, שמואל מתונס","dt":"תקלב","b":"מחכמי תונס-תקיח, תלמיד ר יוסף ביסמוט, חתם על הסכמות עם חכמי תונס, תשובה ממנו ב\"משחא דרבותא\". תלמידו ר עוזיאל אלחאייך בעל \"משכנות הרועים\"."},{"i":40917,"n":"צוייס, בן ציון מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":40918,"n":"צויקל, יונה מזלוטשוב","f":"דב","k":"בעל ידיד נפש","b":"מחכמי זלוטשוב ובעל תפלה. חיבר \"ידיד נפש\" זלוטשוב תרסד. היגר לארה\"ב."},{"i":40919,"n":"צולא, יעקב מירושלים","dt":"תקד - ב חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":40920,"n":"צולטאן, אברהם ממרוקו","dp":"אספי(מרוקו)","b":"צדיק במרוקו"},{"i":40921,"n":"צולטאן, דניאל דינר מפאס","k":"בעל דברי חכמים","bp":"דבדו-מרוקו","b":"שו\"ב מחכמי פאס-תק\"מ-ת\"ר. חיבר \"דברי חכמים\""},{"i":40922,"n":"צולטאן, ישועה מאלגיר","f":"מרדכי","bt":"תף","dt":"תקן - בערך","b":"רב ור\"מ בתלמסאן. נזכר במכתב ר אברהם ן סאמון לר יצחק מרעלי. חיבר ספר זכרון עניני הקהלה ותקנותיה."},{"i":40923,"n":"צולטאן, משה","b":"רב ומשורר כנראה מתלמסאן או מווהראן. מפיוטיו שרד פיוט ידוע - בכת\"י."},{"i":40924,"n":"צולטאן, משה מדברו-מרוקו","bt":"[תץ]","dt":"תקן - בערך","b":"מחכמי דברו-מרוקו."},{"i":40925,"n":"צולטאן, שלום מאלגיר","f":"ישועה מתלמסאן","bt":"תקך","dt":"תר - בערך","b":"מחכמי תלמסאן, סופר ומשורר. חתם עם רבני תלמסאן על הסכמה לספר הזכרון - תרה."},{"i":40926,"n":"צולטאן, שמואל מאלגיר","bt":"תרי - בערך","dt":"תש - בערך","b":"רב בתלמסאן, דיין אצל ר חיים בלייח. הו\"ל \"שירות ותשבחות\" תונס תרסג - יחד עם ר א' אלקובי ור א' בן סאמון."},{"i":40927,"n":"צולשאן, צבי הרש מצעהלים","b":"מחכמי צעהלים. חתנו ר שמעון לפלר מבודפשט. בנו ר שלמה זלמן מצעהלים."},{"i":40928,"n":"צולשאן, שלמה זלמן מצעהלים","f":"צבי הירש מצעהלים","b":"מחכמי צעהלים. חתנו - בן אחותו - ר ידידיה צבי הלוי לפלר מבודפשט."},{"i":40929,"n":"צומבר, דב בער מלאסק וברלין","k":"בעל מורה דרך","bt":"תקפא","bp":"לאסק","dt":"תרמד","dp":"ברלין","b":"תלמיד ישיבת ר יוסף שפירא באינורצלב, ישיבת ר יעקב עטלינגר באלטונא, בביהמ\"ד לרבנים בוירצבורג וברלין. ר\"מ בביהמ\"ד לרבנים בברלין. הו\"ל \"הלכות פסחים\" עם \"דבר הלכה\", ועוד. פרסם מאמרים ב\"המגיד\", ועוד."},{"i":40930,"n":"צונאמן, חיים מאיר מקושיץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":40931,"n":"צונזר, אליקום מארה\"ב","f":"שרגא","k":"בעל מכירת יוסף","bt":"1836","bp":"וילנא","dt":"1913","dp":"ניו יורק","b":"תלמיד ישיבת מייליס בוילנא. \"בדחן\" מקצועי בחתונות, ומשורר. היגר לארה\"ב וחיבר כ-600 שירים. מקורב לציונות. שיריו נדפסו בקונטרסים קטנים בוילנא. חיבר אוטוביוגרפיה בשם \"צונזערס ביאגראפיע געשריעבען פון איהם אליין\"."},{"i":40932,"n":"צונץ, אהרן","f":"אריה ליב צינץ","dt":"תרכ - ז תשרי","b":"רב בטורבין תקצ\"ח"},{"i":40933,"n":"צונץ, אלכסנדר מאוסטרליץ","dt":"תעא - כא חשון","b":"רב באוסטרליץ"},{"i":40934,"n":"צונץ, אנשיל מפפד\"מ","f":"הרץ","dt":"תקלו - כב תשרי","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תקך ודיין, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":40935,"n":"צונץ, אריה ליב חריף מפלוצק","f":"משה","k":"בעל משיבת נפש","r":"רב ופוסק","bt":"תקכה","bp":"פינצ'וב","dt":"תקצג - ג אייר","dp":"ורשה","b":"איש מופת,רב בפלאצק, פראגה, גר בוארשא.","bk":[["גרש ירחים",""],["אילת אהבים",""],["ברכת השיר - הגדה של פסח",""],["גט מקושר",""],["חידושי מהרא\"ל",""],["טיב קידושין",""],["מלא העומר",""],["מעייני החכמה",""],["פני אריה",""],["שמחת יום טוב",""]],"e":"תקכ\"ח-תקצ\"ג","co":{"b":"50.519038,20.528600"}},{"i":40936,"n":"צונץ, אריה ליב מהלישוי ופינטשו","f":"נפתלי הירץ","b":"רב בהאלישוי, פינטשוב. חתנו - ר נתן נטע מאיבשיץ, ונכדו ר יונתן איבשיץ."},{"i":40937,"n":"צונץ, דוד אריה ליב מצאנז","f":"שמריה מצאנז","k":"בעל גדולת יהונתן","bt":"תרן","bp":"צאנז","dt":"תש","b":"מחכמי צאנז חתן ר אלתר אליעזר מבוקובסק. עבר לבוקובסק וחיבר שם את ספריו, חזר לצאנז. נספה בשואה. חיבר \"גדולת יהונתן\" פיעטרקוב תרץ. ?? באוצר יש עירוב בינו לר אריה ליב בן משה ??"},{"i":40938,"n":"צונץ, יהודה ליב משיניבה","f":"שמחה","b":"רב בשיניבה"},{"i":40939,"n":"צונץ, יום טוב ליפמן לאופולד","k":"בעל מורה נבוכי הזמן","bt":"תקנד","bp":"דעטמאלד","dt":"תרמו - י אד\"ב","dp":"ברלין","b":"חוקר חכמת ישראל. רב ריפורמי בברלין. פרסם ספרים ומאמרים. חיבר ספר על הפיוט והפייטנים בישראל."},{"i":40940,"n":"צונץ, יונתן","f":"אריה ליב צונץ","b":"רב בעיר חדש"},{"i":40941,"n":"צונץ, יחיאל מתתיהו מקראקא","f":"אלימלך חסיד","k":"אלתר צינז","bt":"תרז","dt":"תרמב","b":"תלמיד דודו ר חיים נתן דמבציר בעל \"כלילת יופי\". חתן ר שכנא שטרנברג. פרסם מאמרים בחכמת ישראל בעתונות העברית. חיבר \"עיר הצדק\" למברג תרלד. - ספר זה עורר מחלוקת (גם בגלל מה שכתב כנגד ה\"נחלת שבעה\") וכנגדו יצא גולדשטורף ב\"מליץ יושר\" ודודו בקונטרס \"מפלת עיר הצדק\". ?? באוצר מופיע בשם לונץ ??"},{"i":40942,"n":"צונץ, מ' יצ' יהודה ליב","dt":"תמד","b":"רב בהעלישוי,פינטשוב"},{"i":40943,"n":"צונץ, משה חיים","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":40944,"n":"צונץ, משה יהודה ליב מקראקא","b":"רב בקראקא, וינה. תשובה אליו במהרש\"ם, \"שערי בנימין\"-תרנה"},{"i":40945,"n":"צונץ, משה מפפד\"מ","b":"מחכמי פפד\"מ, היה חבר בועדה בראשות ר מיכאל שפייאר שניסחה את תקנות הקהילה-תקמד."},{"i":40946,"n":"צונץ, נפתלי הרץ","b":"מגדולי חכמי ווינה"},{"i":40947,"n":"צונץ, נפתלי הרץ","f":"אריה ליב צונץ","dt":"תצג - כט אלול","b":"רב בפינטשוב"},{"i":40948,"n":"צונץ, נתן נטע מפרשבורג","b":"דיין בפרשבורג-תקך אצל ר יצחק לנדא בעל \"מעיני הישועה\", ואצל ר מאיר ברבי. חתם על תקנות ר משה לבוב-תקיח יחד עם ר עקיבא איגר הזקן, ועל תקנות ר מאיר ברבי-תקכח."},{"i":40949,"n":"צונץ, צבי הירש","f":"אריה ליב צונץ","b":"רב בבוטאשטש"},{"i":40950,"n":"צונץ, שמחה","f":"ליב צונץ","dt":"תנו - ח ניסן","b":"רב בסטריא,ר\"מ בלבוב"},{"i":40951,"n":"צונצין, אברהם מאזמיר","b":"מגדולי אזמיר, סייע בהדפסת כמה ספרים."},{"i":40952,"n":"צונצין, אהרן מקושטא","b":"דיין ורב בקושטא-תקי. סייע בהדפסת \"נחפה בכסף\" לר יונה נבון והזכירו בהקדמתו. חתם על הסכמה לטובת כפר יסיף."},{"i":40953,"n":"צונצין, חיים יהושע","f":"משה","b":"בנה בית כנסת באיזמיר-תקיג (ונחשב לעתיק ביותר באזמיר), סייע בהדפסת \"מאיר בת עין\" לר מאיר ביקייאם."},{"i":40954,"n":"צונצין, יהושע מאזמיר","dt":"תרלח - י ניסן","dp":"אזמיר","b":"מרבני אזמיר, הספדו נדפס ב\"אברהם את ידו\" לר\"א בן חיים פלאג'י."},{"i":40955,"n":"צונצין, מנחם מאזמיר","f":"חיים יהושע","dt":"תרכב - לפני","dp":"אזמיר","b":"מחכמי אזמיר, נספד ב\"שפתי רננות\" לר רחמים אריה אברהם הכהן אריאש - אזמיר תרכב."},{"i":40956,"n":"צונצין, מנחם מקושטא","dt":"תרמד - ז טבת","dp":"קושטא","b":"רב בקושטא. אפוטרופוס על יתום-תריג, ממונה על הקדש ר יום טוב ברוך-תרכג. ממתנגדי ר יעקב אביגדור שנתמנה לרב ראשי בקושטא והיה מחלוקת על כך-תרכג. רב שני בקושטא אחרי ר מאיר יעיש-תרמד. תלמידו ר רפאל ביטראן המזכירו בספרו \"זכור לטוב\"."},{"i":40957,"n":"צונצין, שמואל","f":"יהושע","b":"תשובה ממנו ב\"נחלה ליהושע\"."},{"i":40958,"n":"צונצין, שמואל","b":"אחד המדפיסים של \"שמע יעקב\"."},{"i":40959,"n":"צופיוף, דוד הכהן מבוכרה","dt":"תרסד - יג תמוז","dp":"ירושלים","b":"עלה לירושלים-תרן, ממיסדי שכונת \"רחובות הבוכרים\", חזר לבוכרה, ולירושלים-תרסא ובנה בית מרחץ וביכ\"נ בשם \"מגן דוד\", סייע בהדפסת כמה ספרים."},{"i":40960,"n":"צופיוף, שלמה הכהן מבוכרה","f":"דוד","k":"בעל בית דוד שלמה","bt":"תרלו","bp":"בוכרה","dt":"תרצו - יב אלול","dp":"ירושלים","b":"גביר מחכמי בוכרה, ביקר בירושלים-תרסב, ותרסד ויסד ישיבה בירושלים בשם \"מדרש שלמה\", בנה בית כנסת בסמרקנד-תרסו. ברח מהקומוניסטים והגיע לירושלים-תרפא וכיהן כנשיא העדה הבוכרית בירושלים על מקום ר שלמה מוסאיוף. הו\"ל סידור \"בית דוד ושלמה\" ועוד."},{"i":40961,"n":"צוקר אליעזר בן שלום דב","bt":"1859","dt":"ה'תרפ 1920","bk":[["דמשק אליעזר",""],["מגדנות אליעזר",""],["מתוק מדבש",""]]},{"i":40962,"n":"צוקר, אליעזר מברגסאס","f":"שלום דב מרישא","k":"בעל מגדנות אליעזר","bt":"תריח או תרטו","bp":"רישא","dt":"תרף - י שבט","b":"תלמיד הדברי חיים מצאנז, חסיד מונקטש. חתן ר אברהם יהודה ליב הכהן שוורץ מברגסאס בעל \"קול אריה\". רב בברגסאס-תרמה על מקום חותנו. בנו ר חיים על מקומו אחריו. חיבר \"מגדנות אליעזר\" ברטיסלבה תרפא, \"דמשק אליעזר\" ברגסאס תרצב, ועוד, מתורתו ב\"וילקט יוסף\"."},{"i":40963,"n":"צוקר, אליעזר משיניבה","f":"יצחק מאיר משיניבה","b":"רב בשיניבה על מקום אביו, בנו ר חיים אהרן על מקומו אחריו."},{"i":40964,"n":"צוקר, בן ציון מטורטשין","f":"מנשה חיים מטורטשין","bt":"תרמה-ח","b":"תלמיד ישיבות נוברדוק, זעטיל. חתן ר נתן אריה רבינוביץ מביחוב(=ביכוב). מו\"צ בטורטשין-ווהלין-תרסח. נסמך מאת ר מרדכי מסלונים."},{"i":40965,"n":"צוקר, חיים אהרן משיניבה","f":"אליעזר משיניבה","k":"בעל טל חיים","bt":"תרם","dt":"תשג","dp":"שיניבה","b":"רב בשיניבה-תרפב על מקום אביו. נספא בשואה. חיבר \"טל חיים\" ניו יורק תשמה - ע\"י נכדו ר יעקב אשר זליג צויבל."},{"i":40966,"n":"צוקר, חיים מברגסאס","f":"אליעזר מברגסאס","bt":"תרם","dt":"תשד","b":"חתן ר יעקב פרץ זילברמן. רב בהאלאס-תרסב, ברגסאס על מקום אביו. לאחר שסירב בהוראת אביו לרבנות קאשוי. נחשב בעיני רבני דורו והתכתב עם רבים מהם. נספה בשואה ורוב כתביו אבדו. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה, \"לקט ששנ\"ה\" - סטמר תרצד, \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב, \"הנשר\" - טירנוי תרצג-תשד, \"תצא תורה\" - קריניצה תרצא, \"וילקט יוסף\"."},{"i":40967,"n":"צוקר, יוסף יהודה מאפטא","f":"יחיאל מברנוב","bt":"תקפו","dt":"תרסו","b":"רב בפשדבורז, וידמע, אפטא-תרז, קראקא-תרנו. בזיוו\"ש חתן ר נתן שפיגלגלס מוארשא."},{"i":40968,"n":"צוקר, יוסף שאול מלמברג","b":"מחכמי למברג. מעורכי \"אור תורה\" - לבוב תרפו. פרסם מאמרים ב\"יבנה\" - לבוב תרפט."},{"i":40969,"n":"צוקר, יחיאל מברנוב","b":"רב בברנוב. אביהם של ר יוסף יהודה מאפטא ור יצחק מאיר משיניבה."},{"i":40970,"n":"צוקר, יצחק אריה","b":"דומ\"צ בריטשע-תר\"ס"},{"i":40971,"n":"צוקר, יצחק מאיר משיניבה","f":"יחיאל מברנוב","bt":"תקף","dt":"תרנט","b":"רב בשיניבה אצל ר יחזקאל שרגא הלברשטט שהחשיבו מאוד. בנו ר אליעזר על מקומו אחריו."},{"i":40972,"n":"צוקר, ירוחם פישל","f":"מיכאל גרשון","bt":"תרלט","b":"רב בפיאנטקא-פלך קאליש-תרסו."},{"i":40973,"n":"צוקר, ישכר בער מוישניצה","b":"מחכמי וישניצה - תשובה אליו \"תפארת יוסף\"."},{"i":40974,"n":"צוקר, מנשה חיים מטורטשין","b":"רב בטורטשין-תרם ובנו ר שלום על מקומו אחריו."},{"i":40975,"n":"צוקר, מרדכי יהודה","f":"שלמה מאלטשטט","k":"הו\"ל ישועות ישראל","b":"חתן ר יהושע אלכסנדר גולדרייך מאלטשטט. הביא לדפוס ספר חותנו \"ישועות ישראל\" פרמישלא תרמז."},{"i":40976,"n":"צוקר, מרדכי מפאריצק","f":"שמואל","bt":"תרלז","b":"חתן ותלמיד ר שמעון מצאצאי בעל תוספות יו\"ט. רב בקאפציבקה-תרס, פאריצק(=פריצק)-ווהלין-תרסח על מקום חותנו. נסמך מאת: ר יצחק שלמה יואל מראוונא, ר שמואל מראוונא, ר מיכל מסלויטא, ר שלום שכנא ממאצוב בעל \"משמרת שלום\"."},{"i":40977,"n":"צוקר, משה אהרן מוארשא","b":"מו\"צ בוארשא-תרצה."},{"i":40978,"n":"צוקר, שלום מפולנאה וטורטשין","f":"מנשה חיים","bt":"תרלה","b":"נכד ר יוסף מטומשוב, ונכד-אבי אמו ר שמחה מסיקאל-ליד בלז. חתן ר יחיאל מיכל מברעזן. מו\"צ בפולנאה-תרנה, רב בטורטשין-ווהלין-תרסז על מקום אביו. נסמך מאת ר אהרן מטשודנוב."},{"i":40979,"n":"צוקר, שלמה מהאלאס","f":"אליעזר מברגסז","k":"בעל באר שלמה","bt":"תרנה","bp":"ברגסאס","dt":"תשג","dp":"ברגסאס","b":"תלמיד ה\"מנחת אליעזר\" ואף התגורר בביתו. חתן אחיו ר חיים. רב בהאלאס(=נאג'י-האלאס)-מחוז סאבולץ'-תרף. ליוה את רבו בביקורו בארץ-תר\"ץ. חיבר \"באר שלמה\" ברגסאס תרפז. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":40980,"n":"צוקרברג, אלתר שלום דוד מקומרנא","f":"יעקב קופל מפשמישל","bt":"תרכח","dt":"תשג","b":"חתן ר אלכסנדר סנדר ספרין. רב בקומרנא (מטעם חסידי קומרנא). חתן ר יהודה צבי טויב מרוזדול. נספה בשואה. בנו - ר יעקב."},{"i":40981,"n":"צוקרברג, יחיאל מיכל מסטרי","dt":"תש..","b":"חתן ר פנחס חיים טויב מרוזדול. נספה בשואה."},{"i":40982,"n":"צוקרברג, יעקב","dt":"תשג","b":"רב בקומרנא"},{"i":40983,"n":"צוקרברוד, אליעזר סגל ממידן","b":"רב במיידן-תרסז. פרסם מאמרים ב\"הבונה\" - לבוב תרסד."},{"i":40984,"n":"צוקרט, אפרים פישל מגרעווא","b":"רב בגרעווא-תר\"נ"},{"i":40985,"n":"צוקרמן, אברהם","k":"בעל המתנחם","bt":"1843","bp":"אושמיאנה","dt":"1891","dp":"וארשא","b":"פרסם מאמרים ב\"המגיד\", \"השחר\", ועוד. עורך \"הבקר אור\" לגוטלבר. תרגם ספור של מ. ליהמן. חיבר גם \"בת ציון\", ועוד."},{"i":40986,"n":"צוקרמן, אהרן מהיבנוב","f":"אריה ליב מהיבנוב","bt":"תרלג","bp":"היבנוב","dt":"תרפז","b":"מחשובי חסידי בלז. חתן ר שמעון הורשובסקי מאוהנוב (בן ה\"אזור אליהו\"). ישב אצל המהרי\"ד מבלז ולמד עמו בחברותא. מחכמי היבנוב והתפרנס ממסחר."},{"i":40987,"n":"צוקרמן, אליעזר מקיעלץ","dt":"תשא","b":"רב בקיעלץ"},{"i":40988,"n":"צוקרמן, אפרים ממעזירואוב","f":"צדוק מאקירמן","bt":"תריח","b":"מצאצאי ר אליעזר מטאמאשפיל-תלמיד הבעש\"ט, נכד ר משה מויניצא. מו\"צ באזרניץ(=אזראניץ)-פודוליה-תרמב, רב במעזירואוב-פודוליה-תרמד. מתורתו ב\"דברי מלכיאל\" לר מלכיאל צבי הלוי מלומזה."},{"i":40989,"n":"צוקרמן, ברוך","f":"אהרן מהיבנוב","dt":"תרצו - בערך","dp":"היבנוב","b":"חתן ר מאיר אריק. אחיו ר דב בריש הוציא לאור מתורתו בשם \"אמרי ברוך\" בירושלים."},{"i":40990,"n":"צוקרמן, ברוך בנדט מטלנשטי","f":"קלונימוס קלמן","bt":"תרנז","dt":"תשכב","dp":"שיקגו","b":"חתן ר חיים רבינוביץ מיאסי, ובזיוו\"ש חתן ר משה הכהן גינשפורג. רב בטלנשטי, רב ור\"מ בקישינוב. ניצל מהשואה. וכיהן כרב בפריז, עבר לשיקגו-תשז ופתח שם בימ\"ד, קליבלנד."},{"i":40991,"n":"צוקרמן, דב בריש מהיבנוב- באפלו","f":"אהרן מהיבנוב","k":"בעל בית אהרן","bt":"תרסא או תרנא","bp":"היבנוב","dt":"תשלג","b":"חתן ר דוד פרנקל מהוסיאטין. מחכמי למברג ואחר כך וינה, והתכתב עם חכמי דורו. יצא בשליחות חותנו לארצות שונות לחפש כתבי יד וספרים נדירים. ניצל מהשואה ונדד לפריז איטליה ולונדון. הגיע לארה\"ב-תשב וכיהן כרב בבאפלו. הוציא לאור \"דרך החיים\" לר מנחם די לונזאנו, ועוד. חיבר \"בית אהרן\" ירושלים תשלד. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"קול תורה\" - ירושלים תרץ-תשז, \"תלפיות\" - נ\"י תשד."},{"i":40992,"n":"צוקרמן, יהודה אריה מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":40993,"n":"צוקרמן, יוסף מליטשיניץ","f":"צדוק","bt":"תרכה","b":"רב בליטשיניץ-פודוליה-תרנה."},{"i":40994,"n":"צוקרמן, יוסף ממינסק","b":"גביר מחכמי מינסק, מראשי הת\"ת במינסק - בזמן הגדול ממינסק. חתנו ר משה חיים ברוידא."},{"i":40995,"n":"צוקרמן, יצחק זאב מבריינסק","dt":"תשג","b":"אב\"ד נאווא-אוקראינה, ראש ישיבה בקרמנצוג, אב\"ד בריינסק-פלך גרודנא. פרסם מאמרים ב\"יגדיל תורה\", חתם עם גדולי ליטא עלמכתב אין תנאי בנישואין. נספה בשואה."},{"i":40996,"n":"צוקרמן, ישראל מהיבנוב","b":"מחכמי הינבוב, מנהל פנקס חברת \"במחז\"ה\"-תרם. בנו היה ר מרדכי דוד חתן רנ\"נ לייטר מלמברג - נספה בשואה."},{"i":40997,"n":"צוקרמן, מרדכי מפריישטט ואה\"ו","f":"צבי מגלייויטץ","dt":"תרנה - יד טבת","dp":"אלטונא","b":"גיסו של ר אליהו מונק. ראב\"ד בפריישטט, עבר להמבורג, מחכמי הקלויז הספרדי \"זומביל ישיבה\" באלטונא."},{"i":40998,"n":"צוקרמן, משה מאקירמן","f":"צדוק מאקירמן","bt":"תרם","b":"רב באקירמן-בסרביה-תרסו על מקום אביו?. הניח שו\"ת בכת\"י. תשובה אליו ב\"דברי מלכיאל\" לרב מלומזה. אחיו של ר אפרים ממזירוב."},{"i":40999,"n":"צוקרמן, משה מוארשא","b":"מראשי בית החסידים דברסלב \"בית אמונה\" ברחוב גזשיבוב-וארשא."},{"i":41000,"n":"צוקרמן, צבי מגלייויטץ","b":"אב\"ד גלייויטץ-שלזיה. בנו - ר מרדכי מפריישטט ואה\"ו."},{"i":41001,"n":"צוקרמן, צדוק מאקירמן","dt":"תרסו","b":"רב בחרישקיווקע-תרט\"ז,אזרניץ,אקרמן"},{"i":41002,"n":"צוקרמן, קלונימוס קלמן מיבלונוב","f":"ברוך בנדט","k":"בעל מנחת הקמץ","bt":"תרלו","dt":"תשב","b":"גדל אצל דודו ר אריה ליב מהיבנוב - לאחר פטירת אביו. תלמיד ר יחאיל מיכל כהנא שפירא בעל \"דעת נבונים\". חתן ר צבי זוסאפיל. רב ביבלונוב-תרסא על מקום ר עזריאל לנדא שעלה לארץ. רב בוינה בזמן מלחמת העולם הראשונה וחזר לעירו. מקורב לאדמורים מבלז ודזיקוב. נספה בשואה. חיבר \"מנחת הקמץ\" קולומיאה תרצז. ?? לא באוצר ??"},{"i":41003,"n":"צוקרמן, שלמה זלמן (אבינועם)","bt":"1867","bp":"סמרגון","dt":"1927","dp":"גדרה","b":"חבר אגודת \"קיבוץ נדחי ישראל\" במינסק. הצטרף לביל\"ו. עלה לארץ-תרמד והתישב בגדרה. השתתף במשלחת לאמריקה יחד עם דב ליבוביץ למכירת יינות א\"י."},{"i":41004,"n":"צוקרמן, שמואל הלוי מירושלים","bt":"תר","bp":"מזריטש","dt":"תרפט - ו אד\"ב","dp":"ירושלים","b":"עלה בילדותו לירושלים, ועבד כפועל בדפוס ישראל בק, רכש את הדפוס. הו\"ל \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":41005,"n":"צוקרמן, שמעון מהמבורג","f":"משה אפרים","dt":"תרסו - יג ניסן","dp":"המבורג","b":"תלמיד וחתן ר מ. פילכנפלד מפוזן, מחכמי המבורג, ומלמד על מקום ר ראובן פינק."},{"i":41006,"n":"צוקרמנדל, יעקב יוסף הכהן","dt":"תרפו - בערך","b":"תלמיד ר משה שמואל גלזנר מקלויזנבורג. דיין ורב באילאנדא-ליד דעש."},{"i":41007,"n":"צוקרקורן, יהושע מרדכי","b":"חסיד קוצק. חברו של בעל \"חדושי הרי\"ם\". בנו - ר בנימין זאב. מתלמידיו - ר פיבש פישל פלאטא מארה\"ב."},{"i":41008,"n":"צור ן, אברהם ממצרים","b":"רב ברשיד(=רוזיתא)-מצרים - שנות ה-ר'."},{"i":41009,"n":"צור ן, אברהם ממרוקו","f":"יהודה","b":"חכם שלם-תעא. בנו - ר יהודה."},{"i":41010,"n":"צור ן, אברהם מסאלי-מרוקו","f":"משה","b":"רב בסאלי-שנות ה-ש'. מתלמידיו - ר יצחק צבע(=סבע) מסאלי בעל \"קרני ראמים\"."},{"i":41011,"n":"צור ן, אברהם מעכו","f":"משה","bt":"תרנג","bp":"עכו","b":"ממיסדי כפר ברוך בעמק יזרעאל, פרסם מאמרים ב\"מזרח ומערב\", שירים ב\"הדים\", עבר לזכרון יעקב."},{"i":41012,"n":"צור ן, אליהו ממרוקו","f":"יעקב-יעב\"ץ","b":"מחכמי מרוקו, נפטר צעיר בחיי אביו."},{"i":41013,"n":"צור ן, אליעזר מאיטליה","f":"שלמה","b":"מגולי צרפת ופרובנס והגיע לאיטליה. רב בלמרקה-איטליה. בנו - ר יצחק די ליאון בעל \"מגילת אסתר\" על הרמב\"ם."},{"i":41014,"n":"צור ן, אפרים מאלגיר וצפת","bt":"תקם","dt":"תרי - בערך","b":"מחכמי ווהראן-אלגיר, עלה לארץ-תקצג (לאחר הכיבוש הצרפתי) והתישב בצפת. חתם על אגרות בצפת."},{"i":41015,"n":"צור ן, דוד מאגאדיר-מרוקו","f":"אשר","b":"מחכמי אגאדיר, חתם על פס\"ד-תצה עם ר שלמה כרוב."},{"i":41016,"n":"צור ן, יהודה","b":"תק\"ך"},{"i":41017,"n":"צור ן, יהודה מטיטואן-מרוקו","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תרטז עם ר\"י ן ואליד, ר יעקב אדהאן, ועוד. תוכחה ממנו ב\"צלצלי שמע\"."},{"i":41018,"n":"צור ן, יהודה ממכנאס","f":"משה או שלום-שיר חדש","dt":"תעב - יא תמוז","dp":"מכנאס","b":"בחור מחכמי סאלי, דודו של היעב\"ץ. נשרף עק\"ה במכנאס עם ר יצחק ן עמארא ובנו אהרן."},{"i":41019,"n":"צור ן, יהודה ממכנאס","dt":"תקפה - ט תמוז","b":"מחכמי מכנאס, חתם על פס\"ד עם ר אברהם ן חסין, ר חנניה בן זכרי. נספד ב\"קול יעקב\" לר יעקב בירדוגו."},{"i":41020,"n":"צור ן, יהודה ממרוקו","f":"ראובן","b":"אחיו של היעב\"ץ. חתם על פס\"ד עם ר יעקב ן מלכא, ר אברהם עטייה, ר מרדכי צבח."},{"i":41021,"n":"צור ן, יהודה ממרוקו - א","b":"מחכמי מרוקו, חתם על פס\"ד-תעו עם ר יצחק בן אברהם אצבאג."},{"i":41022,"n":"צור ן, יוסף ממכנאס","f":"ראובן","dt":"תנח","dp":"מכנאס","b":"מחכמי מכנאס, אחיו של היעב\"ץ. נזכר ב\"תקפו של יוסף\". בניו - ר יוסף, ר מנשה - נפטרו צעירים."},{"i":41023,"n":"צור ן, יעקב - יעב\"ץ","f":"ראובן","k":"בעל משפט וצדקה ביעקב","bt":"תלג","dt":"תקיג - ב טבת","b":"מגדולי חכמי מרוקו. רב בפאס, היה גם במכנאס ובטיטואן. חברו של ר יהודה ן עטר ממרוקו. נזכר אצל החיד\"א. חיבר חדושים ודרושים בכת\"י (אצל ר חיים מיכל). בסוף ימיו מינה 5 מתלמידיו בטיטואן לדיינים ונקראו בית דין של חמש. שני בניו שנקראו ראובן רבא וראובן זוטא נפטרו צעירים בחייו, בנו - ר רפאל עובד."},{"i":41024,"n":"צור ן, יעקב ממרוקו","f":"משה","b":"מחכמי מרוקו-שנות ה-ש'-ת'. אחיו של ר ראובן-אביו של היעב\"ץ."},{"i":41025,"n":"צור ן, יעקב ממרוקו - א","b":"מחכמי מרוקו. בנו - ר אברהם."},{"i":41026,"n":"צור ן, יעקב מפאס - ב","f":"שלמה שמואל","dt":"תרי - כא אב","dp":"פאס","b":"מו\"ץ בפאס. חתם על פס\"ד-תרד עם ר יעקב סירירו, ר ראובן ן צור."},{"i":41027,"n":"צור ן, יצחק ממכנאס","b":"מו\"ץ במכנאס, חתם על פס\"ד-תקצט עם ר יוסף בירדוגו, נזכר ב\"הלכתא למשיחא\"."},{"i":41028,"n":"צור ן, יצחק מפאס","f":"היעב\"ץ","b":"מחכמי פאס, נפטר צעיר בחיי אביו."},{"i":41029,"n":"צור ן, יצחק מפאס","f":"משה מספרד ופאס","dt":"שסג","b":"נולד לאביו בהיותו כבן 100 ולכן נקרא אביו - אברהם העברי. מו\"ץ בפאס, חתם על פס\"ד-שנא. נהרג בזמן לימודו (אולי על ידי אדם שהפסיד אצלו בדין). בנו - ר ראובן, ונכדו - היעב\"ץ."},{"i":41030,"n":"צור ן, מרדכי ממראקש","bt":"תרז","bp":"מראקש","b":"רב במראקש. חיבר ספרי שות ועל הש\"ס בכת\"י."},{"i":41031,"n":"צור ן, משה הזקן","b":"ממגורשי קשטיליה-ק\"נ. נכדו ר משה ן צור מפאס."},{"i":41032,"n":"צור ן, משה הנכד","f":"שמואל בן משה","k":"אברהם העברי","b":"נקרא אברהם העברי משום שנולד לו בן בהיותו כבן-100. נכד ר משה ן צור מספרד. מגדולי ספרד, לאחר הגירוש הגיע לפאס-רנ\"ב, מרביץ תורה בפאס. בניו - ר אברהם, ר שמואל, ר יצחק שנהרג עק\"ה, נכדו ר משה ן צור מצפת בעל \"מערת שדה המכפלה\"."},{"i":41033,"n":"צור ן, משה מטיטואן","b":"מחכמי טיטואן, חתם על פס\"ד-תקנח עם ר שלמה אבודרהם, ר אברהם מונסונייגו, ור שלמה רופא."},{"i":41034,"n":"צור ן, משה מסאלי-מרוקו","f":"יצחק בן משה בן שמואל","k":"בעל מערת שדה המכפלה","bp":"סאלי","dt":"תסו - ז שבט","dp":"פאס?","b":"רב פייטן ומקובל בסאלי-מרוקו, והיה גם בפאס ובמכנאס, דור חמישי למגורשי ספרד. חיבר גם \"מבוא שער השמים\", \"צלצלי שמע\" ועוד. חיבר פיוטים שנכנסו ל\"בקשות\". אחיו של ר ראובן, ודוד של היעב\"ץ. בניו - ר שלום, ר יעקב ור יהודה הקדוש (יש אומרים שר יהודה היה נכדו בנו של ר שלום)."},{"i":41035,"n":"צור ן, משה מצפת","k":"בעל מערת שדה המכפלה","b":"מקובל,מחכמי צפת-ש\"צ"},{"i":41036,"n":"צור ן, ראובן מסאלי","f":"יעקב - היעב\"ץ","bt":"תעז - בערך","dt":"תקב","dp":"סאלי","b":"מחכמי מרוקו, נפטר צעיר בחיי אביו. נספד ע\"י ר אליהו הצרפתי ב\"נער בוכה\"."},{"i":41037,"n":"צור ן, ראובן מפאס","f":"יצחק בן משה?","k":"בעל פלגות ראובן","dt":"תעג - לפני","b":"תלמיד ר מרדכי אצבאן מפאס. חתן ר יוסף ן סונבאל. מגדולי חכמי פאס-תץ. נהג שלא לאכול אורז בפסח וממנו התפשט המנהג במרוקו. אביו של ר יעקב ן צור = היעב\"ץ. אחיו - ר משה מפאס."},{"i":41038,"n":"צור ן, ראובן מפאס","bt":"תלג - בערך","b":"ברח מפני העלילה והגיע לפאס. נזכר במכתב ר יהודה טולידנו - \"אוצר המכתבים\". (אולי הוא שהיה אביו של היעב\"ץ)"},{"i":41039,"n":"צור ן, רפאל","b":"מחכמי מרוקו. נזכר ב\"אוצר המכתבים\"."},{"i":41040,"n":"צור ן, רפאל ממכנאס","b":"מו\"ץ במכנאס-שנות ה-תק'-תר'. הניח פס\"ד."},{"i":41041,"n":"צור ן, רפאל מפאס","f":"שלמה","bt":"תקץ","dt":"תרעז - טו כסלו","dp":"[פאס]","b":"רב בפאס. חיבר השגת ל\"בית עובד ויום מנוחה\". ירש ספריה גדולה מאביו והוסיף עליה, ספרייתו היתה אחת החשובות במרוקו, ואותה הוריש לבנו ר שלמה."},{"i":41042,"n":"צור ן, רפאל מפאס","f":"שלמה שמואל","k":"בעל זכרון לבני ישראל","bp":"פאס","dt":"תקפו - כט סיון","b":"אחיו של ר יעקב ן צור. רב בפאס. חיבר גם \"שמחת עולם\", שיטה למסכת סוכה, הכל בכת\"י. בנו - ר שלמה בעל זבחי רצון."},{"i":41043,"n":"צור ן, רפאל עובד ממרוקו","f":"יעקב - היעב\"ץ","bt":"תסו","bp":"פאס","dt":"תקכט - יט אייר","b":"רב ודיין בפאס בחיי אביו ומטעמו, (היחידי מבני היעב\"ץ שלא נפטר בחייו). העתיק מתקנות ופסקי החכמים הראשונים בפאס. בנו ר שלמה שמואל - נפטר תקכט ונספד ע\"י ר אליהו הצרפתי. נמנה בין חברי בית הדין של חמש בפאס (ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי, ר מתתיהו בן מנחם סירירו)."},{"i":41044,"n":"צור ן, שלום מסאלי","f":"משה","k":"בעל שיר חדש","dt":"תפז - לפני","b":"מחכמי סאלי מדקדק ומשורר, בן דודו של היעב\"ץ (ר יעקב ן צור). בנו - ר יהודה שנשרף עק\"ה במכנאס (ולפי טולדנו-נר המערב היה אחיו ולא בנו). חיבר גם \"שירים וקינות\" - נדפס בספר היעבץ \"עת לכל חפץ\", ועוד."},{"i":41045,"n":"צור ן, שלמה אליהו מפאס-מרוקו","f":"יעקב","k":"שאב\"ץ","bt":"תקפב","bp":"פאס","dt":"תרלג","dp":"פאס","b":"מחכמי פאס, נכדו של היעב\"ץ. חיבר הגהות והערות לספר דודו - \"פני שלמה\", ולספרים רבים וחתם שאב\"ץ, וחיבר שו\"ת ופסקי דינים."},{"i":41046,"n":"צור ן, שלמה מפאס","f":"רפאל","k":"בעל פני שלמה","bt":"תקסה","bp":"פאס","dt":"תרג - א תשרי","dp":"פאס?","b":"מחכמי פאס-מרוקו. תלמיד ר דניאל צולטאן. חיבר גם \"זבחי רצון\" שנדפס ב\"זבחים שלמים\" לר אברהם אנקווא, ור יוסף ן נאיים עשה לו קיצור בשם \"זובחי הזבח\". הו\"ל פיוטים מזקנו היעב\"ץ - \"עת לכל חפץ\" אלכסנדריה תרנג."},{"i":41047,"n":"צור ן, שלמה מצפת","b":"מחכמי צפת, בשנת שסד בשליחות לאלגיר עם יחיאל לוריא."},{"i":41048,"n":"צור ן, שם טוב מפאס","b":"מחכמי פאס, דודו של היעב\"ץ."},{"i":41049,"n":"צור ן, שמואל ממרוקו","f":"משה","b":"מחכמי מרוקו."},{"i":41050,"n":"צור ן, שמואל מספרד ואיטליה","b":"ממגורשי ספרד-רנב, עבר לאנקונה. מחכמי אנקונה-איטליה, בזמן הרא\"ם. נזכר בהקדמת פירוש ר שלמה עטיא לתהלים."},{"i":41051,"n":"צור ן, שמואל מפאס","f":"רפאל עובד","dt":"תקנב - כה אב","dp":"מכנאס","b":"תלמיד ר אליהו הכהן אלכלאץ. מו\"ץ בפאס עם ר אליהו הצרפתי, ור מתתיה סירירו. חתם על שטר-תקנב. בניו - ר רפאל, ר יעקב."},{"i":41052,"n":"צורוגין, אברהם","b":"מחכמי צפת, בשנת תקנג חתם על אגרת השליחות של ר משה בן יוסף מצליח, בשנת תקס על אגרת השליחות של רחמים יעקב בן ראובן ור חיים ברוך מאיסטרו, בשנת תקסד על אגרת ר משה אבוטבול, ובשנת תקע על אגרת ר אברהם בן חסון."},{"i":41053,"n":"צורוגין, אהרן","k":"בעל בית אהרן","b":"דרשן, חיבר \"בית אהרן\""},{"i":41054,"n":"צורוגין, יהושע מאיטליה"},{"i":41055,"n":"צורוגין, יצחק","b":"מחכמי טבריה וצפת, בשנים תקל-תקלז בשליחות טבריה בעירק, בשנת תקמג חתום על אגרת ראשי קהילת צפת."},{"i":41056,"n":"צורי ן, אברהם מצפת","b":"מחכמי צפת-תמח."},{"i":41057,"n":"צורי, חיים משלוניקי","dt":"תצא","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41058,"n":"צורי, יהושע דוד משלוניקי","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תס."},{"i":41059,"n":"צורי, יעקב מטבריה","b":"חתם על קבלה-תרפג מישיבת חכמי הספרדים בטבריה."},{"i":41060,"n":"צורי, משה מעכו","bt":"תריג","bp":"עכו","dt":"תרצו - כג ניסן","dp":"חיפה","b":"פעיל צבור בגליל."},{"i":41061,"n":"צוריא, אברהם","k":"בעל שמו משה","dt":"תריג","dp":"חברון","b":"נספד בספר \"שמו משה\" הנספח לספר \"וישב אברהם\", דרוש א"},{"i":41062,"n":"צוריא, דניאל מאזמיר","b":"גזבר \"חברת יתומות\" של קהלת פורטוגל באזמיר-שנות ה-ת'."},{"i":41063,"n":"צורייאנו, חיים דוד מאזמיר","f":"נסים רפאל יצחק","b":"רב באזמיר, חתם-תר ביוזיל היסאר עם ר שאול בכר עזרא."},{"i":41064,"n":"צורייאנו, נסים רפאל יצחק","dt":"תכג - כז אייר","dp":"אזמיר","b":"רב באיידין יוזיל חיסאר שליד אזמיר. בנו - ר חיים דוד מאזמיר.","bk":[["תאיר נרי","שו\"ת"]]},{"i":41065,"n":"צורמאני, אברהם מרודוס","b":"סוחר ברודוס-תקנא, העיד בענין עגונה במונאסטיר."},{"i":41066,"n":"צורמאני, מצליח מאיסטנקיואי","b":"חתן ר אברהם חביב מאיסטנקיואי. מחכמי איסטנקיואי(=איסטאנקיואי)-תק."},{"i":41067,"n":"צורמאני, מתתיה אברהם מבוקרשט","k":"מצ\"א חן","bp":"בולגריה?","dt":"תרסב","dp":"בוקרשט","b":"חתן ר מיכאל יעקב ישראל בעל שנות ימין, ועבר לרודוס, רב בשומלא-בולגריה. רב עדת הספרדים בבוקרשט-רומניה-תרל עד תרסב. פרסם מאמרים ב\"המאסף\"-ירושלים. גיסו של ר חיים יהודה ישראל בעל \"בן ימין\" המזכירו בספרו. תשובות ממנו בספרי חכמי דורו."},{"i":41068,"n":"צורנדורפר, שמואל מאנשבך","b":"רב באנשבך-תקיד ור שלום אולמן על מקומו אחריו-תקמד."},{"i":41069,"n":"צורף אפרים","bt":"1903","dt":"ה'תשנ 1990","bk":[["חיי הרב קוק",""]]},{"i":41070,"n":"צורף, אברהם שלמה זלמן מירושלים","f":"יעקב","bt":"תקפו","bp":"קיידאן","dt":"תריא - יט אלול","dp":"ירושלים","b":"עלה עם ר מנחם מנדל משקלוב לצפת ועסק בצורפות, עבר לירושלים. פעל רבות להצלת הישוב בירושלים ובא\"י, בשליחות קהלת ירושלים-תקעט בשליחות ובחזרתו-תקץ בערך הביא את כספי התרומות מוילנא. בשליחות נוספת-תקצט. עסק בשיקום חורבת ר יהודה החסיד. לאחר הרעש בצפת עמד בראש משלחת סיוע מירושלים. בשליחות אצל מוחמד עלי במצרים-תקצו בענין ה\"חורבה\" בירושלים. נהרג עק\"ה ע\"י ערבים. בנו - ר מרדכי (סלומון) מירושלים. מצאצאיו - משפחת סלומון מירושלים."},{"i":41071,"n":"צורף, אליהו מקראקא","dt":"תס","b":"מקובל,רב בקרקא"},{"i":41072,"n":"צורף, אפרים","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":41073,"n":"צורף, יהושע השל מקראקא","f":"יוסף מוילנא","k":"בעל שלשה עדרי צאן","dt":"תס-פ - כד אייר","dp":"קראקא","b":"מקובל מחכמי קראקא. נקרא צורף - שהיה יודע לצרף האותיות."},{"i":41074,"n":"צורף, יצחק","b":"מגדולי חכמי דורו-ש\"צ"},{"i":41075,"n":"צורף, יצחק מאנדרינופול","f":"מתיתיא מרדכי","b":"רב באנדרינופול, קושטא. תשובה ממנו ב\"שלום הבית\" - שהיה בכת\"י בידי החיד\"א."},{"i":41076,"n":"צורף, יצחק מוינה","f":"ישכר בער","k":"בעל מאזני צדק","b":"מגולי וינה. חיבר גם \"אבני צדק\" על משלי."},{"i":41077,"n":"צורף, ישראל מטריקולה","f":"דניאל","b":"רב בטריקולה-שנות ה-ש'."},{"i":41078,"n":"צורף, מרדכי מירושלים (סלומון)","f":"אברהם שלמה זלמן","dt":"תרכו - ט חשון","dp":"ירושלים","b":"חתן ר טוביה בן שלמה מטולצין. עסקן צבור, נסע ללונדון-תרה ופעל ליסוד בית חרושת לאריגה בירושלים, גבאי הקהלה האשכנזית בירושלים-תריד, פעל אז להקמת ביהמ\"ד \"שערי ציון\" יחד עם ר אריה ליב נאמן. בשליחות-תריח-תרכב להקמת \"החורבה\". בנו - ר יואל משה סלומון. נפטר עם אשתו במגפת הכולירה בירושלים-תרכו."},{"i":41079,"n":"צורף, משה מירושלים","f":"מנחם מנדל בן ברוך","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":41080,"n":"צורף, שמואל משלוניקי","b":"מחכמי קהלת קאטאלאן ישן בשלוניקי-שנות ה-ת'-תק'."},{"i":41081,"n":"צורף, שמואל סגל מפוזנא","b":"מגדולי חסידי פוזנא-ת\"ל"},{"i":41082,"n":"צורף-לדהירקש, מנחם","f":"שלמה","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":41083,"n":"צחון-צחין ן, אברהם","b":"מחכמי ספרד לפני הגירוש. בנו - ר יצחק."},{"i":41084,"n":"צחייך מגרבה","f":"יוסף","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":41085,"n":"צחן ן, שמואל מירושלים","b":"מקובל, מחכמי ירושלים-תכה (מקהלת המסתערבים). נזכר ב\"תורת הקנאות\" - שהיה אחד משלשה רבנים שגירשו את שבתי צבי כשהגיע לירושלים."},{"i":41086,"n":"ציבולניק, אברהם פרץ","f":"נחמיה","bt":"תריז","b":"תלמיד ישיבות מיר, וולוזין. רב בנובלע(=נאבלע)-פלך מינסק-תרמב, סערניק-פלך מינסק-תרסא. נסמך מאת: הנצי\"ב, ר אלעזר משה הורביץ מפינסק, ר רפאל שפירא מוולוזין."},{"i":41087,"n":"ציגלמן, אהרן ליב מוארשא","b":"מראשי בית החסידים דברסלב \"בית אמונה\" בגזשיבוב-וארשא, הו\"ל ספרי מוהר\"ן ועסק בהפצת חסידות ברסלב בפולין."},{"i":41088,"n":"ציגלר, יצחק משה","b":"בנו ר יצחק משה מביליץ הוציא לאור ספר זקנו \"פרי נאה\"."},{"i":41089,"n":"ציגלר, ליב חסיד מקלם","bt":"תקפד","bp":"וארפיאן-ליד קלם","dt":"תרנד - יז תמוז","dp":"ציטוביאן - קלם","b":"מחכמי קלם ונערץ ע\"י בני עירו גם הנכרים, עבר לציטוביאן. בהלוויתו השתתפו 12 רבנים ואלפי יהודים מהסביבה."},{"i":41090,"n":"ציגר, ברוך מפוטיק","b":"רב בפוטיק-תרנה"},{"i":41091,"n":"צידיקירו, אברהם מקושטא","b":"גביר מחכמי קושטא-תח, קיבל עליו נזירות שמשון ונשאל על נדרו מאת ר חיים בנבנישתי."},{"i":41092,"n":"ציוידאל, אביגדור מונציה","dt":"שסב - יח חשון","dp":"ונציה","b":"מחכמי האשכנזים שהתישבו בונציה. תלמיד מהר\"ר שי\"ק(=שמואל יהודה קצנלנבוגן המכונה ר יהודה מינצי השני). דיין בבית דינו של רבו בפדובה. חברם של ר בן ציון צרפתי ור ליב סראוואל. תשובה ממנו ב\"משבית מלחמות\" בענין המחלוקת על המקוה ברוויגו. נספד ב\"מדבר יהודה\" לר יהודה רויגו. אחיו - ר רפאל. מתלמידיו ר יעקב הלפרין בעל \"נחלת יעקב\""},{"i":41093,"n":"ציון בינג, זליגמן הלוי","b":"מגדולי חכמי אשכנז בדורו,רב באנדרנך,בינגן-ר\"ו,אופנהים-רכ\"ד."},{"i":41094,"n":"ציון בינג, זלמן הלוי","f":"זליגמן הלוי","k":"בעל אסור והיתר","b":"מגדולי חכמי אשכנז בבינגן"},{"i":41095,"n":"ציון הכהן","f":"אבאתו","k":"בעל יושיע ציון","bt":"תריח","bp":"ג'רבא","b":"תלמיד ר דוד כהן גישא בעל \"שירי דוד\", ור רחמים חורי השני. רב בג'רבא. חיבר \"יושיע ציון\" ג'רבא תשח."},{"i":41096,"n":"ציון הכהן מאלגיר","b":"רב בארץ ישראל ועבר לאלגיר וכיהן כרב ודיין בלמדייא(=מידיאה). מקום ציונו היה מקודש ונהגו לקיים זיירא על ציוני ביום לג בעומר."},{"i":41097,"n":"ציון הכהן מצפת","f":"יחזקאל הכהן","bt":"תריג","b":"מקובל מחכמי צפת-תרע."},{"i":41098,"n":"ציון, אשר הלוי","b":"מרביץ תורה בויניציאה-רע\"ח"},{"i":41099,"n":"ציון, דניאל מסופיה","b":"רב בבולגריה-תש בזמן השואה."},{"i":41100,"n":"ציוני, אברהם זליג מהורדוק","f":"דוד צבי מרעזיצע","bt":"תרעב","dt":"תשג","b":"תלמיד ישיבות סלובודקה, ראדין, טלז, וולוזין, ר שמעון שקופ בבריינסק, ור יוסף ליב משאדעווע. חתן ר ניסן ברוידא, רב בהורודוק-פלך גרודנא-תרסה על מקום חותנו. נסמך מאת: ר רפאל שפירא מוולוזין, ר שלמה הכהן מוילנא."},{"i":41101,"n":"ציוני, אהרן זליג מלוצין","f":"נפתלי מלוצין","dt":"תרלה","b":"רב בוארקלאן, לוצין על מקום אביו."},{"i":41102,"n":"ציוני, דוד אשר מלוצין - הזקן","dt":"תקסח - ב ניסן","b":"רב בלוצין-פלך ויטבסק ובנו ר נפתלי על מקומו אחריו."},{"i":41103,"n":"ציוני, דוד צבי מרעזיצע - הנכד","f":"יצחק - עולת יצחק","b":"חתן ר משה פלצינסקי מוישקעס. רב בלוגאו, רעזיצה-פלך ויטבסק על מקום אביו."},{"i":41104,"n":"ציוני, יצחק מרעזיצא","f":"נפתלי מלוצין","k":"בעל עולת יצחק","bt":"תקף","b":"רב בקריסלובא, רעזיצא-פלך ויטבסק-תרל ובנו ר דוד צבי על מקומו אחריו. חתניו - ר בן ציון דון יחיא, ר גרשון בן יוסף רבינזון מקליבלנד-ארה\"ב."},{"i":41105,"n":"ציוני, ישראל מניו יורק","b":"חתן ר אליעזר דון יחיא מלוצין בעל \"אבן שתיה\". עורך עתון אורטודוכסי בניו יורק."},{"i":41106,"n":"ציוני, מנחם משפיירא","b":"מקובל,מגדולי חכמי דורו בשפירא-שנת ר'. חיבר ביאור על התורה ונדפס."},{"i":41107,"n":"ציוני, מנחם מתל אביב","f":"ניסן בן ציון","b":"רב בתל אביב-תש. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":41108,"n":"ציוני, משה","f":"ניסן","dt":"תשכג - טו תשרי","b":"סידר ש\"ס מפוסק"},{"i":41109,"n":"ציוני, נפתלי מלוצין","f":"דוד אשר מלוצין","dt":"תרטז - ג אייר","b":"תלמיד ר גרשון משקלוב, ר נתן ור שמואל מקריסלובא. רב בלוצין-תקסה על מקום אביו כ-50 שנה. בניו - ר זליג בעל שו\"ת ציוני על מקומו אחריו, ר יצחק מקריסלובא בעל \"עולת יצחק\". חתנו - ר חיים דוד זליגמן מגריווא."},{"i":41110,"n":"ציזלינג, צבי מנחם","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":41111,"n":"ציזלר, הרצל מגלינא","bt":"תרסח","bp":"גלינא","dt":"תשב","b":"מזכיר צא\"י. פרסם בכמה עתונים על חיי היהדות. נספה בשואה."},{"i":41112,"n":"ציזנר, שמלקא מקשאנוב","f":"יעקב מקשאנוב","bt":"תרסה","b":"תלמיד בישיבת בובוב. תשובה אליו ב\"פרי השדה\" תרסח."},{"i":41113,"n":"ציטמור, ישראל אשר מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":41114,"n":"ציטרון, אברהם אליעזר מדאראג","f":"זאב וולף מדאראג","b":"בן האדמור מדאראג. רב בדאראג על מקום אביו, פעסט, וינה, ברזיל."},{"i":41115,"n":"ציטרון, זאב וולף מהאידו-דאראג","f":"אברהם אליעזר מערדא","k":"אדמור מדאראג","bt":"תריז","bp":"כפר אדאמוש","dt":"תרפז - טו ניסן","b":"תלמיד ר מנחם מנדל פאנט בדעש, ור אברהם יצחק וינברגר בקלינורדין. חתן ר שמואל פרנקל מדאראג, רב ואדמור בדאראג-תרמג על מקום חותנו כ-44 שנה וראש ישיבה שם ובנו ר אברהם אליעזר על מקומו אחריו. חיבר אגדות מהרז\"צ על התורה-מישקולץ תרצז, \"זבד טוב\". בניו: ר יהושע מביסרמין, ר יחזקאל שרגא, ר אברהם אליעזר מדאראג. חתניו: ר מרדכי צבי שורץ מקליבלנד, ר צבי הירש פרידמן מניו יורק, ר אריה ליב פריד מבודפשט."},{"i":41116,"n":"ציטרון, יהושע מביסרמין","f":"זאב וולף מדאראג","b":"בן האדמור מדאראג. רב בביסרמין. שאפרן, פעסט."},{"i":41117,"n":"ציטרון, יחזקאל שרגא מדאראג ענט","f":"זאב וולף מדאראג","dt":"תשד","b":"חתן ר משה פרנקל מהאידו דאראג. רב בהאידו-דאראג לצד אביו. רבה הראשון של ענטש(=אנץ')-תרצב - לאחר שהפכה לקהלה עצמאית - על מקום הדיין ר ישראל ברוין. נספה בשואה."},{"i":41118,"n":"ציטרון, ישראל אבא מפתח תקוה","f":"גרשון","k":"בעל חדושי מוהריא ציט","r":"חתנו של הרוג'טושבי","bt":"תרמא","bp":"קריזברג או דוינסק","dt":"תרפז","dp":"תל אביב","b":"מחכמי ליטא, תלמיד ישיבות טלז וולוזין, חתן ר יוסף רוזין מדוינסק (הרוגצ'ובר). רבה הראשון של פתח תקוה-תרעא - וניהל את ספר האחוזה ע\"פ דין תורה. חיבר \"ספר חידושי מוהריא ציטרון\" תל אביב תרץ. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט. לזכרו נספד \"גיא חזיון\" פתח תקוה תרפט. (שינה שמו מקטרוני לציטרון).","bk":[["חידושי מהרי\"א ציטרון",""]]},{"i":41119,"n":"ציטרון, מנחם מנדל מוילקי","b":"רב בוילקי. אחיו - ר שמעון ציטרון מטלז, ר יצחק רייצר מקרוקי."},{"i":41120,"n":"ציטרון, צבי דב מיזלוביץ","b":"מחכמי יזלוביץ. הו\"ל כתב העת \"ועד חכמים\" קולומיאה תרנח - תרסד, בערים יזלוביץ, מונקטש, פרמישלא, דרוהוביץ, סיגט, לבוב, הוסיאטין, בוצאץ."},{"i":41121,"n":"ציטרון, שמואל ליב מנובוזיבקוב","k":"בעל יונה פותה","bt":"תרכב","bp":"מינסק","b":"תלמיד ישיבת וולוזין. מורה לעברית ברוסיה וגרמניה, התישב בנובוזיבקוב-פלך טשרנינוב. פרסם מאמרים ב\"המליץ\", \"השחר\", \"כנסת ישראל\", ועוד. חיבר \"אם אין אני לי\", אסיפת ספורים\", ועוד."},{"i":41122,"n":"ציטרון, שמעון מטלז","b":"רב בטלז. אחיו - ר מנחם מנדל ציטרון מוילקי, ר יצחק רייצר מקרוקי."},{"i":41123,"n":"ציטרוננבוים, דוד","f":"זישא מזמיגרוד","k":"בעל זר זהב","b":"חתן ר חיים הערבאך מגריבוב. חיבר \"זר זהב\" בילגוריא תרצג. ?? לא באוצר ??"},{"i":41124,"n":"ציטרוננבוים, שמריה מארה\"ב","f":"צבי מקראסנא","k":"עורך כרם שלמה","bt":"תשט","b":"חסיד בובוב בניו יורק. חתן ר יהושע זאב זאפערן מקראסנא. עורך הקובץ \"כרם שלמה\" של חסידי בובוב - ניו יורק."},{"i":41125,"n":"צייאח ן, אברהם מדמשק","f":"יוסף מדמשק","b":"סופר קהלת דמשק-שכט."},{"i":41126,"n":"צייאח ן, יוסף מירושלים","f":"אברהם","k":"בעל אבן השהם - בכת\"י","bp":"ירושלים","b":"מחכמי ירושלים, חתם על הסכמה בענין המס-שכו, רב קהלת המסתערבים בדמשק, ירושלים-שח על מקום ר שלמה סיריליו, חלב, חמת, טוקאת, רב קהלת המסתערבים בדמשק, חזר לירושלים-רצז."},{"i":41127,"n":"צייארי, אברהם מאלגיר","f":"משה בן מרדכי","dt":"תעד","b":"מגדולי המשוררים באלגיר - מושפע מהמשורר ע' הצפרוני, ונזכר אצל ר יצחק מרעלי במבוא למחזור \"מדבר ים\". כמה מפיוטיו נכנסו לקרוב\"ץ ולמחזור אלגיר. נזכר גם אצל ר יצחק בלוך בספרו. ר יצחק מרעלי הכין לדפוס את הדיוואן שלו אך טרם נדפס. הניח כתבים בשירים ופיוטים. יסד ביכ\"נ ועל כל קירותיו שירים שחיבר. נפטר ללא ילדים."},{"i":41128,"n":"צייארי, דוד מאלגיר","bt":"שץ","dt":"תס - בערך","b":"נגיד הקהל מחכמי אלגיר."},{"i":41129,"n":"צייארי, יעקב מאלגיר","b":"ראשון מבני המשפחה הידוע באלגיר. נזכר בשו\"ת הרשב\"ש."},{"i":41130,"n":"צייארי, משה מאלגיר","f":"מרדכי","dt":"תלט","b":"פייטן ומשורר מחכמי אלגיר. מפיוטיו ב\"אוצר טוב\" ברלין תרם. בנו ר אברהם המשורר מאלגיר."},{"i":41131,"n":"צייארי, סעדיה מאלגיר","f":"אברהם","bt":"רך - בערך","dp":"ש - בערך","b":"רב באלגיר, וביקש לילך לפאס ללמוד תורה (כנראה בנדר) ולא עלה בידו וביקש מר שמעון בן הרשב\"ש עצה להתרת נדרו."},{"i":41132,"n":"צייארי, שלמה מאלגיר","b":"רב בלמדייא(=מידיאה) ומלמד תשב\"ר, הרשב\"ש השיב לו בשו\"ת הרשב\"ש."},{"i":41133,"n":"צייג, עזרא מחלב","k":"בעל פרי עץ הדר","b":"רב בחלב.חתנו ר משה סוויד בעל \"מסוא משה\" שהספידו בספרו."},{"i":41134,"n":"צייח (צייאה), יוסף","f":"אברהם","bp":"ירושלים","dt":"שלא - אחרי","b":"נדד בארצות שונות ותקופה מסוימת שימש כרב בדמשק, בשנת רצה חזר לירושלים ושימש כרב ראשי לאחר ר שלמה סיריליאו. ענה לשאלות מכל הארצות, וניהל חליפת מכתבים עם ר יוסף קארו הרדבז והמביט. חיבר גם ספרים בקבלה בכתב יד."},{"i":41135,"n":"צייטלין, אברהם זאב מטשקנט","b":"חסיד חב\"ד, רב בארענבורג(=טשקנט). מחותן עם ר שמואל זנויל קרטופל בעל \"בית שמואל\"."},{"i":41136,"n":"צייטלין, דב בר הכהן מפאריס","f":"זאב וולף או יוסף","k":"בעל יד הקטנה","bt":"תרא","bp":"וילנא","b":"תלמיד ר מאיר מיכל מוילנא. דרשן, מו\"ץ באנטאקליא על מקום ר ליב בן גרשון. בר פלוגתא של ר בצלאל הכהן מוילנא. היה מחלוקת כנגדו בגלל קנאותו ונאלץ לעזוב את רוסיה, רב ביהמ\"ד בלונדון, רב בפאריס-תרנב. חיבר גם \"מסלת הדעת\", הו\"ל כתב עת \"הירח\" ובו יצא בקנאות נגד משכילי הדור והיה מחלוקת כנגדו על כך (ונאלץ לעזוב)."},{"i":41137,"n":"צייטלין, דוד מצפת","f":"יחיאל","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":41138,"n":"צייטלין, יהושע משקלוב","f":"צבי הירש","k":"השר מאושיצה-עמודי גו","bt":"תקב","dt":"תקפב - א אלול","dp":"חרסון","b":"תלמיד בעל שאגת אריה. גביר עשיר ומקורב למלכות מחכמי שקלוב. השיב לשאלות חכמי דורו, הושיב תלמידי חכמים אצלו לחבר את ספריהם ובהם: ר נחום בעל \"תוספות בכורים\", ר מנדל לפין בעל \"חשבון הנפש\", ר ברוך משקלוב, ר בנימין זלמן ריבעלעס. חיבר הגהות לסמ\"ק בשם \"עמודי גולה\" - קפוסט תקף."},{"i":41139,"n":"צייטלין, יוסף מביליניץ","f":"אלכסנדר סנדר","b":"רב בבילינץ(=בליניטש)-תפ. בנו - ר צבי הירש. אחיו - ר יהודה יודל מקלצק וסלוצק, ר אריה ליב מנישעויז וסלוצק."},{"i":41140,"n":"צייטלין, מאשקע רמב\"ם","dt":"תרי - ט אייר","b":"תלמיד ר חיים מוולוזין (אחד מה-4 שזרק בהם מרה)."},{"i":41141,"n":"צייטלין, משה מפולין - ב","b":"מראשי אגודת ישראל בפולין, חתם עם מהר\"ם שפירא מלובלין."},{"i":41142,"n":"צייטלין, משה מצפת","f":"יצחק","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":41143,"n":"צייטלין, משה מראסיין","f":"יעקב משקלוב","bt":"תקעב","bp":"שקלוב","dt":"תריז - ט חשון","dp":"גורז'ד(=גארזד)","b":"נכד ר יהושע צייטלין השר מאושיצה. חתנו ותלמידו של ר חיים צבי הירש ברוידא (למד עם ר אלכסנדר משה לפידות - שלימים כיהן גם הוא כרב בראסיין). בקי בתכונה והנדסה רב בשקלוב-תר, ראסיין-תרד עד תרטז על מקום ר דב בר רבינוביץ ור אברהם שמואל רבינוביץ על מקומו אחריו, ועבר בגלל מחלוקת לפלונגיאן. (באוצר הרבנים מופיע כבנו של ר יהושע - במקום נכדו)."},{"i":41144,"n":"צייטלין, צבי הירש","f":"יוסף מביליניץ","b":"רב-שנת תק\"כ"},{"i":41145,"n":"צייטלין, צבי הירש משקלוב","f":"משה בן יהודה","b":"רב בשקלוב. חתנו - ר נחמן סירקין."},{"i":41146,"n":"צייטלין, שניאור זלמן מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":41147,"n":"צייטליש, אליעזר","f":"צבי הירש צייטלש"},{"i":41148,"n":"צייטליש, מרדכי","f":"אליעזר","b":"חתן ר צבי הירש צייטליש, וגיסו של ר יהושע צייטליש בעל ביאור על הסמ\"ק."},{"i":41149,"n":"ציילברגר, בנימין מניו יורק","k":"בעל תורת חסד","b":"ר\"מ בישיבת \"בית התלמוד\" בניו יורק. פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":41150,"n":"ציימן, יוסף יוזפא מפבלובקה","f":"אברהם משה","k":"בעל אלומות יוסף","bt":"תרכג","b":"רב בסבלובקה(=פאוואלאווקא)-פלך חרסון-תרמה. חיבר חיבור בהלכה ואגדה בשם \"אלומות יוסף\"."},{"i":41151,"n":"ציימן, מתתיהו מניישטאט","k":"בעל אמרי נועם","b":"רב בניישטאט-נוברדוק, סירקוז-ניו יורק. חיבר גם \"אמרי נועם\" תרעז."},{"i":41152,"n":"ציימן, צבי הירש מואלחוב","f":"יוסף יוזפא","bt":"תרם","b":"רב ושו\"ב ביליזלוועטפאלי-תרסב, באקו-קווקז-תרסב, וואלחאב-פלך נאווגאראד-תרסג."},{"i":41153,"n":"צייס, עזריאל מרדכי מארה\"ב","f":"יעקב","bt":"1874","bp":"אליטא-ליטא","dt":"1939","dp":"מנצסטר-ארה\"ב","b":"תלמיד ישיבת מייליס בוילנא. היגר למנצסטר-ארה\"ב והתעשר. תרם לקרן מיוחדת לתמיכה בחניכי גימנסיות בליטא ובהמשך השכלתם, תרם לגימנסיה הריאלית העברית בקובנא. הקים \"בתי צייס\" במנצסטר לשיכון משפחות פועלים. פעיל בתנועה הציונית ובועד היהודי אמריקאי."},{"i":41154,"n":"צייסל, הרמן מוינה","bp":"פירצינהובן-מעהרן","dt":"תקעז","b":"רופא בוינה. חיבר ספרים ומאמרים בנושא רפואה."},{"i":41155,"n":"צילך, אברהם מלאסק","f":"מאיר מלאסק","k":"בעל בית יעקב","dt":"תרן","b":"חתן ר ליבוש ר טעבליעלס מפיעטרקוב, ובזיוו\"ש חתן ר מיכאל פאצאנובסקי מגלובנה. בנו - ר שמעון מלודז."},{"i":41156,"n":"צילך, אריה ליב מלאסק","f":"מאיר מלאסק","b":"מחכמי לאסק. חתנו - ר ליב הכהן מוידובה, וחתן נכדתו היה ר אפרים בן יחזקאל מקוזמיר."},{"i":41157,"n":"צילך, ברוך בנדיט","f":"שמואל מפובזניק"},{"i":41158,"n":"צילך, מאיר מלאסק","bt":"תקי","dt":"תקפו - יא אד\"ב","dp":"לאסק","b":"חתן ר אריה ליב-בן ר שמואל לסקר מלוסק. מחכמי ליסא, אב\"ד לאסק(=לוסק)-תקמ כ-46 שנה על מקום ר צבי בן פנחס זליג, ור זאב וולף הכהן על מקומו אחריו. חברו של ר עקיבא איגר. בניו: ר שמואל מפובונזיק-ליד וארשא, ר אריה ליב מלאסק, ר יחיאל מיכל, ר אברהם, וחתנו - ר וולף ליפמן ונכדו - ר שמשון מקאליש. נספד מאת ר אריה ליב צינץ מפלוצק בספרו \"טיב חליצה\". הניח חדושים בכת\"י. בנו - ר שמואל מפובזניק חיבר לזכרו \"נחלת שבעה\"."},{"i":41159,"n":"צילך, שמואל מפובוזניק","f":"מאיר מלאסק","k":"בעל נחלת שבעה","dt":"תרי - טו תשרי","b":"רב בפובוזניק. חיבר \"נחלת שבעה\" לזכר אביו - ברסלוי תקפז."},{"i":41160,"n":"צילץ, אליעזר","b":"רב בפוזנא-תק\"ע"},{"i":41161,"n":"צילץ, חיים ליבש מפיסלינג","f":"משה ליב צילץ","b":"רב בפיסלינג-תק\"צ"},{"i":41162,"n":"צילץ, משה ליב מנייטרא - הנכד","f":"שמואל מיאקא","dt":"תרלז - כא תמוז","dp":"נייטרא","b":"תלמיד הכת\"ס. חתן ר נפלתי הרץ ארנפלד מנייטרא. רב בקאמארן, נייטרא."},{"i":41163,"n":"צילץ, משה ליב מניקלשבורג הסבא","f":"יוסף","bp":"צילץ","dt":"תקצא","b":"תלמיד ר מרדכי בנט בניקלשבורג. דיין בניקלשבורג-תקנח, ואח\"כ ראב\"ד. זקנו של ר משה ליב צילץ מנייטרא."},{"i":41164,"n":"צילץ, ראובן מברלין","f":"ר\"מ","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":41165,"n":"צילץ, שמואל כץ מניקלשבורג","f":"משה ליב מניקלשבורג","dt":"תריט","b":"רב ביאקע, ראב\"ד בניקלשבורג-תקצא. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד (נדפסו מכתב ידו)."},{"i":41166,"n":"צילציל, משה מבודה","f":"חיים","b":"רב בבודין(=בודה)-שנות ה-ש'."},{"i":41167,"n":"צילצר, צבי הירש מאלטונא","f":"יוסף מסעלץ","dt":"תקפח","dp":"אלטונא","b":"מחכמי אלטונא."},{"i":41168,"n":"צימבליסט, יהושע מהורדנא","f":"משה אהרן","bt":"תרכה","bp":"הורדנא","dt":"תשז - ז תשרי","dp":"ירושלים","b":"מו\"צ במינסק,ומראשי הקהלה, ראש ישיבת \"שואבי המים\" במינסק גם בתקופת הקומוניסטים. עלה לירושלים-תרצד, וכיהן כנשיא התאחדות הרבנים פליטי רוסיה. לזכרו ספר זכרון-ירושלים תשט."},{"i":41169,"n":"צימבליסט, שלמה מירושלים","f":"יהושע","b":"ראש ישיבת תפארת צבי, ובעל תפלה בישיבת חברון בירושלים."},{"i":41170,"n":"צימבליסט-הורדנר","dt":"תשטז - ג כסלו","b":"מרביץ תורה,ראש ישיבת תפארת צבי בבני ברק"},{"i":41171,"n":"צימט, יעקב ליב מויליצקה","b":"מחכמי ויליצקה - ממשתתפי \"אהל מועד\"."},{"i":41172,"n":"צימטבוים, אהרן","f":"פנחס סגל מגרוסורדין","bt":"תרנח","dt":"תשמג","b":"רב בגרוסורדין אצל אביו, קרעניץ. ניצל מהשואה - והציל יהודים רבים. עבר לארה\"ב-תשה ונקרא שם הרב מגרוסורדין וקרניץ. פעיל בארגוני עזרה וחסד. הו\"ל ספר אביו \"דברי פנחס\"."},{"i":41173,"n":"צימטבוים, דוד מקרניץ ובורשה","f":"פנחס סגל מקרניץ","k":"בעל חסדי דוד-תרצח","bt":"תרנ-ד","bp":"קרניץ","dt":"תשג","b":"התכתב עם גדולי דורו בהיותו בן 12! בגיל 17 סירב לרבנות סרנטש. חתן הגביר ר אלעזר שטינמץ מבורשא. רב בבורשא, רבה האחרון של קרניץ(=קריניצה)-תרפב על מקום זקנו - ר אריה ליב ברוינפלד. נספה בשואה. חיבר \"חסדי דוד\" בילגוריא תרצח. ?? לא באוצר ??"},{"i":41174,"n":"צימטבוים, מנדל","bt":"תקסו","bp":"טורנא","b":"עלה לארץ-תריא. סגן מנהל כולל אוסטריה."},{"i":41175,"n":"צימטבוים, משה הלוי מצאנז","k":"בעל אבן משה","b":"מחכמי צאנז-תרפז, ועבר לבייטש. חיבר \"אבן משה\". פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח. ?? לא באוצר ??"},{"i":41176,"n":"צימטבוים, פנחס מגרוסורדין","f":"ישכר דב סגל מטורנא","k":"בעל דברי פנחס-תרעב","bt":"תרכה או תרלא","bp":"טורנא או רופשיץ","dt":"תשד - ח סיון","dp":"אושוויץ","b":"תלמיד ר יצחק שמלקיס בעל \"בית יצחק\". חתן ר אריה ליב ברוינפלד מקרעניץ, ועבר לשם. דיין בגרוסורדין-תרנד על מקום ר ישראל משה קליין, וראב\"ד-תרסא כיובל שנה. נספה בשואה. חיבר \"דברי פנחס\" והחל להדפיסו בוויצען תרעב, ובנו ר אהרן מנ\"י הוציאו לאור בנ\"י תשכג. נספה בשואה. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישובה תרפח, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"לקט ששנ\"ה\" - סטמר תרצד. ?? לא באוצר ??"},{"i":41177,"n":"צימטבוים, רפאל הלוי סגל","k":"בעל דרכי חיים","bp":"צאנז","b":"גדל אצל הדברי חיים, והיה משמש בקודש אצלו. עבר לקראקא. אמר בדחנות בכל חתונות נכדי הדברי חיים. חיבר \"דרכי חיים\" קראקא תרפג."},{"i":41178,"n":"צימטבוים, רפאל מגורליץ","f":"משה מרדכי סגל","k":"בעל אור לפארו","bt":"תרי","bp":"בריגל","dt":"תרף","b":"רב ומלמד בגורליץ, ר\"מ בטרנוב. חיבר \"אור לפארו\" מונקטש תרנב."},{"i":41179,"n":"צימקובסקי, מיכאל","bt":"1861","bp":"שאוולי","dt":"1928","dp":"קובנא","b":"עו\"ד בשאוולי. ממקימי הגוש היהודי ליטאי בדומא. יו\"ר האגודה הספרותית היהודית. מורשה מטעם ליטא במוסקבה להחזרת פליטים."},{"i":41180,"n":"צימר, ברוך מיגולניצה","b":"רב ביגולניצה-תרסט."},{"i":41181,"n":"צימר, יוסף מראפע","b":"מחכמי ראפע (ליד צאנז) - ידידו של הדב\"ח. חתנו - ר יצחק איזיק הלוי שנדורף מצאנז."},{"i":41182,"n":"צימר, שלום","f":"משה יהושע","b":"משמש בקודש אצל הדברי חיים."},{"i":41183,"n":"צימרמן, אברהם יצחק הלוי מהלוסק","b":"חתן ר יעקב משה דירקטור ממוש. רב בהאלוסק וחתנו ר ברוך דב בער ליבוביץ על מקומו אחריו, קרמנצוג-תר\"נ."},{"i":41184,"n":"צימרמן, אהרן חיים מניו יורק","k":"בעל בנין הלכה","b":"רב בניו יורק. חיבר \"בנין הלכה\" נ\"י תשב. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":41185,"n":"צימרמן, י' ה' מלונדון","b":"פרסם מאמרים ב\"המסילה\" - לונדון תשז."},{"i":41186,"n":"צימרמן, מאיר הלוי","f":"אברהם יצחק צימרמן","bt":"תרלז","dt":"תרצו - יח חשון","b":"רב בלונדון-תרעג. פרסם מאמרים ב\"אור תורה\" - לונדון תרצד."},{"i":41187,"n":"צימרמן, משה נחמן מקלוש","dt":"תרלז","b":"תלמיד ר חי\"ל סוסניצר."},{"i":41188,"n":"צימרמן, שמחה אשר מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":41189,"n":"צינאבל, יהודה ליב שלום מקופישו","b":"רב בקופישוק-ליטא."},{"i":41190,"n":"צינגר יצחק בן נחמן צבי","bt":"1840","dt":"ה'תרע 1910","bk":[["פעולת הצדיקים",""],["שבע רצון",""]]},{"i":41191,"n":"צינגר, יצחק מראוה רוסקה","f":"נחמן צבי הירש","k":"בעל כרם ביבנה","b":"הוציא לאור ספרונים פופולרים והוסיף להם מהערותיו. חיבר \"כרם ביבנה\", \"זכרון צדיקים\" פאדגורזע תרנז. שותף-תרסג לר אליעזר רפפורט ברז\"ו שהיה אב\"ד פיאטרא (והדפיסו בפודגורזע)."},{"i":41192,"n":"צינגר, משה מקשנוב","f":"מנדל","bt":"תרף","b":"חסיד בובוב ותלמיד ישיבת בובוב בקשנוב. נספה בשואה. דברי תורה ותולדותיו - כר\"ש תשמג."},{"i":41193,"n":"צינדלר-צידיר, איזיק מנוסטרישץ","b":"רב בנוסטרישץ-תרמט."},{"i":41194,"n":"צינוביץ, יוסף אברהם מלומזה ואו","f":"חיים צבי","bt":"תריח","b":"דומ\"צ באוסטרובה(=אסטראווא)-פלך לומזה-תרמז, לומזה-תרסח. פרסם מאמרים ב\"דבר בעתו\" - וארשא תרצט."},{"i":41195,"n":"צינוביץ, משה","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":41196,"n":"צינוירט, אברהם אביש וישניצה","f":"יצחק קלויזנר מהלישוי","bt":"תקמב","dt":"תרלו","b":"בחר בשם צינוירט על שם צעהן ווארט (עשרת הדברות). חסיד החוזה מלובלין. רב בוישניצה ומיסד השטיבל החסידי הראשון שם. (והיה במחלוקת עם האב\"ד - אריה דבי עילאי). חי כ-100 שנה. בנו ר יצחק על מקומו אחריו (והיה במחלוקת עם האב\"ד ר שלמה מבובוב). חתן נכדת ר שמעון מירוסלב. מצאצאיו ר יוסף שעלה לירושלים וממנו משפחה גדולה בארץ, ואדמורי ללוב-קרלין."},{"i":41197,"n":"צינוירט, יצחק מוישניצא","f":"אברהם אביש מוישניצא","b":"רב בוישניצא על מקום אביו (והיה במחלוקת עם האב\"ד ר שלמה מבובוב). חתן נכדת ר שמעון מירוסלב. מצאצאיו ר יוסף שעלה לירושלים וממנו משפחה גדולה בארץ, ואדמורי ללוב-קרלין."},{"i":41198,"n":"צינוירט, משה יהושע השל מוישניץ","f":"יעקב","bp":"וישניצה","b":"חתן ר אליעזר טיפנברון מקראקא. עבר ללונדון ולארה\"ב. עלה לארץ-תשכז."},{"i":41199,"n":"צינוירט, משה נתן נטע מירושלים","f":"יהושע","r":"אב\"ד לידא מגנצא ואמשטרדם,","bt":"תרפז","bp":"ירושלים","dt":"תשמב","b":"לימד בישיבת תולדות אהרן וראש כולל סקווירא בירושלים. חסיד בויאן מקורב לאדמורי רוזין, וגור. חתן ר דוד זליג זלצמן מקוברין."},{"i":41200,"n":"צינוירט, צבי יעקב מירושלים","f":"יהושע","bt":"תרצב","bp":"ירושלים","dt":"תשמב","b":"מקורב לאדמור מקרלין. ר\"מ בישיבת קרלין. בהנהלת כולל גליציה על מקום אביו."},{"i":41201,"n":"צינמאן, חיים מאיר מקושיץ","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":41202,"n":"צינמאן, יוסף יוזל מפאוולובקא","b":"רב בפאוולובקה-ליד אודסה. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"שמעתתי דרבנן\" - אודסה תרמז."},{"i":41203,"n":"צינמאן, יחיאל מפוקשוינצא","b":"תלמיד ר ישכר דב מראדושיץ."},{"i":41204,"n":"צינס, צבי הירש","f":"אליהו","b":"רב בפלונגאן"},{"i":41205,"n":"צינסטרו, אברהם שאול מירושלים","dt":"תקיו - כג טבת","b":"מחכמי ירושלים."},{"i":41206,"n":"ציסארסקיא, חיים","b":"פרסם מאמרים ב\"בית המדרש\" - קראקא תרמח."},{"i":41207,"n":"ציף, יצחק מטלומטש ולבוב","bt":"תרלא","bp":"למברג","dt":"תרצה","b":"חתן ר אורי שרגא פיבל טויבש מיאס בעל \"אורי וישעי\", תלמיד מהרי\"א איטינגא. רב בטלומטש(=טלינטש)-תרנח, למברג-תרף."},{"i":41208,"n":"ציפורש, משה מלבוב","f":"יעקב ישראל","k":"בעל סדר גיטין","dt":"שסא - יג אלול","dp":"לבוב","b":"מחכמי לבוב, חתם בועד ארבע ארצות-שנו, נזכר ב\"שארית יוסף\"."},{"i":41209,"n":"ציפסר, מאיר משטוהל-ויסנבורג","k":"בעל מי השלח","bt":"תקעה","bp":"יארמוט","dt":"תרל - ו טבת","dp":"רוחניץ","b":"תלמיד ר נחום טרוויש בעל \"שלום ירושלים\". רב ברכניץ על מקום ר גבריאל אנגלסמן, שטוהל-ויסנבורג(=סעקעש-פעהערוואר)-הונגריה. חיבר קונטרס \"מי השלח\" - אופן 1853 - בענין הכשרת גט, וכנגדו יצא ר גוטליב פישר בספר \"דלתים ובריח\" - וינה תרטו. על כך אצל י' כץ - \"הקרע שלא נתאחה\" ירושלים תשנה."},{"i":41210,"n":"ציפקביץ, דוד","dt":"תשד","b":"רב במיאדזאל"},{"i":41211,"n":"ציפקביץ, שמחה אליהו מארה\"ב","f":"מאיר","bt":"תרלו","bp":"נובוגראד","dt":"תשח - טו שבט","dp":"ניו יורק","b":"תלמיד ישיבת לומזה, כולל קובנא, וילנא, גרודנא, וולוזין. נסמך מאת: ר רפאל שפירא, ר משה בצלאל לוריא מסובאלק. היגר לארה\"ב-תרעד וכיהן כרב בקהלת \"נצח ישראל\" בברונקס. בנו - אביגדור, חתנו - ר שמאון מורדכוביץ."},{"i":41212,"n":"ציפקוביץ, ראובן","dt":"תשג","b":"רב בדווארנאווא"},{"i":41213,"n":"ציפקין, ישראל שלמה מארה\"ב","k":"בעל 25 שנות חינוך יה","bt":"1891","bp":"וילנא","dt":"1955","dp":"ניו יורק","b":"תלמיד הסמינר התיאולוגי בניו יורק. מנהל ביה\"ס של לשכת החינוך היהודית בניו יורק. מנהל \"ג'ואיש אדוקיישן אסוס\". מנהל בתי הספר הדתיים בניו יורק, ועוד. פרסם מאמרים וספרים בעניני חינוך בעברית ואנגלית."},{"i":41214,"n":"ציפקעס, חיים מוילנא","b":"רב בוילנא בזמן ר שאול קצנלנבוגן. נזכר ב\"נשמת אדם\"."},{"i":41215,"n":"ציפר, יחיאל מיכל","f":"אברהם מאיר","k":"בעל דרך חיים","bt":"תקעה","dt":"תרט - כא אדר","b":"רב בציפר. חיבר גם \"חיי עולם\","},{"i":41216,"n":"ציפרשטין, אביגדור","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":41217,"n":"ציצביץ, א'","b":"פרסם מאמרים ב\"המאור\" - ברלין תרצג."},{"i":41218,"n":"ציצוביץ, אביעזר מברלין","b":"פרסם מאמרים ב\"המאור\" - תל אביב תרצה."},{"i":41219,"n":"ציציליא, משה ממצרים","b":"מו\"צ ברשיד-מצרים-תיג, בזמן ר דוד גרשון."},{"i":41220,"n":"צירינו, מרדכי מאזמיר","dt":"תקיב - יב אייר","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":41221,"n":"צירלסון, יהודה ליב מקישנוב","f":"משה חיים","k":"בעל עצי לבנון","bt":"תרך","dt":"תשא - תמוז","b":"פוסק, מנהיג, מקורב למלכות, וציר בבית הנבחרים בבסרביא, נבחר לראש אסיפת הרבנים בפטרבורג-תרסט. רב בפרילוקי(=פרילוקא)-פלך פולטובה-תרלח, קישינב(=קעשנוב)-תרסח, הסכים לעבור לראדום אך חזר בו (על כך תגובות הלכתיות ב\"שערי תורה\" - וארשא תרסג-תרצט מאת ר מאיר ישראל אידנשטין מקישינוב וכנגדו מר מנחם מנדל וינגורט מראדום). פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אוצר החיים\" - דעווא תרפה, \"אחאיסף\" - סטריזוב תרפט, \"בית ועד לחכמים\" - לונדון תרסב, \"בית ועד לחכמים\" - סטמר תרפב, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"המאסף\" - ירושלים תרנו, \"המגיד\" - סטמר תרפח, \"שערי ציון\" - ירושלים תרפא, \"תורה מציון\" - ירושלים תרנה-תרסה, \"תל תלפיות\" - וייצען תרנב-תרעד.","bk":[["עצי הלבנון [שו\"ת]",""],["גבול יהודה",""],["דרך סלולה",""],["לב יהודה",""],["מערכי לב",""],["עצי הלבנון",""],["גבול יהודה - שו\"ת",""],["דרך סלולה - מאמרים ושירים",""],["הגיון לב - ענייני הטפה",""],["לב יהודה - שו\"ת והטפה",""],["מערכי לב - תשובות, דרושים, נאומים",""]]},{"i":41222,"n":"צירלסון, יוסף יצחק מלודמיר","b":"חסיד חב\"ד. אב\"ד לודמיר. הניח חיבור בכת\"י - נדפס בחלקו ב\"אהלי שם\" - חב\"ד כרכים א,ג,ו."},{"i":41223,"n":"צירקל, יהודה מעשיל הכהן מבוריס","f":"זליג","dt":"תרנט - יז סיון","b":"רב בוועוויא(=ואוויה)-תרכ, אלעקסט-תרל\"ה,בוריסוב-תרמ\"א,פלאצק-תרנ\"ה. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":41224,"n":"צירקל, שמואל י. הכהן","f":"זליג","bt":"תקמח","bp":"סלוצק","b":"רב בויסאקי-ליטאוויסק-פלך הורדנא-תרמ."},{"i":41225,"n":"צ'כנוביץ, ירוחם זאב פישל מלומז","k":"בעל הגיוני ירוחם","dt":"תקטו?","b":"רב בלומז'ה, עבר לארה\"ב. חיבר גם \"תורת מאיר\""},{"i":41226,"n":"צכנובסקי, דוד אשר מפאקראי","f":"יצחק צבי","bt":"תרלב","dt":"תרצח - ב תשרי","b":"רב בפאקראי-פלך קובנא-תרסה."},{"i":41227,"n":"צכנובסקי, יצחק צבי","b":"רב-שנת תר\"מ"},{"i":41228,"n":"צלמונה - משפחה","b":"משפחה עשירה ונדיבה בסופיה."},{"i":41229,"n":"צלמונה, אהרן מסופיה","b":"גביר מחכמי סופיה-תקטו, תמך בהדפסת \"פרי הארץ\" עם אחיו שבתי."},{"i":41230,"n":"צלמונה, חיים ג'יליבי מירושלים","f":"יוסף","dt":"תריא - ו שבט","dp":"ירושלים","b":"גביר בירושלים."},{"i":41231,"n":"צלמונה, יוסף מירושלים","dt":"תקס - ג כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":41232,"n":"צלמונה, יוסף מירושלים - א","f":"אהרן (או שלמה)","dt":"תקיא - ה-ח אייר","dp":"ירושלים","b":"זקנו של ר שלמה שלם בעל \"שונה הלכות\" וגדל בביתו לאחר שנתייתם מאביו. גביר מחכמי סופיה, עלה לירושלים. חתם-תקא על כתב שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי. נספד בספר \"דברי שלמה\". (לפי רוזניס שם אביו - שלמה)."},{"i":41233,"n":"צלמונה, יוסף מירושלים - ב","f":"אהרן","dt":"תקס - ב חשון","dp":"ירושלים","b":"פקיד הכוללות בירושלים."},{"i":41234,"n":"צלמונה, יוסף משלוניקי","dt":"תקמב - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מרכבת המשנה\" לר שלמה חלמא-תקמב."},{"i":41235,"n":"צלמונה, יוסף שלמה משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"שו\"ת ר ישראל מברונא-תקנח, \"שמחת יום טוב\" לר יו\"ט אלגזי-תקנד."},{"i":41236,"n":"צלמונה, יצחק משלוניקי","dt":"תרמד","dp":"שלוניקי","b":"רב בשלוניקי. נזכר בהקדמה ל\"מעם לועז\"."},{"i":41237,"n":"צלמונה, שבתי מסופיה","b":"גביר מחכמי סופיה-תקטו, תמך בהדפסת \"פרי הארץ\" עם אחיו אהרן."},{"i":41238,"n":"צלמונה, שלמה משלוניקי","dt":"תרס","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41239,"n":"צלמונה, שמעון מסופיה","f":"יוסף מסופיה וירושלים","b":"גביר מחכמי סופיה, נפטר צעיר בחיי אביו. בניו - הגבירים אהרן ושבתי."},{"i":41240,"n":"צלנגוט, יעקב מגורליץ","b":"מראשי הקהל בגורליץ."},{"i":41241,"n":"צלניק, מרדכי מירושלים","f":"דוד הלוי","bt":"תרעא","bp":"קלווריה","b":"ממיסדי פא\"י, כתב באידישע ארבייטר ודי יודישע שטימע. עלה לירושלים-תרצד. ספר זכרון עליו \"דברי מרדכי\" ירושלים תשנב."},{"i":41242,"n":"צלניק, נחמן מירושלים","f":"מרדכי","k":"בעל עצרת","bt":"תרצה","bp":"ירושלים","dt":"תשסא","dp":"ירושלים","b":"מראשוני תלמידי מדרשיית נועם בפרדס חנה. חתן ר אברהם אלעזר לרמן - חסיד בויאן. חיבר \"עצרת\" ירושלים תשלג."},{"i":41243,"n":"צלניקר, יצחק צבי מירושלים","b":"מראשי כולל הו\"ד בירושלים, חתם-תרמא עם ר יוחנן שלנק ור נחמן נתן קורונל."},{"i":41244,"n":"צלניקר, מיכאל מארה\"ב","f":"אברהם יצחק הי\"ד","bt":"תרעו","bp":"וארשא","b":"תלמיד ביהמ\"ד לרבנים תחכמוני בוארשא, המכון למדעי היהדות בוארשא, ר משה סולוביציק בניו יורק, ועוד. חתן ר יצחק יחיאל ליברמן, ונסמך ממנו ומאת: ר חיים פוזנר, ר יחיאל מאיר בלומנפלד. רב ביכנ\"ס \"בית יעקב\" בוארשא, בזמן השואה ברח לרוסיה, הגיע לרומא-תשו וכיהן כרב, היגר לקנדה-תשח וכיהן כרב במונטריאול."},{"i":41245,"n":"צלניקר-בברויסקר, ניסן","dt":"תשג","b":"מרביץ תורה בביאליסטוק"},{"i":41246,"n":"צלקוביץ, שמואל דוד ממיר","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"בית ועד לחכמים\" - לונדון תרסב, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":41247,"n":"צלר, אברהם מבילקמין","b":"תלמיד ר צבי הירש הורביץ מברודי. רב בבילקמין."},{"i":41248,"n":"צלר, יונה מבוצאץ","f":"יוסף","bt":"תרפח","bp":"בוצאץ","dt":"תשס","b":"ניצל מהשואה, ואחריה תלמיד הרב מסקולן בטשרנוביץ ובוקרשט. עלה לארץ-תשו. חסיד רוזין ומנהל מוסדות סקולן בארץ."},{"i":41249,"n":"צלר, נפתלי מבובוב","f":"צבי ישכר מבובוב","bt":"תרסו","b":"תלמידי ישיבת בובוב. חתן רז\"ו רוטנברג מקראקא."},{"i":41250,"n":"צלר, שלום","k":"ש. שלמון","bp":"גליציה","dt":"תשנב","b":"עלה מארה\"ב לירושלים. חיבר חוברות על מחדלי הציונות בשואה. בחתימת - \"ש. שלמון\"."},{"i":41251,"n":"צלר, שמואל מחאצימירעז","b":"רב בחאצימירעז-תרסה."},{"i":41252,"n":"צמאש, משה מליפאנטו","f":"שלמה בן יעקב","b":"רב בליפאנטו-שנות ה-ש'."},{"i":41253,"n":"צמח","f":"חיים","b":"מגדולי חכמי איטליה-שנת מ'"},{"i":41254,"n":"צמח גאון סורא","f":"חיים","b":"גאון סורא-ד'תרמה (885), בן אחיו של רב נחשון גאון (ואולי אחיו מאמו). בזמנו הופיע אלדד הדני וסיפר על עשרת השבטים, וחכמי קירואן-תונס שאלו את רב צמח אודותיו, והשיב להם שבענין תורה לא ישמעו לאלדד, וישמעו רק לחכמים."},{"i":41255,"n":"צמח גאון סורא","f":"רב יצחק","k":"צמח צדק","b":"גאון סורא-ד'תשמח (988). מצאצאי רב פלטוי גאון פומפדיתא. פתח מחדש את ישיבת סורא שהיתה סגורה 45 שנה, מזמן פטירת ר יוסף גאון בן רב יעקב."},{"i":41256,"n":"צמח גאון פומפדיתא","f":"כפנאי","b":"גאון פומפודיתא-ד'תרצו (936)."},{"i":41257,"n":"צמח גאון פומפדיתא","f":"רב פלטוי גאון","b":"גאון פומפדיתא-ד'תרן (890). זקנו של רב חנניה גאון אביו של רב שרירא גאון. חיבר מילון תלמודי ליהודים מחוץ לבבל שלא שלטו בארמית, הספר היה בשימוש אצל ר אברהם זכות בעל ספר יוחסין - אך אבד."},{"i":41258,"n":"צמח הכהן מג'רבה","f":"סעייד","k":"בעל תורי זהב","bt":"תק","bp":"ג'רבא","b":"מגדולי הרבנים ומקובל בג'רבא. תלמיד ר אהרן פרץ מג'רבא, ר נסים הכהן בעל \"מעשה נסים\", ור יצחק חדאד בעל \"תולדות יצחק\". מתלמידיו ר שאול הכהן ראב\"ד ג'רבא, ר אברהם הכהן בעל \"קנה אברהם\", ר חיים הכהן בעל \"לב שומע\", ר משה זקן מאזוז בעל \"שערי תורה\", ועוד. ר צמח היה בן למשפחה המיוחסת לר ישמעאל כהן גדול ולעזרא הסופר, והמשפחה כונתה \"כהן אברי\"ש\" או \"בארי\"ש\" (ר\"ת: אני בן רבי ישמעאל), והיה ברשותן תעודת יוחסין אולם חלקה נמחקה מרוב השנים. חיבר גם \"מדרש הגדה\" ג'רבא תרעט, ועוד. ?? לא באוצר ??"},{"i":41259,"n":"צמח מוילנא","f":"יעקב מוילנא","b":"הוא או אשתו-נכדי ר מרדכי יפה בעל ה\"לבושים\". דיין בוילנא, חתם-תפח עם ר יהודה בן בנימין, ר משה בן יהודה ליב, ר שמריה בן יוסף א\"ש."},{"i":41260,"n":"צמח מוילנא","f":"מרדכי","dt":"תקמח - כט תמוז","dp":"וילנא","b":"מחכמי וילנא, נפטר צעיר. בנו משה נפטר צעיר ונקבר אצלו."},{"i":41261,"n":"צמח מטבריה","bp":"כנראה צפת","dp":"כנראה טבריה","b":"רב הקהלה בטבריה בשנת רץ"},{"i":41262,"n":"צמח מסלוצק","b":"ראב\"ד בסלוצק-תר\"נ"},{"i":41263,"n":"צמח מפרען","f":"בנימין","b":"אב\"ד פרען-תקן. חתנו - ר משה בן דב בער - אחיהם של ר אברהם יעקב וילנר מוילימפול, ור יצחק זעלקא."},{"i":41264,"n":"צמח נרבוני הזקן","f":"ישראל","dt":"שפ - אחרי","dp":"ירושלים","b":"מחכמי קושטא עד אחרי שנת שעג, מתלמידיו ר חיים בנבנשתי בעל \"כנסת הגדולה\", עלה לצפת והיה מבית דינו של ר יוסף טרני, חתום עמו בשנת שעג, בשנת שפ היה בירושלים."},{"i":41265,"n":"צמח צדוק הכהן","k":"בעל תורי זהב","b":"מגדולי רבני טריפולי"},{"i":41266,"n":"צמח צדק גאון סורא","b":"גאון ישיבת סורא בדור שלפני רב שרירא גאון."},{"i":41267,"n":"צמח, אברהם מירושלים","f":"יעקב","k":"בעל ברית אברהם","dt":"תל","b":"רב בירושלים. נמנה על בית דינו של ר משה בן יונתן גאלאנטי וחתום בפסקים רבים. בשנת תטז הסכים על ספר \"שער אפרים\". חיבר ספר \"ברית אברהם\" החיד\"א ראה את כתב היד הספר לא נדפס. ר חיים אבולעפיה בספרו \"עץ החיים\" מביא חדושים ממנו"},{"i":41268,"n":"צמח, בונם מדוסאט","f":"נתן נטע","b":"רב בדוסאט-תר\"ס"},{"i":41269,"n":"צמח, גדליה מדמשק","f":"חיים","b":"מחכמי דמשק בזמן ה\"בית יוסף\""},{"i":41270,"n":"צמח, דוד מבגדד","f":"סלימן","k":"בעל ורד אל דאודייה","bt":"תרסב","bp":"בגדד","b":"מחכמי בגדד, חוקר שירת ספרד. פרסם מאמרים, קובץ מחקרים בכת\"י."},{"i":41271,"n":"צמח, יוסף שלום מספרד","k":"בעל ברכה ליהודים","b":"חיבר ברכה ליהודים עם תשובות לנוצרים (די רוסי)."},{"i":41272,"n":"צמח, יעקב מצפת ודמשק","f":"חיים","k":"בעל נגיד ומצוה","bt":"של-שמ","bp":"ליסבון","dt":"תכה - אחרי","dp":"ירושלים","b":"מאנוסי פורטוגל, למד רפואה בליסבון, בגיל שלושים עבר לשלוניקי חזר ליהדות-שסח, למד שם תורה ועלה לצפת בשנת שעח. עבר לדמשק ולמד אצל ר שמואל ויטאל. חיבר \"נגיד ומצוה\" קושטא תפו (קיצור מכוונות הארי), ועוד ספרים רבים. ראה את כתבי ר חיים ויטאל והשתמש בהם לסידור ספריו. עבר לירושלים. בהקדמתו לפירוש האידרא מספר על כתבי הקבלה שראה. היה מהלוחמים בשבתי צבי. בנו - ר אברהם בעל \"ברית אברהם\"."},{"i":41273,"n":"צמח, יעקב מקושטא","b":"מחכמי קושטא-שנות ה-ת'-תק', נזכר ב\"כהונת עולם\"."},{"i":41274,"n":"צמח, מנחם תמר","k":"בעל ראשי בשמים","b":"חיבר פירוש לתורה, ולדקדוק בשם \"ראשי בשמים\", ועוד."},{"i":41275,"n":"צמח, רפאל מירושלים","f":"שמעון","b":"רב בירושלים-תקל, חתם על הסכמה בענין ירושות-תקלו. ראה גם: צמח ן שמעון מירושלים."},{"i":41276,"n":"צמח, שמואל מאיפסולה","b":"מחכמי איפסולה-תכז, חתום על ההסכם עם נתן העזתי."},{"i":41277,"n":"צנגר, דוד אלימלך מצאנז וקראקא","f":"יצחק פנחס","k":"אדמור מקראקא","bt":"תרם","bp":"צאנז","dt":"תשך","b":"תלמיד ר שלמה מבובוב. חתן ר יצחק רוטנברג. התישב כאדמור בקראקא-תרסג. בעצת ר בן ציון מבובוב היגר לקנדה-תרצה, וכיהן כאדמור במונטריאול."},{"i":41278,"n":"צנגר, יונה מרזסטוק","dt":"תרל","b":"הגיע מרזסטוק לכהן כרב ביאסלו."},{"i":41279,"n":"צנוע, משה מפטרץ","b":"רב בפטרץ-שץ."},{"i":41280,"n":"צנזור, אהרן הירש","dt":"תרז - כד אייר","b":"דיין בקרקא"},{"i":41281,"n":"צנזור, יוסף יאסקה","dt":"תקצח - טו כסלו","b":"דיין בקרקא"},{"i":41282,"n":"צנזור, יוסף יוסקי","f":"שמעון זאב וולף","dt":"תרז","b":"רב בקראקא-תקצח, גם אחיו ר אהרן הירש רב לצדו. חתם בקנאת ציון נגד אסיפת ברונשטייג."},{"i":41283,"n":"צנזור-וולפגנג, א' צבי","dt":"תרז - כד אדר","b":"מו\"צ בקרקא"},{"i":41284,"n":"צנזר, יהושע מקראקא","f":"זאב","bt":"תרנז","bp":"קראקא","dt":"תשנא","b":"חסיד בלז. מחכמי קראקא. חתן ר יעקב שור מסטרי. עבר לאנטורפן. ניצל מהשואה וברח לצרפת ומשם לפורטוגל וקובה. עבר לארה\"ב עסק במסחר ובלימוד תורה בניו יורק."},{"i":41285,"n":"צנמון, יוסף מדומברובה","b":"רב בדומברובה, קראקא-תרצג."},{"i":41286,"n":"צנמון, יחיאל מיכל מרישא","b":"חסיד צאנז. רב ברישא-תרנב."},{"i":41287,"n":"צנעאני, אברהם הלוי","f":"צדוק","k":"בעל קדש הילולים","b":"משורר, רב בראדע(תימן)-תרע\"א, כתב \"קודש הילולים\""},{"i":41288,"n":"צעדרבוים, נתן מקיצק וארשא","b":"מראשי קהלת וארשא-תקסח."},{"i":41289,"n":"צעוויץ, יהודה ליב מצעוויץ","b":"תלמיד החת\"ס, ור\"מ בנט, ור ברוך פרנקל. דיין בנייטרא כ-35 שנה. בנו - ר קלמן מקרלסבורג."},{"i":41290,"n":"צענר, דוד","b":"תשובה אליו מר יהודה מינץ."},{"i":41291,"n":"צעסיס, משה מגיד מטשודנוב","b":"תלמיד ר יעקב יוסף מפולנאה בעל התולדות. מגיד מישרים בטשודנוב. מתלמידיו ר שמואל השני מקמינקא."},{"i":41292,"n":"צפג', אליהו מתונס","b":"מדייני תונס-תרל\"ז"},{"i":41293,"n":"צפג', דוד מג'רבה","k":"בעל דברי דוד","dt":"תרן","b":"דיין בג'רבה, רב במותסיר-תונס. חיבר \"דברי דוד\" חידושים על הש\"ס"},{"i":41294,"n":"צפג', שלמה מתונס","b":"רב בתונס - בשנות התש', חתם עם רבני תונס ב\"מעשה בית דין\"."},{"i":41295,"n":"צפג', שמואל מתונס","f":"דוד","dt":"תרכז - אחרי","b":"דיין בתונס-תקצב. חתם על תשובות והסכמות."},{"i":41296,"n":"צפדייה, שלמה מחלב (בוואבי)","dt":"תרסד - כח אב","b":"רב בחלב וממלא מקום החכם באשי. חיבר שות, וחדושים בקבלה - בכת\"י. תשובה ממנו ב\"מעשה איש\"."},{"i":41297,"n":"צפח, שמואל","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ - ותשובה על דבריו מר יוסף רוזין - הרוגצובר."},{"i":41298,"n":"צפט ן, מסעוד מפאס","b":"מראשי הקהלה בפאס-שי, וחתם עם הנגיד ר יעקב רותי, ר משה אנפאוי, ר יעקב בן סניור ועוד."},{"i":41299,"n":"צפט ן, שמעון מפאס","b":"מחכמי פאס ומראשי הקהלה-שי, וחתם אז על תקנה בעניני כתובה."},{"i":41300,"n":"צפיג, אברהם מתונס וירושלים","f":"יהודה","k":"בעל עיני אברהם","bp":"תונס","b":"סגי נהור מלידה, בקי בכל התורה, עלה לירושלים בשנת תקלה, נסע לאמשטרדם להדפיס את חדושיו, חיבר ספר: \"עיני אברהם\" אמשטרדם תקמז, במסעותיו נפגש עם ר יחזקאל לנדא שהסכים על ספרו ועם עוד רבנים רבים. בתקסג יצא בשליחות חברון לתורכיה וקבל את התרומות שנאספו משנת תקנד שמאז אל הגיע שליח. בשנת תקסד היה ברודוס."},{"i":41301,"n":"צפייש, משה","b":"חתן בעל \"ברכת טוב\" והגיה את ספר חותנו והוסיף בו מדבריו אך נפטר לפני שסיימו."},{"i":41302,"n":"צפירה, יוסף מתימן וירושלים","f":"סעדיה","k":"בעל כסף צרוף","bt":"תרז","bp":"צנעה (תימן)","dt":"תרצג - יח אדר","dp":"ירושלים","b":"מקובל מחכמי תימן שעלה לירושלים-תרן והיה סופר סת\"ם. השתתף עם אביו בחיבור \"כסף צרוף\"."},{"i":41303,"n":"צפירה, סעדיה מתימן וירושלים","f":"יוסף","k":"בעל כסף צרוף","bt":"תרז","bp":"תנעם-תימן","dt":"תרצג - יח אדר","b":"מקובל מחכמי תימן בירושלים. בנו ר יוסף השתתף עמו בחיבור ספרו \"כסף צרוף\"."},{"i":41304,"n":"צפירה, שלום מתימן","b":"דיין בתנעם-תימן - בתחילת המאה ה-20. עמו בדיינות ר אברהם שחב, ור יוסף קרואני."},{"i":41305,"n":"צפירה, שלמה מתימן","b":"רב בתנעם-תימן-תריט."},{"i":41306,"n":"צפת, אליהו הלוי מסלא-מרוקו","b":"סופר שטרות בסלא-מרוקו-בשנות ה-תק'."},{"i":41307,"n":"צפת, אלעזר הלוי מסאלי","f":"דוד","b":"מחכמי סאלי, חתם על שטר-תפח עם ר שלמה בן אברהם הכהן."},{"i":41308,"n":"צפת, דוד הלוי מאלגיר","f":"שמואל","bp":"מרוקו","dt":"תקי","dp":"צפת","b":"מחכמי מרוקו, מרביץ תורה, הגיע לאלגיר בזמן ר יהודה עייאש וכיהן כרב באלג'יר, עלה לירושלים, טבריה, צפת. חתם על תשובה עם רבני אלגיר ונזכר ב\"בית יהודה\"."},{"i":41309,"n":"צפת, יונה הלוי ממרוקו","b":"מחכמי מרוקו כנראה בסאלי בזמן היעב\"ץ ור שלם ן צור."},{"i":41310,"n":"צפת, שלמה הלוי ממרוקו","b":"מחמכי מרוקו, חתם-תקמח עם ר אברהם בן יוסף."},{"i":41311,"n":"צפת, שמואל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":41312,"n":"צפתמן, משה דוב","bt":"תרמח","dt":"תשא - אב","b":"משגיח רוחני בישיבת פוניבאז'"},{"i":41313,"n":"צציק, זאב דב מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה."},{"i":41314,"n":"צ'צ'קס, שלום מרדכי הלוי","b":"עסק במסחר ובתורה - תשובה אליו ב\"בית יצחק\". כתב חיבור על הרמבם, חוקר וכותב שירים. חתן ר יהודה הכהן פרב. בנו הסופר ש\"י עגנון."},{"i":41315,"n":"צקהוזר, אהרן","dt":"תקעג - כא תשרי","b":"דיין בווילנה"},{"i":41316,"n":"צרבינסקי, ישראל מירושלים","f":"יהושע","b":"מחכמי ירושלים-תרס.."},{"i":41317,"n":"צרואניקאמין, נפתלי מקרסניסטוב","f":"אריה יצחק","bt":"תרלג","b":"תלמיד ר מאיר יחיאל מאוסטרובצא. רב בקאמינקא(=קאמיענקיא)-פלך לברטוב-תרס, קרסנוסטוב(=קראסניסטאוו)-פלך לובלין. נסמך מאת: ר מאיר יחיאל, ר ירחמיאל ישעיה מליקאווא."},{"i":41318,"n":"צרויה ן, שם טוב מספרד וקושטא","b":"מגדולי חכמי ספרד, בגירוש עבר לקושטא-רנב. רב בקושטא - רן-ש, בזמן הרא\"ם. נזכר בהקדמת ספרו של ר שלמה עתיא בפירושו לתהלים."},{"i":41319,"n":"צרויה, יצחק מספרד ופאס","b":"ממגורשי ספרד, הגיע לפאס וכיהן כרב וממתקני התקנות-רנד, יחד עם ר משה אלברהניץ, ר משה ממון, ר בנימין בן יוסף גבאי."},{"i":41320,"n":"צרור, אברהם מחברון","dt":"תקא - כא כסלו","dp":"האג-הולנד","b":"בשליחות חברון-תצט באירופה, באגרת השליחות של ר אברהם גדיליה נזכרת שליחותו של ר אברהם."},{"i":41321,"n":"צרור, אברהם מקוס","b":"ראש הקהל בקוס(=איסטאנקיואי)-שנות ה-ת'."},{"i":41322,"n":"צרור, אליהו מאלגיר","bt":"תרי","dt":"תרף - בערך","b":"מחכמי אלגיר. חיבר סיפור מעללי העכו\"ם ביהודי אלגיר תרם-תרס בשם \"קצאת חרבאן אדזאייר\"."},{"i":41323,"n":"צרור, אליהו מטריפולי","bt":"תקם","dt":"תרי - בערך","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":41324,"n":"צרור, אשתרוק מאלגיר","f":"שלמה","b":"נזכר בשו\"ת הרשב\"ש."},{"i":41325,"n":"צרור, יוסף מאלגיר","f":"יעקב","dt":"תקטו","b":"דיין מחכמי אלגיר ב\"בית דינא רבא\", וראש ישיבה, וספרא רבא. השיב תשובות רבות. חתם על פסק דין-תקא עם ר יהודה עייאש. חיבר הקדמה ל\"פרי צדיק\", ועוד."},{"i":41326,"n":"צרור, יעקב מאלגיר","dt":"תקה","b":"דיין באלגיר ומכונה \"הגאון\". חתם עם רבני העיר על קבלת עדות, שטר עגונה, על חרם כנגד נחמיה חיון.בנו - ר יוסף."},{"i":41327,"n":"צרור, יצחק","b":"מחכמי המגרב. חיבר סדר תנאים ואמוראים."},{"i":41328,"n":"צרור, יצחק מטריפולי","k":"בעל צרור המור - כת\"י","bt":"תק","dt":"תקע - בערך","b":"רב וראש קהלת טריפולי-תקנג. חיבר חדושי תורה בשם \"צרור המור\"."},{"i":41329,"n":"צרור, ישועה מאלגיר","f":"שלמה בן טוביה","bt":"ת","dt":"תע","b":"רב באלגיר(=דזאייר) ודרשן, מדרשותיו בחיבור בכת\"י - באוסף גינצבורג במוסקבה. נזכר ב\"וזאת ליהודה\"."},{"i":41330,"n":"צרור, מרדכי מאלגיר","f":"שלמה","k":"בעל קול ששון","bt":"תר - בערך","dt":"תרע - בערך","b":"דיין באלגיר אצל ר שמואל צרור. הו\"ל \"קול ששון\" אלגיר תרמה. מתורתו ב\"זה השלחן\" לר אליהו גיג'. הו\"ל הגדה מנהג אלגיר - ליוורנו תרמו. ?? לא באוצר ??"},{"i":41331,"n":"צרור, משה מאלגיר","bt":"תך - בערך","dt":"תץ - בערך","b":"מחכמי בית הכנסת של כהנים באלגיר, ונזכר ב\"פרי צדיק\". (ידוע על בתי כנסת של כהנים בג'רבא ובדברו-מרוקו, בפאס-מרוקו, וכאן המקור לביכ\"נ באלגיר - היו ידיעות על בתי כנסת כהנים גם בהוניין-אלגיר, תלמסאן)."},{"i":41332,"n":"צרור, משה מאלגיר","f":"אפרים","bt":"שע","dt":"תס - בערך","b":"רב וסופר באלגיר. העתיק את שו\"ת הרשב\"ץ-תנה, וסידור תפלה מנהג אלגיר, תכנן לעלות לארץ ולא ידוע אם אכן עלה."},{"i":41333,"n":"צרור, משה מאלגיר","dt":"תקסב - כב תשרי","dp":"ירושלים","b":"רב באלגיר, עלה לירושלים. נזכר ב\"חלקת מחוקק\"."},{"i":41334,"n":"צרור, ציון מטריפולי","dt":"תרעו","b":"רב בטריפולי, מיסד ישיבת \"יגדיל תורה\" לבני עניים, ועמד בראשה כ-24 שנה - עד פטירתו. עליו ב\"סיני\" תשג."},{"i":41335,"n":"צרור, רפאל ידידיה שלמה מאלג'יר","f":"ישועה בן שלמה בן טוב","k":"בעל פרי צדיק","bt":"תמא","dt":"תצח","b":"רב ורופא באלג'יר. מצאצאי הרמב\"ן, הרשב\"ץ, ר אברהם ן טוואה. משומרי מורשת אלג'יר ואסר לשנות ממנהג אלג'יר, חיבר דיני מנהגי ק\"ק אלג'יר, עם הקדמה מתלמידו ר יהודה עייאש. עוד מתלמידיו - ר מכלוף עמר, ר\"מ אלפאסי, ועוד. חיבר הקדמה לשו\"ת התשב\"ץ, קיצור שו\"ע - ואבד, מתורתו ב\"פרי צדיק\" ליוורנו תקח. היה בקי בתולדות החזנים באלגיר לדורותיהם.","bk":[["פרי צדיק [על שו\"ע, ושו\"ת] (מהרי\"ש)",""]]},{"i":41336,"n":"צרור, שלמה מאלג'יר - א","bt":"של - בערך","dt":"ת - בערך","b":"תלמיד \"ישיבת הרב אביגדור\". רב באלג'יר, תונס, ועמד בקשרי שו\"ת עם חכמי מרוקו ותונס. מתשובותיו ב\"החוט המשולש\", הראשון מחכמי אלג'יר שראה את ספרי רבני צפת, והביא בתשובותיו מדברי ר יוסף קארו."},{"i":41337,"n":"צרור, שלמה מאלג'יר - ב","f":"טוביה","dt":"תכד","b":"רב באלג'יר. נזכר ב\"פרי צדיק. זקנו של ר רפאל ידידיה שלמה צרור רבה של אלג'יר. נזכר ב\"מצבות אלגיר\" לר יצחק בלוך."},{"i":41338,"n":"צרור, שלמה מאלגיר - ג","bt":"תך","dt":"תץ - בערך","b":"רב באלגיר. חתם עם רבני אלגיר על החרם כנגד נחמיה חייא חיון, ועל פס\"ד ב\"פרי צדיק\"."},{"i":41339,"n":"צרור, שמואל מאלגיר","f":"יהודה","bt":"תרכב","dt":"תרצז","b":"רב באלגיר-תרמו כ-50 שנה ודיין ראשון-תרע. חתם ראשון בפסק דין \"קול ריחים\" אלגיר תרעב (עיקר הפסק מהשליח ר בן ציון אלקלעי)."},{"i":41340,"n":"צרינו, אברהם מאזמיר","b":"גזבר \"חברת יתומות\" של קהלת פורטוגל באזמיר-תמח."},{"i":41341,"n":"צ'רנוביץ חיים","bt":"1870","dt":"ה'תשט 1949","bk":[["קצור התלמוד",""],["קצור התלמוד מסכת ברכות",""],["תולדות ההלכה",""]]},{"i":41342,"n":"צ'רני, אהרן ראובן","k":"בעל רצוף אהבה","dt":"תשכח","b":"דרשן,ר\"מ בסובאלק, בירמינגהם, ניו דזורדש'-ארה\"ב. חיבר גם \"חזיונת הסבא\"."},{"i":41343,"n":"צ'רני, ברוך ממאנעסטרישט","f":"אלעזר","bt":"תרלב","b":"רב במנסטריץ(=מאנעסטרישט)-פלך קיוב-תרנה על מקום אבותיו (שכיהנו בעיר כמה דורות)."},{"i":41344,"n":"צ'רני, דב בר ממנוסטרישץ","f":"שלמה פישל ממונסטרישץ","b":"חתן ר יצחק אברהם הויסינסקי מסטאויטש. רב במניסטריטש(=מנוסטרישץ) על מקום אביו."},{"i":41345,"n":"צ'רני, דוד מאזרא","f":"יהושע","k":"בעל דברי דוד","bt":"תרז","b":"נכד ר דוד ממיר. רב באזרא-תרן."},{"i":41346,"n":"צ'רני, חיים יצחק","dt":"תשג","b":"רבב בקראסנא"},{"i":41347,"n":"צ'רני, יוסף יהודה","f":"יעקב","k":"בעל המסעות בארץ קוקז","bt":"תקצז","bp":"מינסק","b":"נוסע וחוקר קהלות ישראל באסיה המרכזית והקווקז."},{"i":41348,"n":"צ'רני, יצחק ברוך","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":41349,"n":"צ'רני, ישעיהו","k":"בעל דרכי הוראת המקרא","bt":"1879","bp":"וילנא","dt":"1932","b":"תלמיד ביהמ\"ד למורים. למד כימיה בברלין. מורה בגרודנא. מנהל גימנסיה \"תרבות\" בחרקוב. פרסם מאמרים בנושאי חינוך והיסטוריה.. חיבר גם \"לתולדות החינוך בישראל\" - וילנא תרפט."},{"i":41350,"n":"צ'רני, מרדכי ליב מבאבר","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":41351,"n":"צ'רני, משה מבאקו","f":"אברהם בן שלום","b":"בן למשפחת השחורים במיר. תלמיד ישיבות ליטא. חתן ר שלמה זלמן אלטשול מטשאווס. רב (או נושא משרה כבודה) בבאקו."},{"i":41352,"n":"צ'רני, משה מדוקאר","dt":"תרסא - ל חשון","b":"רב בדוקאר-תרלט, וחתנו ר ניסן טלושקין על מקומו אחריו."},{"i":41353,"n":"צ'רניאק, ברוך","f":"מרדכי יהודה טשרניאק","bt":"תרלה","dt":"תרעה","b":"רב בסטנילבצ'ק"},{"i":41354,"n":"צ'רניאק, ישעיה גרשון מחסלביץ","b":"גביר תלמיד חכם בחסאלביץ. מחותן עם ר בנימין לוין מויאזמא."},{"i":41355,"n":"צ'רניאק, ישראל","b":"מרביץ תורה בריגה-תרפ\"ה"},{"i":41356,"n":"צ'רניאק, ישראל יעקב","dt":"תשג","b":"רב בוילקי"},{"i":41357,"n":"צ'רניאק, ישראל יעקב מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":41358,"n":"צ'רניאק, מרדכי יהודה","b":"רב בסטניסלבצ'יק-תר\"מ"},{"i":41359,"n":"צ'רניאק, שלום שכנא ממאציוב","k":"בעל משמרת שלום","bt":"ה'תרכא","dt":"תרצח","b":"רב בפיטשאיוב-תרנ\"ד,בערימליא,מאציוב. פרסם מאמרים ב\"אוצר החיים\" - זאמושט תרצז.","bk":[["משמרת שלום [על פמ\"ג]",""],["חיים וברכה",""]]},{"i":41360,"n":"צרפתי, אבנר ישראל","f":"וידאל הצרפתי","dt":"תרצג","b":"דיין באספי-תרצ\"א"},{"i":41361,"n":"צרפתי, אבנר ישראל מפאס -האי\"ש","f":"וידאל הצרפתי","k":"בעל קיצור משכנות הרו","bt":"תקפז-כא שבט","bp":"פאס","dt":"תרמד - ח תשרי","b":"רב ומ\"צ בפאס, מחכמי פאס, בעל ספריה גדולה ובה מאות כתבי יד מהראשונים. מתלמידיו ר שלמה ן דנאן בעל \"אשר לשלמה\". כתב \"קיצור משכנות הרועים\"."},{"i":41362,"n":"צרפתי, אברהם מאלגיר","f":"שלמה","bt":"רס","dt":"של - בערך","b":"רב ומשורר באלגיר. פיוטים ממנו לפורים שני - ד חשון לכבוד מפלת הצי הספרדי מול חופי אלגיר - ונדפסו בקרוב\"ץ אלגיר. על שמו ביכ\"נ הנקרא \"בית כנסת צרפתי\" באלגיר."},{"i":41363,"n":"צרפתי, אברהם מטולידו","b":"מרבני טולידו"},{"i":41364,"n":"צרפתי, אברהם מירושלים","b":"רב ורופא מתומכי ר שלמה מולכו. עלה לירושלים. נזכר בשו\"ת הרא\"ם."},{"i":41365,"n":"צרפתי, אברהם מנפולי","b":"רב בנפולי-רצג. עסק בפדיון שבויים שנשבו במלחמת ונציה תורכיה-רצב."},{"i":41366,"n":"צרפתי, אברהם מסוס","b":"רב בסוס-מרוקו בזמן הריב\"ש. (אולי הוא גר הצדק הנזכר בתשב\"ץ)."},{"i":41367,"n":"צרפתי, אברהם מפאס","f":"יוסף","dt":"תפב - כו חשון","b":"רב בפאס"},{"i":41368,"n":"צרפתי, אברהם מפאס","f":"שמואל","b":"רב בפאס"},{"i":41369,"n":"צרפתי, אברהם מפאס","b":"רב בפאס, תשובה ממנו-שלט בענין טריפה ומכונה \"הבודק הגדול\"."},{"i":41370,"n":"צרפתי, אברהם מפאס","b":"ממגורשי צרפת, הגיע לפאס, נזכר בספר קרובו ר אליהו הצרפתי-ה'צח כפייטן."},{"i":41371,"n":"צרפתי, אברהם משלוניקי","f":"יצחק או יוסף","dt":"תפב - יז שבט","dp":"אדרינופול","b":"רב בשלוניקי, אדרינופולי על מקום אביו (ולפי רוזניס על מקום אחיו - ר יצחק, ושם אביו ר יוסף) וחתנו - ר אברהם גירון על מקומו אחריו. חתם-תסג על זכרון עדות, הניח קובץ דרשות בכת\"י ונשרפו-תרסה. חתנו גם - ר אברהם דנון."},{"i":41372,"n":"צרפתי, אהרן מפאס","b":"בודק מומחה מחכמי פאס-שעז."},{"i":41373,"n":"צרפתי, אהרן מפאס וסאלי","f":"אברהם או יצחק","k":"בעל משגב אמהות","b":"נכד ר וידאל הצרפתי מפאס. תלמיד ר אהרן אסבעוני, מחכמי פאס, דיין בסאלי-מרוקו עם ר שלמה הכהן ור שמואל קארו - והסכימו-תצא על ספר חפץ לר חיים ן עטר, חתם עם ר שמואל אזאווי על פס\"ד. חיבר \"משגב אמהות\" נדפס בסוף \"צוף דבש\" לזקנו ר וידאל צרפתי. בנו - ר יוסף. אחיו - ר שמואל מפאס."},{"i":41374,"n":"צרפתי, אורי מצפת","f":"ישראל","b":"מחכמי צפת, בשנת שפא חתם על ההזמנה לר ישכר בר איילינבורג."},{"i":41375,"n":"צרפתי, אליהו מטריפולי","dt":"תרעח","b":"רב בטריפולי. נזכר אצל ר גבריאל רוקח."},{"i":41376,"n":"צרפתי, אליהו מפאס","f":"יוסף","k":"בעל קול אליהו","bt":"תעה","bp":"פאס","dt":"תקסה - כו אלול","b":"תלמיד ה\"אור החיים\", ר שמואל אלבאז, ור יהודה ן עטר. נסמך מאת ר יעקב ן צור-היעב\"ץ. לפי טולדנו נפלה טעות ולא היה תלמיד בעל אור החיים אלא של ר יהודה ן עטר. רב בטיטואן-תק, דיין בפאס-תקי אצל היעב\"ץ, יצא לגלות בבאלזאוויא-תקלח. מרביץ תורה, דרשן, חיבר גם \"אליה זוטא\", \"איל מילואים\", ועוד. מתשובותיו בספרי חכמי דורו. אחד מחמשת הדיינים שכונו בית דין של חמש בפאס (יחד עם ר שאול שמואל דנון, ר אפרים בן אברהם מונסונייגו, ר רפאל עובד בן יעקב ן צור, ר אליהו בן יוסף הצרפתי). מתלמידיו: ר שאול אביטבול, ר רפאל אהרן מונסונייגו. מבניו: ר ישראל יעקב, ר רפאל מנחם, חתנו - ר שמואל ן דנאן. קברו הועבר (כשהשלטונות פינו את בית הקברות הישן) ונקבר בשנית ליד סוליקה הצדקת. קונטרס שירים לזכרו ולזכר בנו יעקב מאת ר שלמה חלואה."},{"i":41377,"n":"צרפתי, אליהו משלוניקי","dt":"שי - לפני","b":"רופא בשלוניקי."},{"i":41378,"n":"צרפתי, אליעזר משלוניקי","dt":"שי","b":"משורר מחכמי שלוניקי."},{"i":41379,"n":"צרפתי, בכור"},{"i":41380,"n":"צרפתי, בן ציון","b":"מחכמי ישיבת \"בית אל\", שד\"ר למצרים-תרכ\"ה. מזקני רבני ויניציא"},{"i":41381,"n":"צרפתי, בן ציון מונציה","dt":"שע - ד סיון","b":"רב בונציה. פסק בענין המקוה ברוויגו, נזכר ב\"נחלת יעקב\" לר\"י הלפרין, וב\"משבית מלחמות\", ו\"פלגי מים\"."},{"i":41382,"n":"צרפתי, הלל ממרוקו","b":"מו\"צ במרוקו, חתם על פס\"ד-תיד ונזכר ב\"משפט וצבי\"."},{"i":41383,"n":"צרפתי, וידאל מפאס - א","f":"יצחק","b":"מגולי ספרד, הגיע לפאס."},{"i":41384,"n":"צרפתי, וידאל מפאס - ב - סיניור","f":"יצחק הצרפתי","k":"בעל צוף דבש","bt":"ש","bp":"פאס","dt":"שעט","b":"מכונה ר וידאל הצרפתי השני. אב\"ד בפאס, בעל פלאות, משורר, פייטן, חיבר \"צוף דבש\" על התורה, ועוד."},{"i":41385,"n":"צרפתי, וידאל מפאס - ג","f":"יצחק?","bt":"שצא-כז אלול","bp":"פאס","dt":"תסד - יד כסליו","dp":"פאס","b":"אב\"ד פאס-תמט על מקום ר יהודה עוזיאל, חתם עם ר מנחם סירירו, ר סעדיה ן דנאן. חיבר ספר \"המפתח\", ופסקי דינים בכת\"י (ואבדו). לזכרו חיברו בפאס קינות רבות."},{"i":41386,"n":"צרפתי, וידאל מפאס - ד","bt":"תקנז","dt":"תרטז - ח אב","b":"מו\"ץ בפאס. חיבר פסקים ושו\"ת - בכת\"י. בנו - ר אבנר ישראל הצרפתי."},{"i":41387,"n":"צרפתי, וידאל מפאס - ה","f":"אבנר ישראל - אי\"ש","bt":"תרכב","dt":"תרפא - כג טבת","b":"מו\"ץ בפאס, ראב\"ד מטעם הממשלה. הניח פסקי דינים - בכת\"י. בניו: ר אבנר ישראל,"},{"i":41388,"n":"צרפתי, חיים אברהם מפאס","b":"מו\"ץ בפאס, חתם-תקצו עם רא\"ם, ר יעקב סירירו, ר יעקב ן צור השני."},{"i":41389,"n":"צרפתי, חיים יוסף גי'יליבי","dt":"תקצז","dp":"צפת","b":"מחכמי צפת, בשנת תקפט חתם על כתב שליחות ר בצלאל בן אריה ליב הכהן, בשנת תקע חתם עם גדולי חברון על כתב שליחות לר אברהם בן חסון. נספה ברעש בצפת."},{"i":41390,"n":"צרפתי, חיים מאדרינופול ושלוניק","dt":"תלח - יח סיון","dp":"שלוניקי?","b":"רב באדרינופול, עבר לשלוניקי. בנו - ר יוסף מאדרינופול."},{"i":41391,"n":"צרפתי, חיים מירושלים","b":"מחכמי ירושלים, כנראה הוא המוזכר במכתב ר יצחק חילו משנת צד כאחד מראשי הקהל שבא מצרפת."},{"i":41392,"n":"צרפתי, חיים ממרוקו","dt":"תר - כח שבט","b":"מגדולי חכמי פאס במרוקו"},{"i":41393,"n":"צרפתי, חיים משלוניקי","dt":"תסב","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":41394,"n":"צרפתי, טוביה מארץ ישראל","b":"רב בארץ ישראל-שנות ה-שן' בזמן ר נפתלי אשכנזי המביאו בספרו \"אמרי שפר\"."},{"i":41395,"n":"צרפתי, יהודה ממראקש","b":"רב במראקש, חתם על פס\"ד-תקמז. בנו - ר מרדכי."},{"i":41396,"n":"צרפתי, יהודה ממרוקו","b":"מחכמי מרוקו-שנות ה-ש'. נזכר בתשובה של ר שמואל קוריאט לר שמואל ן דנאן."},{"i":41397,"n":"צרפתי, יהודה משלוניקי","f":"יעקב מאראגון-שלוניקי","b":"חזן קהלת אראגון בשלוניקי-שב על מקום אביו (שהיה הרב) ועמו נבחר כרב הקהלה ר יצחק עראמה, רב באדרינופול?"},{"i":41398,"n":"צרפתי, יהושע מפדובה","dp":"פדובה","b":"רב ורופא שגורש מצרפת בשנת קנה והגיע לפדובה."},{"i":41399,"n":"צרפתי, יהושע משלוניקי","dt":"רצג - ח אלול","dp":"שלוניקי","b":"מחכמי שלוניקי, אולי חותנו של ר משה אלמושנינו."},{"i":41400,"n":"צרפתי, יודא יהודה","b":"נזכר אצל מהר\"ם פאדובה."},{"i":41401,"n":"צרפתי, יוסף ישראל מקושטא","b":"מדפיס בקושטא-רעט עם ר משה חליבוי ומיליאריבי."},{"i":41402,"n":"צרפתי, יוסף מאדריאנופול","f":"חיים","k":"בעל יד יוסף","bt":"שס","dp":"ירושלים","b":"תלמיד ר שלמה הלוי (שהיה גם רבו של ר\"ש פלורנטין בעל \"לב שלמה\"). מחכמי אדרינופול רב ודרשן בזמן בעל \"שבט מוסר\", בשנת שס ועלה לירושלים. חיבר \"יד יוסף\" ונציה שעו , \"בן יוסף\", \"ראש יוסף\" ועוד בכתב יד."},{"i":41403,"n":"צרפתי, יוסף מאיטליה","f":"שמואל","b":"רופא מחכמי איטליה, היה רופאו של האפיפיור יוליוס השני, מורה לשפות עתיקות ובין תלמידיו המשפטן הפרופ' תיזיאוס אמברוזיוס מבולוניה."},{"i":41404,"n":"צרפתי, יוסף מסאלי-מרוקו","f":"אהרן מסאלי","b":"מחכמי מרוקו, העתיק קונטרס דיני טריפות."},{"i":41405,"n":"צרפתי, יוסף מסידרוקאפסי","b":"רב בסידרוקאפסי-שן."},{"i":41406,"n":"צרפתי, יוסף מפאס","f":"יצחק","k":"בעל קיצור דיני טריפו","bt":"תב","dt":"תעח - כז חשון","b":"רב בפאס. בנו - ר אליהו, ולפי טולדנו בנו - ר אברהם."},{"i":41407,"n":"צרפתי, יוסף משלוניקי - א","dt":"שטו - ח תשרי","dp":"שלוניקי","b":"חתן ר שמואל די מדינה. מחכמי שלוניקי. נפטר צעיר."},{"i":41408,"n":"צרפתי, יוסף משלוניקי - ב","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה הלוי הבחור, ר מרדכי קלעי."},{"i":41409,"n":"צרפתי, יעקב מוירונה","f":"יצחק","b":"רב בוירונה. חתם בענין המקוה ברויגו-שסא ב\"פלגי מים\"."},{"i":41410,"n":"צרפתי, יעקב מצרפת","f":"שלמה","k":"בעל משכנות יעקב","b":"מחכמי צרפת-קמח. חיבר \"משכנות יעקב\" בשלשה חלקים ובסופו \"אבל רבתי\" על קרוביו שנפטרו במגפה-קמח בצרפת."},{"i":41411,"n":"צרפתי, יעקב משלוניקי","dt":"שא-ב - בערך","b":"רב קהלת אראגון בשלוניקי על מקום ר מאיר עראמה-רפב-שב. חתם על ה\"הסכמות\"-רפט ורצג. בנו - ר יהודה על מקומו אחריו יחד עם ר מאיר עראמה-נכד ר מאיר עראמה שהיה רבה של הקהלה."},{"i":41412,"n":"צרפתי, יצחק הזקן","b":"נזכר בספר דרשות של ר חיים חברייא ממצרים."},{"i":41413,"n":"צרפתי, יצחק הנגיד מפאס - ב","b":"חתם על הסכמה-תג, ותנח, וחתם-תך עם ר שמואל סירירו ור סעדיה ן דנאן, ור עמנואל סירירו, חתם גם עם ר אברהם עוזיאל, ר חיים ביבאס. (לא סביר שחתם בהפרש של 50 שנה ואולי הוא חכם אחר באותו השם? ראה גם ר יצחק בן יוסף צרפתי)"},{"i":41414,"n":"צרפתי, יצחק מאדרינופול","f":"שלמה","bp":"אשכנז","b":"הגיע מאשכנז והתישב באדרינופול או קושטא, והיה מגדולי חכמיה. שלח אגרת-קץ \"קול קורא\" ליהודי אשכנז לבוא לתוגרמה."},{"i":41415,"n":"צרפתי, יצחק מאדרינופול ושלוניק","f":"יוסף","dt":"תפב - יז שבט","dp":"ירושלים","b":"רב באדרינופול-תם ואחיו ר אברהם על מקומו אחריו, אחר כך רב בשלוניקי, עלה לירושלים. נספד על ידי ר יוסף דוד בעל \"צמח דוד\", ונדפס בספר \"יקרא דשכבי\", וכן בספר \"משכנות יעקב\". חתניו - ר אברהם דאנון, ר אברהם גירון. לפני רוזניס - חתנו-ר אברהם גירון על מקומו אחריו ובגלל מחלוקת נבחר ר מנחם בן יצחק אשכנזי על מקומו."},{"i":41416,"n":"צרפתי, יצחק ממרוקו - ג","f":"יוסף","dt":"תצז - ניסן","dp":"מרוקו","b":"רב במרוקו. הספידו אחיו ר אליהו הצרפתי ב\"נער בוכה\". נזכר ב\"מלכי רבנן\". אולי הוא שחתם על הסכמת רבני פאס-תנח עם ר מנחם סירירו וחבריו."},{"i":41417,"n":"צרפתי, יצחק מסאלי-מרוקו","dt":"תץ","b":"מו\"ץ בסאלי עם ר שלמה הכהן ור שמואל קארו, חתם על פס\"ד-תפו, היה מחלוקת בינו לבין רבני מכנאס."},{"i":41418,"n":"צרפתי, יצחק מפאס - א -אדרינופו","f":"וידאל","k":"בעל מאסף לכל המחנות","b":"מחכמי מרוקו-רנב ולפי נר המערב-שלה, (ולפי רוזניס מחכמי אדרינופול-שנות ה-ש'). חיבר גם מפתח תנחומא ופסיקתא ומדרש רבה, ועוד. מתורתו ב\"צוף דבש\" ו\"מגלת סתרים\". (כנראה שהמדובר לפחות ב-2 חכמים שונים ואולי יותר)"},{"i":41419,"n":"צרפתי, יצחק מפאס - ב","f":"וידאל","dt":"תכ","dp":"פאס","b":"רב בפאס. חתם עם היעב\"ץ-שסג. נגיד הקהלה-תט. חיבר מפתח לחמש מגילות-תב. חדושים ממנו בספרי אביו. (יתכן והוא המחבר \"תולדות יצחק\" - ירושלים תשנו)."},{"i":41420,"n":"צרפתי, יצחק מפאס - ב","dt":"תקכו - יא תשרי","b":"רב בפאס. חיבר דרושים לנפטרים - בכת\"י. נספד מאת ר רפאל אהרן מונסונייגו."},{"i":41421,"n":"צרפתי, יצחק מקושטא","b":"רב בקושטא-שס."},{"i":41422,"n":"צרפתי, יצחק משלוניקי","dt":"תם","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":41423,"n":"צרפתי, ישראל יעקב מפאס","f":"אליהו מפאס","bp":"מרוקו","dt":"תקפב-ו -יב תשרי","b":"מו\"ץ בפאס. עשיר ומקורב למלכות. אחיו של ר רפאל מנחם. בנו - ר רפאל מנחם ונכד ר וידאל הצרפתי הרביעי."},{"i":41424,"n":"צרפתי, מאיר הכהן","dt":"כג","b":"מגדולי חכמי נרבונה בטולידו"},{"i":41425,"n":"צרפתי, מרדכי ממראקש","dt":"תרמה","b":"תלמיד ר משה רוזיליו בעל \"קול מבשר\". מו\"ץ במראקש-תרלב."},{"i":41426,"n":"צרפתי, מרדכי ממראקש","b":"מו\"ץ במראקש, חתם-תרמא על פס\"ד."},{"i":41427,"n":"צרפתי, משה","b":"נכדו של ר שמואל אלגזי. מוזכר ב\"תולדות אדם קטן\"."},{"i":41428,"n":"צרפתי, משה ממרוקו וירושלים","b":"ממשפחת ר צמח צרפתי ועלה לירושלים. מחכמי ירושלים, הסכים על \"דבר שמואל\" לר שמואל צרפתי-תנז."},{"i":41429,"n":"צרפתי, נחמיה מטיריא","b":"רב בטיריא-ש'-ת' - בזמן ר גבריאל גליקו."},{"i":41430,"n":"צרפתי, נתנאל אלישיב מאמשטרדם","k":"בעל אר\"ש חידה","b":"מחכמי אמשטרדם. חתנו - ר דוד בן רפאל מילדולה מאמשטרדם. הו\"ל ספר חתנו - \"מועד דוד\", ועוד. מגיה של \"תקון סופרים\" אמשטרדם תקכז. חיבר שיר וחידה בשם \"אר\"ש חידה\" אמשטרדם תקה."},{"i":41431,"n":"צרפתי, צמח מאלגיר","bt":"תרל","dt":"תשה","b":"מחכמי קצמטינא, עורך לוח שנה בשם \"לוח יוסף\" בשנים - תרע-תשה. הו\"ל סדורים ומחזורים \"מנחת יהודה\" סוסה תרפו-צד."},{"i":41432,"n":"צרפתי, צמח מתונס - ב","b":"מרביץ תורה,רב הכולל בתוניס-תק\"נ"},{"i":41433,"n":"צרפתי, צמח מתונס וירושלים","k":"מהרצ\"ץ","dt":"תעז - יד אדר","dp":"ירושלים","b":"מגדולי רבני תונס, פגש את החיד\"א בשליחותו שם והחיד\"א כותב עליו כי קודם לזמנו לא למדו תוספות בתונס והוא חידש לימוד תוספות ומהרש\"א בעיון. היה רבו של יצחק לומברזו בעל \"זרע אברהם\" אב\"ד תונס ושל ר אברהם טייב. ישב שנים בדמשק ועלה לירושלים והיה מחכמי \"בית יעקב פיררה\". תורתו נדפסה בספרי חכמי דורו. נספד ב\"זרע יצחק\" לר יצחק לומברזו."},{"i":41434,"n":"צרפתי, רפאל","k":"בעל מנחת פתים"},{"i":41435,"n":"צרפתי, רפאל ממרוקו","b":"רב במאזאגן ג'דידא-מרוקו - תשה."},{"i":41436,"n":"צרפתי, רפאל מנחם ממרוקו","f":"אליהו","dt":"תרג - ט תשרי","dp":"מרוקו","b":"רב בפאס. ובעל מינוי שררה מטעם המלכות."},{"i":41437,"n":"צרפתי, רפאל מפדובה","f":"יהושע","bp":"פדובה","dt":"שיד - ז פסח","dp":"פדובה","b":"רב ורופא בפדובה. ממשפחה שגורשה מצרפת-קנה."},{"i":41438,"n":"צרפתי, שלם מצפת","f":"שלמה","b":"מחכמי צפת, חתם-תקכג על כתב שליחות ר אשר קוריאט."},{"i":41439,"n":"צרפתי, שלמה","b":"מגדולי חכמי דורו-ק\"פ"},{"i":41440,"n":"צרפתי, שלמה","bp":"פאס","b":"מחכמי ארץ ישראל עלה בשנת תמו. קובץ דרשות שלו בכתב יד (פרמא)."},{"i":41441,"n":"צרפתי, שלמה מאבילונא-אלבניה","b":"מחכמי אבילונה-אלבניה וחזן בק\"ק הפולייסים."},{"i":41442,"n":"צרפתי, שלמה מאלגיר","bt":"רץ","dt":"שס - בערך","b":"רב בלמדייא, נזכר ב\"חוט המשולש\"."},{"i":41443,"n":"צרפתי, שלמה מניקופול","b":"רב בניקופול-שנות ה-ש'."},{"i":41444,"n":"צרפתי, שלמה מסופיה","b":"מראשי הקהלה הספרדית בסופיה - בדור שלאחר הגירוש."},{"i":41445,"n":"צרפתי, שלמה מספרד","b":"רב במיורקה-ספרד, התכתב עם הריב\"ש המזכירו בספרו."},{"i":41446,"n":"צרפתי, שמואל מאריף-מרוקו","f":"שם טוב","b":"מחכמי אריף-מרוקו, חתם-תקעח."},{"i":41447,"n":"צרפתי, שמואל מטיטואן","b":"מחכמי טיטואן, חתם-תפט על פס\"ד עם ר אברהם אלמושנינו."},{"i":41448,"n":"צרפתי, שמואל מפאס-מרוקו","f":"אברהם","k":"בעל פתח עינים","bt":"תכ","dt":"תעג-ז - ב אב","dp":"פאס","b":"נכד ר וידאל צרפתי. רב ודיין בפאס עם ר יהודה ן עטר והיעב\"ץ. חיבר גם \"דברי שמואל\" אמשטרדם תנז, \"ערוגת הבושם\", ועוד."},{"i":41449,"n":"צרפתי, שמואל מצפת","f":"יצחק","b":"מחכמי צפת. חתם-שפא על הזמנה לר ישכר בר איילנבורג לכהן כרבה של צפת."},{"i":41450,"n":"צרפתי, שמואל משלוניקי","b":"מחכמי שלוניקי-שנות הר'."},{"i":41451,"n":"צרפתי-טרוויש - משפחה","b":"חלק מצאצאי רש\"י כינו עצמם על שם עירו, ונקראו גם צרפתי - חלקם גלה מצרפת-סו לאיטליה ומקומות נוספים."},{"i":41452,"n":"צרפתי-טרוויש, אברהם מירושלי","b":"רב בירושלים-שנות ה-ש'."},{"i":41453,"n":"צרפתי-טרוויש, מתתיה מטיווה","f":"יעקב","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":41454,"n":"צשינובר, יהודה ליב מזולוקא","bt":"תרטז","bp":"נרול","dt":"תרצב","b":"חתן ר משולם זלמן לורברבוים מזולוקא. חסיד בלז. רב בזולוקוא. כתביו אבדו."}];
